@SubscribeEvent
    public static void onClientTick(TickEvent.ClientTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }

