@Override
    public void tickServer() {
        super.tickServer();

        discharging = false;
        charging = false;

        chargingStackSynced = itemHandler.getStackInSlot(CHARGE_INVENTORY_INDEX);

        int airToTransfer = (int) (PneumaticValues.CHARGING_STATION_CHARGE_RATE * getSpeedMultiplierFromUpgrades());

        for (IAirHandler itemAirHandler : findChargeable()) {
            float itemPressure = itemAirHandler.getPressure();
            float itemVolume = itemAirHandler.getVolume();
            float chargerPressure = getPressure();
            float delta = Math.abs(chargerPressure - itemPressure) / 2.0F;
            int airInItem = itemAirHandler.getAir();

            if (PneumaticCraftUtils.epsilonEquals(chargerPressure, 0f) && delta < 0.1f) {
                // small kludge to get last tiny bit of air out of an item (arithmetic rounding)
                itemAirHandler.addAir(-airInItem);
            } else if (itemPressure > chargerPressure + 0.01F && itemPressure > 0F) {
                // move air from item to charger
                int airToMove = Math.min(Math.min(airToTransfer, airInItem), (int) (delta * airHandler.getVolume()));
                itemAirHandler.addAir(-airToMove);
                this.addAir(airToMove);
                discharging = true;
            } else if (itemPressure < chargerPressure - 0.01F && itemPressure < itemAirHandler.maxPressure()) {
                // move air from charger to item
                int maxAirInItem = (int) (itemAirHandler.maxPressure() * itemVolume);
                float boost = chargerPressure < 15f ? 1f : 1f + (chargerPressure - 15f) / 5f;
                int airToMove = Math.min(Math.min((int)(airToTransfer * boost), airHandler.getAir()), maxAirInItem - airInItem);
                airToMove = Math.min((int) (delta * itemVolume), airToMove);
                itemAirHandler.addAir(airToMove);
                this.addAir(-airToMove);
                charging = true;
            }
        }

        boolean shouldEmit = rsController.shouldEmit();
        if (oldRedstoneStatus != shouldEmit) {
            if (nonNullLevel().getGameTime() - lastRedstoneUpdate > MAX_REDSTONE_UPDATE_FREQ) {
                updateRedstoneOutput();
            } else {
                pendingRedstoneStatus = shouldEmit ? 1: 0;
            }
        } else if (pendingRedstoneStatus != -1 && nonNullLevel().getGameTime() - lastRedstoneUpdate > MAX_REDSTONE_UPDATE_FREQ) {
            updateRedstoneOutput();
        }

        airHandler.setSideLeaking(!upgradeOnly && hasNoConnectedAirHandlers() ? getRotation() : null);
    }

public void tick() {
        if (!this.pendingChalices.isEmpty()) {
            this.pendingChalices.forEach(this::registerChalice);
            this.pendingChalices.clear();
        }
        switch (dimensionState) {
            case INVALID -> {
                LOGGER.error("The velmorra dimension is invalid, the level will be destroyed");
                destroyDimension();
            }
            case DEAD -> {
                deathTicks++;
                if (deathTicks >= COLLAPSE_DURATION) {
                    destroyDimension();
                    return;
                }
                while (warningsSend < COLLAPSE_WARNINGS.length && deathTicks >= COLLAPSE_WARNINGS[warningsSend].tick()) {
                    sendMessage(Component.translatable(COLLAPSE_WARNINGS[warningsSend].translationKey()));
                    warningsSend++;
                }
                int remaining = COLLAPSE_DURATION - deathTicks;
                if (remaining <= 10 * 20 && remaining % 20 == 0) {
                    sendOverlayMessage(Component.translatable("message.vampirism.velmorra.collapse.countdown", remaining / 20));
                }
                // regular sync covers late joiners as well
                if (deathTicks % 20 == 1) {
                    var packet = new ClientboundVelmorraCollapsePacket(deathTicks / (float) COLLAPSE_DURATION);
                    this.level.players().forEach(player -> player.connection.send(packet));
                }
            }
            case NONE -> {
                if (chaliceReferences.values().stream().filter(r -> r.active).count() >= 4) {
                    startFight();
                    return;
                }
            }
            case FIGHTING -> {
                if (level.getGameTime() % 100 == 0){
                    level.players().forEach(event::addPlayer);
                    if (this.draculaId == null) {
                        LOGGER.error("Dracula id is null");
                        this.dimensionState = State.INVALID;
                    } else if (this.dracula == null || this.dracula.get() == null) {
                        Entity entity = this.level.getEntity(this.draculaId);
                        if (entity instanceof Dracula dra) {
                            this.dracula = new WeakReference<>(dra);
                        } else {
                            LOGGER.error("Dracula is null");
                            this.dimensionState = State.INVALID;
                        }
                    }
                }
            }
        }
    }

@Override
    public void tick(BlockEntity ownerTE) {
        Level world = Objects.requireNonNull(ownerTE.getLevel());
        Direction actualLeakDir = leakDir;

        if (!world.isClientSide) {
            if (pendingAir != 0) {
                // add any saved air if this is being restored from item stack component data
                // need to wait till now to ensure saved volume upgrades are also accounted for
                addAir(pendingAir);
                pendingAir = 0;
                if (getPressure() > getDangerPressure()) {
                    // shouldn't happen but just in case
                    setPressure(getDangerPressure() - 0.1f);
                }
            }

            // server
            disperseAir(ownerTE);

            BlockPos pos = ownerTE.getBlockPos();
            if (safetyLeakDir != null) {
                float pressure = getPressure();
                if (!safetyLeaking && safetyPredicate.test(pressure)) {
                    safetyLeaking = true;
                } else if (safetyLeaking && !safetyPredicate.test(pressure + 0.2f)) {
                    safetyLeaking = false;
                }
                // also cap pressure at critical level (it's still possible for air to added faster than it can vent)
                if (pressure >= getCriticalPressure()) {
                    int wanted = (int)(getCriticalPressure() * getVolume());
                    addAir(wanted - getAir());
                }
            } else if (Objects.requireNonNull(world.getServer()).getTickCount() > 20) {
                // little kludge: no overpressure checks right after server starts up (just to be safe)
                doOverpressureChecks(ownerTE, world, pos);
            }

            actualLeakDir = safetyLeaking ? safetyLeakDir : leakDir;
            if (prevLeakDir != actualLeakDir || actualLeakDir != null && (world.getGameTime() & 0x1f) == 0) {
                // if leak status changes, sync pressure & leak dir to the client
                // OR if already leaking, periodically sync pressure & leak dir to the client
                NetworkHandler.sendToAllTracking(PacketUpdatePressureBlock.create(ownerTE.getBlockPos(),
                        anyConnectableFace(), actualLeakDir, getAir()
                ), ownerTE);
            }

            prevAir = getAir();
            prevLeakDir = actualLeakDir;
        }

        if (actualLeakDir != null && getAir() != 0) {
            handleAirLeak(ownerTE, actualLeakDir);
        }
    }

@Override
	public void tick() {
		super.tick();

		boolean doLogic = !level.isClientSide || isVirtual();
		State prevState = state;
		float totalTime = Math.max(3, (float) launcher.getTotalFlyingTicks());

		if (scanCooldown > 0)
			scanCooldown--;

		if (launch) {
			launch = false;
			activateDeferred();
		}

		for (Iterator<IntAttached<ItemStack>> iterator = launchedItems.iterator(); iterator.hasNext();) {
			IntAttached<ItemStack> intAttached = iterator.next();
			boolean hit = false;
			if (intAttached.getSecond() == trackedItem)
				hit = scanTrajectoryForObstacles(intAttached.getFirst());
			float maxTime = earlyTarget != null ? Math.min(earlyTargetTime, totalTime) : totalTime;
			if (hit || intAttached.exceeds((int) maxTime)) {
				placeItemAtTarget(doLogic, maxTime, intAttached);
				iterator.remove();
			}
			intAttached.increment();
		}

		if (state == State.LAUNCHING) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			lidProgress.tickChaser();
			if (lidProgress.getValue() > 1 - 1 / 16f && doLogic) {
				state = State.RETRACTING;
				lidProgress.setValue(1);
			}
		}

		if (state == State.CHARGED) {
			lidProgress.setValue(0);
			lidProgress.updateChaseSpeed(0);
			if (doLogic)
				ejectIfTriggered();
		}

		if (state == State.RETRACTING) {
			if (lidProgress.getChaseTarget() == 1 && !lidProgress.settled()) {
				lidProgress.tickChaser();
			} else {
				lidProgress.updateChaseTarget(0);
				lidProgress.updateChaseSpeed(0);
				if (lidProgress.getValue() == 0 && doLogic) {
					state = State.CHARGED;
					lidProgress.setValue(0);
					sendData();
				}

				float value = Mth.clamp(lidProgress.getValue() - getWindUpSpeed(), 0, 1);
				lidProgress.setValue(value);

				int soundRate = (int) (1 / (getWindUpSpeed() * 5)) + 1;
				float volume = .125f;
				float pitch = 1.5f - lidProgress.getValue();
				if (((int) level.getGameTime()) % soundRate == 0 && doLogic)
					level.playSound(null, worldPosition, SoundEvents.WOODEN_BUTTON_CLICK_OFF, SoundSource.BLOCKS,
						volume, pitch);
			}
		}

		if (state != prevState)
			notifyUpdate();
	}

public static int buildBenchmarkCube(CommandContext<CommandSourceStack> ctx) {
        String confirmation = ctx.getArgument("confirm", String.class);
        if (!confirmation.equals(CONFIRMATION_KEY)) {
            ctx.getSource().sendFailure(MSG_NO_CONFIRM);
            return 0;
        }

        if (!(ctx.getSource().getPlayer() instanceof ServerPlayer player) || player instanceof FakePlayer) {
            ctx.getSource().sendFailure(MSG_NOT_A_PLAYER);
            return 0;
        }

        ServerLevel level = ctx.getSource().getLevel();
        Direction horViewDir = Direction.getApproximateNearest(player.getViewVector(1F).multiply(1, 0, 1));
        SectionPos chunk = SectionPos.of(player.position().add(horViewDir.getUnitVec3().multiply(16, 0, 16)));
        BlockState state = FBContent.BLOCK_FRAMED_SLAB.value().defaultBlockState();
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();
        CamoContainer<?, ?> camo = FBContent.FACTORY_BLOCK.value().applyCamo(level, BlockPos.ZERO, player, ItemAccess.forStack(new ItemStack(Blocks.STONE)));
        if (camo == null) {
            ctx.getSource().sendFailure(MSG_CAMO_FAILED);
            return 0;
        }

        Holder<BlockOverlay> blockOverlay = null;
        if (ctx.getArgument("overlays", Boolean.class)) {
            Optional<Holder.Reference<BlockOverlay>> optional = level.registryAccess().get(OVERLAY_KEY);
            if (optional.isEmpty()) {
                ctx.getSource().sendFailure(MSG_OVERLAY_FAILED);
                return 0;
            }
            blockOverlay = optional.get();
        }

        int minX = chunk.minBlockX();
        int minY = chunk.minBlockY();
        int minZ = chunk.minBlockZ();
        for (int y = 0; y < 16; y++) {
            for (int x = 0; x < 16; x++) {
                for (int z = 0; z < 16; z++) {
                    pos.set(minX + x, minY + y, minZ + z);
                    boolean top = ((x % 2) ^ (z % 2)) != 0;
                    top |= y == 14 && x >= 7 && x <= 8 && z >= 7 && z <= 9;

                    level.setBlockAndUpdate(pos, state.setValue(FramedProperties.TOP, top));
                    if (level.getBlockEntity(pos) instanceof IFramedBlockEntity be) {
                        be.setCamo(camo, false);
                        be.setOverlay(blockOverlay);
                    }
                }
            }
        }

        pos.set(minX + 7, minY + 15, minZ + 7);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());
        pos.set(minX + 8, minY + 15, minZ + 7);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());

        pos.set(minX + 7, minY + 15, minZ + 8);
        level.setBlockAndUpdate(pos, Blocks.REPEATER.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING, Direction.SOUTH));
        pos.set(minX + 8, minY + 15, minZ + 8);
        level.setBlockAndUpdate(pos, Blocks.REPEATER.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING, Direction.NORTH));

        pos.set(minX + 7, minY + 15, minZ + 9);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_WIRE.defaultBlockState());
        pos.set(minX + 8, minY + 15, minZ + 9);
        level.setBlockAndUpdate(pos, Blocks.REDSTONE_TORCH.defaultBlockState());

        BlockPos dustPos = new BlockPos(minX + 8, minY + 15, minZ + 9);
        level.getServer().schedule(new TickTask(level.getServer().getTickCount() + 1, () ->
                level.setBlockAndUpdate(dustPos, Blocks.REDSTONE_WIRE.defaultBlockState())
        ));

        return Command.SINGLE_SUCCESS;
    }

@SubscribeEvent
	public static void clientInit(FMLClientSetupEvent evt) {
		// ensure API implementations are loaded
		BotaniaAPI.LOGGER.debug("Client API instances: {}",
				List.of(BotaniaAPIClient.instance(), ClientXplatAbstractions.instance()));

		BlockRenderLayers.skipPlatformBlocks = true; // platforms can use standard rendering on Forge
		BlockRenderLayers.init(ItemBlockRenderTypes::setRenderLayer);
		// GUIs
		evt.enqueueWork(() -> {
			MenuScreens.register(BotaniaItems.FLOWER_BAG_CONTAINER, FlowerPouchGui::new);
			MenuScreens.register(BotaniaItems.BAUBLE_BOX_CONTAINER, BaubleBoxGui::new);
		});

		// Events
		var bus = MinecraftForge.EVENT_BUS;
		bus.addListener((BookDrawScreenEvent e) -> KonamiHandler.renderBook(e.getBook(), e.getScreen(), e.getMouseX(), e.getMouseY(), e.getPartialTicks(), e.getGraphics()));
		bus.addListener((TickEvent.ClientTickEvent e) -> {
			if (e.phase == TickEvent.Phase.END) {
				ClientTickHandler.clientTickEnd(Minecraft.getInstance());
				KonamiHandler.clientTick(Minecraft.getInstance());
			}
		});
		bus.addListener((ItemTooltipEvent e) -> TooltipHandler.onTooltipEvent(e.getItemStack(), e.getFlags(), e.getToolTip()));
		bus.addListener((ScreenEvent.KeyPressed.Post e) -> CorporeaInputHandler.buttonPressed(e.getKeyCode(), e.getScanCode()));

		// Forge bus events done with Mixins on Fabric
		bus.addListener(EventPriority.HIGH, (ClientChatEvent e) -> {
			var player = Minecraft.getInstance().player;
			if (player != null && CorporeaIndexBlockEntity.ClientHandler.onChat(player, e.getMessage())) {
				e.setCanceled(true);
			}
		});
		bus.addListener((CustomizeGuiOverlayEvent.BossEventProgress e) -> {
			var result = BossBarHandler.onBarRender(e.getGuiGraphics(), e.getX(), e.getY(),
					e.getBossEvent(), true);
			result.ifPresent(increment -> {
				e.setCanceled(true);
				e.setIncrement(increment);
			});
		});
		bus.addListener((CustomizeGuiOverlayEvent.DebugText e) -> DebugHandler.onDrawDebugText(e.getLeft()));
		bus.addListener((InputEvent.Key e) -> {
			RingOfDexterousMotionItem.ClientLogic.onKeyDown();
			KonamiHandler.handleInput(e.getKey(), e.getAction(), e.getModifiers());
		});
		bus.addListener((TickEvent.RenderTickEvent e) -> {
			if (e.phase == TickEvent.Phase.START) {
				ClientTickHandler.renderTick(e.renderTickTime);
			}
		});
		bus.addListener(EventPriority.LOWEST, (RenderTooltipEvent.Color e) -> {
			var manaItem = XplatAbstractions.INSTANCE.findManaItem(e.getItemStack());
			if (manaItem == null) {
				return;
			}
			// Forge does not pass the tooltip width to any tooltip event.
			// To avoid a mixin here, we just duplicate the width checking part.
			int width = 0;
			ManaBarTooltipComponent manaBar = null;
			for (ClientTooltipComponent component : e.getComponents()) {
				width = Math.max(width, component.getWidth(e.getFont()));
				if (component instanceof ManaBarTooltipComponent c) {
					manaBar = c;
				}
			}
			if (manaBar != null) {
				manaBar.setContext(e.getX(), e.getY(), width);
			}
		});

		// Etc
		ClientProxy.initSeasonal();
		bus.addGenericListener(Entity.class, ForgeClientInitializer::attachEntityCapabilities);
		bus.addGenericListener(BlockEntity.class, ForgeClientInitializer::attachBeCapabilities);

		if (XplatAbstractions.INSTANCE.isModLoaded("ears")) {
			EarsIntegration.register();
		}
	}

protected void tickDeath() {
        ++this.deathTime;
        if (this.deathTime == 1){
            if (this.pendingTeleportSearch != null) {
                this.pendingTeleportSearch.cancel(true);
                this.pendingTeleportSearch = null;
            }
            this.antiRegen = 0;
            this.antiRegenTotal = 0;
            this.toTeleportTime = 0;
            this.toTeleportPos = null;
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        }
        if (MobsConfig.FancierApostleDeath.get() || (this.isInNether() && MobsConfig.ApostleNetherFancyDeath.get())) {
            this.setNoGravity(true);
            if (this.getKillCredit() instanceof Player){
                this.lastHurtByPlayerTime = 100;
            } else {
                this.lastHurtByMobTimestamp = 100;
            }
            if (this.deathTime < 180) {
                if (this.deathTime > 20) {
                    this.move(MoverType.SELF, new Vec3(0.0D, 0.1D, 0.0D));
                }
                ExplosionUtil.lootExplode(this.level, this, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0.0F, false, Explosion.BlockInteraction.KEEP, LootingExplosion.Mode.LOOT);
            } else if (this.deathTime != 200) {
                this.move(MoverType.SELF, new Vec3(0.0D, 0.0D, 0.0D));
            }
            if (this.deathTime >= 200) {
                this.move(MoverType.SELF, new Vec3(0.0D, -4.0D, 0.0D));
                if (this.onGround() || this.getY() <= this.level.getMinBuildHeight()) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        if (serverLevel.getLevelData().isThundering()) {
                            serverLevel.setWeatherParameters(6000, 0, false, false);
                        }
                        for (int k = 0; k < 200; ++k) {
                            float f2 = random.nextFloat() * 4.0F;
                            float f1 = random.nextFloat() * ((float) Math.PI * 2F);
                            double d1 = Mth.cos(f1) * f2;
                            double d2 = 0.01D + random.nextDouble() * 0.5D;
                            double d3 = Mth.sin(f1) * f2;
                            serverLevel.sendParticles(ParticleTypes.LARGE_SMOKE, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                            serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                        }
                        serverLevel.sendParticles(ParticleTypes.EXPLOSION_EMITTER, this.getX(), this.getY(), this.getZ(), 0, 1.0F, 0.0F, 0.0F, 0.5F);
                    }
                    this.playSound(SoundEvents.GENERIC_EXPLODE, 4.0F, (1.0F + (this.level.random.nextFloat() - this.level.random.nextFloat()) * 0.2F) * 0.7F);
                    this.playSound(this.getTrueDeathSound(), 5.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
                    this.die(this.deathBlow);
                    this.remove(RemovalReason.KILLED);
                }
            }
        } else {
            this.move(MoverType.SELF, new Vec3(0.0D, 0.0D, 0.0D));
            if (this.deathTime == 1){
                if (!this.level.isClientSide) {
                    ServerLevel ServerLevel = (ServerLevel) this.level;
                    if (ServerLevel.getLevelData().isThundering()) {
                        ServerLevel.setWeatherParameters(6000, 0, false, false);
                    }
                    for (int k = 0; k < 200; ++k) {
                        float f2 = random.nextFloat() * 4.0F;
                        float f1 = random.nextFloat() * ((float) Math.PI * 2F);
                        double d1 = Mth.cos(f1) * f2;
                        double d2 = 0.01D + random.nextDouble() * 0.5D;
                        double d3 = Mth.sin(f1) * f2;
                        ServerLevel.sendParticles(ParticleTypes.LARGE_SMOKE, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                        ServerLevel.sendParticles(ParticleTypes.FLAME, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                    }
                    for (int l = 0; l < 16; ++l){
                        ServerLevel.sendParticles(ParticleTypes.FLAME, this.getRandomX(1.0F), this.getRandomY() - 0.25F, this.getRandomZ(1.0F), 1, 0, 0, 0, 0);
                    }
                }
                this.die(this.deathBlow);
                this.playSound(this.getTrueDeathSound(), 5.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            }
            if (this.deathTime >= 30) {
                this.remove(RemovalReason.KILLED);
            }
        }

    }

private static void prepare(Frame frame) {
        LightPassTimer.frame();
        prepared = null;
        pendingHaze = null;
        lightCount = 0;
        shadowedCount = 0;
        volumeCount = 0;
        volumeShadowedCount = 0;
        visibilityMapCount = 0;
        fogCount = 0;
        FOG.clear();
        VOLUMETRIC.clear();
        VOLUME_RANK.clear();
        UNSHADOWED_VOLUME_RANK.clear();
        var config = PhotonConfig.INSTANCE;
        var scene = frame.scene();
        if (!config.dynamicLights.get() || frame.width() <= 0 || frame.height() <= 0
                || DynamicLightManager.isEmpty(scene, frame.world())) return;
        long start = System.nanoTime();
        var lights = DynamicLightManager.collect(scene, frame.world(), frame.partialTick(), FRAME_LIGHTS);

        int n = 0;
        var camera = frame.camera();
        for (var light : lights) {
            var p = light.position;
            var c = light.color;
            // negated, so NaN fails too: one bad light would turn its whole cluster NaN
            if (!light.enabled || !(light.range > 0) || !(light.intensity > 0) || !Double.isFinite(p.x + p.y + p.z)
                    || !Float.isFinite(c.x + c.y + c.z + light.intensity + light.range)) continue;
            double r = light.range;
            if (frame.frustum() != null && !frame.frustum().isVisible(new AABB(p.x - r, p.y - r, p.z - r, p.x + r, p.y + r, p.z + r))) {
                continue;
            }
            if (n == candidates.length) {
                candidates = Arrays.copyOf(candidates, n * 2);
                importance = Arrays.copyOf(importance, n * 2);
                order = Arrays.copyOf(order, n * 2);
            }
            float luminance = 0.2126f * c.x + 0.7152f * c.y + 0.0722f * c.z;
            candidates[n] = light;
            importance[n] = (float) (luminance * light.intensity * r * r / Math.max(camera.distanceToSqr(p.x, p.y, p.z), 1.0));
            order[n] = n;
            n++;
        }
        boolean volumetric = volumetricEnabled(frame.world());
        if (volumetric) {
            collectFog(frame);
        } else {
            scene.volumeBuffer = free(scene.volumeBuffer);
        }
        if (n == 0 && FOG.isEmpty()) {
            prepareMillis = (System.nanoTime() - start) / 1e6;
            return;
        }
        scene.lastLitTick = ticks;
        ACTIVE.add(scene);
        var rank = importance;
        IntArrays.quickSort(order, 0, n, (a, b) -> Float.compare(rank[b], rank[a]));
        int count = Math.min(n, MAX_LIGHTS);

        if (++scene.ambientAge > 20) {
            scene.ambient.clear();
            scene.ambientAge = 0;
        }
        var shadowMode = config.lightShadowMode.get();
        int shadowBudget = shadowMode == ShadowMode.OFF ? 0 : config.lightShadowedLights.get();
        SHADOWED.clear();
        SHADOWED_RANK.clear();
        DATA.clear();
        for (int k = 0; k < count; k++) {
            var light = candidates[order[k]];
            boolean shadowed = light.castShadows && SHADOWED.size() < shadowBudget;
            if (shadowed) {
                SHADOWED.add(light);
                SHADOWED_RANK.add(k);
            }
            pack(light, k, shadowed, frame);
            VOLUME_INDEX[k] = -1;
            if (volumetric && light.volumetric > 0) {
                // the haze is shadowed from the voxels only
                (shadowed && shadowMode == ShadowMode.VOXEL ? VOLUME_RANK : UNSHADOWED_VOLUME_RANK).add(k);
            }
        }
        // shadowed first: the volume pass tells them apart by index
        volumeShadowedCount = VOLUME_RANK.size();
        VOLUME_RANK.addAll(UNSHADOWED_VOLUME_RANK);
        for (int v = 0; v < VOLUME_RANK.size(); v++) {
            int k = VOLUME_RANK.getInt(v);
            VOLUME_INDEX[k] = v;
            VOLUMETRIC.add(candidates[order[k]]);
        }
        Arrays.fill(candidates, 0, n, null);

        MAP_RANK.clear();
        if (shadowMode == ShadowMode.VOXEL) {
            for (int v = 0; v < volumeShadowedCount; v++) MAP_RANK.add(VOLUME_RANK.getInt(v));
            for (int i = 0; i < SHADOWED_RANK.size(); i++) {
                int k = SHADOWED_RANK.getInt(i);
                if (VOLUME_INDEX[k] < 0) MAP_RANK.add(k);
            }
            // shadowed: the light's map + 1, whether or not the map is drawn this frame
            for (int map = 0; map < MAP_RANK.size(); map++) DATA.put(MAP_RANK.getInt(map) * 16 + 13, map + 1f);
        }
        LightClusters.build(VIEW, count, frame.projection(), frame.width(), frame.height());
        if (!VOLUMETRIC.isEmpty()) LightClusters.buildVolume(VOLUME_INDEX, count);
        uploadData(count);
        if (shadowMode != ShadowMode.VOXEL) {
            scene.voxels.release();
            scene.visibilityAtlas = free(scene.visibilityAtlas);
        } else if (!SHADOWED.isEmpty()) {
            scene.voxels.update(frame.level(), camera, SHADOWED, (long) (config.lightVoxelBudgetMs.get() * 1e6));
            // before anything is drawn, so lit particles have them even when the pass runs after them
            boolean everyLight = ticks - litParticleTick < LIT_PARTICLE_TICKS || !FOG.isEmpty();
            buildVisibilityMaps(frame, everyLight ? MAP_RANK.size() : volumeShadowedCount);
        }
        lightCount = count;
        shadowedCount = SHADOWED.size();
        volumeCount = VOLUMETRIC.size();
        fogCount = FOG.size();
        prepared = frame;
        prepareMillis = (System.nanoTime() - start) / 1e6;
        LightPassTimer.cpu(prepareMillis);
    }

@Override
    public void tick() {
        super.tick();

        if (this.isStuck())
            this.setDeltaMovement(Vec3.ZERO);

        var level = this.level();

        if (this.isStuck()) {
            if (!level.isClientSide()) {
                var owner = this.getOwner();

                if (owner instanceof LivingEntity livingOwner && !level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox(),
                        entity -> entity != livingOwner && TargetingUtils.canHarm(livingOwner, entity, this.getStack(), "constellation")).isEmpty())
                    this.discard();

                if (this.tickCount % 5 == 0 && this.tickCount >= this.getLifetime() * 20 && random.nextInt(20) == 0)
                    this.discard();
            }

            if (level.isClientSide()) {
                var color = isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(50), 50 + random.nextInt(150), 255);
                var data = ParticleUtils.constructSimpleSpark(color, 0.2F + random.nextFloat() * 0.1F, 30 + random.nextInt(20), 0.95F);

                level.addParticle(data, this.getX() + MathUtils.randomFloat(random) * this.getBbWidth() / 2F, this.getY(), this.getZ() + MathUtils.randomFloat(random) * this.getBbWidth() / 2F, 0, 0.1F + random.nextFloat() * 0.1F, 0);
            }

            var origin = this;
            var queue = new ArrayDeque<ConstellationStarEntity>();
            var visited = new HashSet<ConstellationStarEntity>();

            queue.add(origin);
            visited.add(origin);

            while (!queue.isEmpty()) {
                var current = queue.removeFirst();

                var neighbors = level.getEntitiesOfClass(ConstellationStarEntity.class, current.getBoundingBox().inflate(this.getConstellationRadius()));

                for (var star : neighbors) {
                    if (visited.add(star))
                        queue.add(star);
                }
            }

            if (visited.size() < 2)
                return;

            var sortedIds = new ArrayList<>(visited);

            var originIndex = sortedIds.indexOf(origin);

            var totalStars = sortedIds.size();
            var starEntities = new ConstellationStarEntity[totalStars];
            var starCenters = new Vec3[totalStars];
            var midYs = new double[totalStars];

            for (var i = 0; i < totalStars; i++) {
                var e = sortedIds.get(i);

                starEntities[i] = e;

                if (e != null) {
                    var c = e.getBoundingBox().getCenter();

                    starCenters[i] = c;
                    midYs[i] = c.y;
                }
            }

            var edges = new ArrayList<int[]>();
            var exists = new boolean[totalStars][totalStars];

            for (var i = 0; i < totalStars; i++) {
                var a = starCenters[i];

                if (a == null || !starEntities[i].isStuck())
                    continue;

                var neighbors = new ArrayList<EdgeCandidate>();

                for (var j = 0; j < totalStars; j++) {
                    if (i == j)
                        continue;

                    var b = starCenters[j];

                    if (b == null || !starEntities[j].isStuck())
                        continue;

                    var dx = a.x - b.x;
                    var dy = a.y - b.y;
                    var dz = a.z - b.z;

                    neighbors.add(new EdgeCandidate(i, j, dx * dx + dy * dy + dz * dz));
                }

                neighbors.sort(Comparator.comparingDouble(e -> e.weightSquared));

                var connections = 0;

                for (var candidate : neighbors) {
                    if (connections >= 2)
                        break;

                    var u = candidate.indexU;
                    var v = candidate.indexV;

                    if (exists[u][v])
                        continue;

                    edges.add(new int[]{u, v});
                    exists[u][v] = exists[v][u] = true;

                    connections++;
                }
            }

            for (var edge : edges) {
                if (edge[0] != originIndex)
                    continue;

                var a = starCenters[edge[0]];
                var b = starCenters[edge[1]];

                if (a == null || b == null)
                    continue;

                var dir = b.subtract(a);
                var length = dir.length();
                var dirNorm = dir.scale(1 / length);

                var proximityThreshold = 0.5;

                var segmentBox = new AABB(
                        Math.min(a.x(), b.x()) - proximityThreshold,
                        Math.min(a.y(), b.y()) - proximityThreshold,
                        Math.min(a.z(), b.z()) - proximityThreshold,
                        Math.max(a.x(), b.x()) + proximityThreshold,
                        Math.max(a.y(), b.y()) + proximityThreshold,
                        Math.max(a.z(), b.z()) + proximityThreshold
                );

                var crossed = false;
                var owner = this.getOwner();

                for (var entity : level.getEntitiesOfClass(LivingEntity.class, segmentBox,
                        entity -> owner instanceof LivingEntity livingOwner && entity != livingOwner && TargetingUtils.canHarm(livingOwner, entity, this.getStack(), "constellation"))) {
                    if (entity.getBoundingBox().clip(a, b).isPresent()) {
                        crossed = true;

                        if (!level.isClientSide() && owner instanceof LivingEntity livingOwner)
                            TargetingUtils.addHarmfulEffect(entity, new MobEffectInstance(RelicsMobEffects.TREMOR, (int) (this.getTremor() * 20), 0), livingOwner, this.getStack(), "constellation");

                        if (!level.isClientSide() && entity.tickCount % 20 == 0 && stack.getItem() instanceof MidnightMantleItem relic && owner instanceof LivingEntity livingOwner)
                            relic.getRelicData(livingOwner, stack).getLevelingData().addExperience("constellation", "star_tremor", 1);
                    }
                }

                if (level.isClientSide()) {
                    var particleSpacing = 0.15;

                    var up = new Vec3(0, 1, 0);
                    var u = dirNorm.cross(up);

                    if (u.length() < 1e-4)
                        u = dirNorm.cross(new Vec3(1, 0, 0));

                    u = u.normalize();

                    var v = dirNorm.cross(u).normalize();

                    var stepCount = Math.max(1, (int) Math.ceil(length / particleSpacing));

                    var amplitude = 0.05D;
                    var wavelength = 2D;
                    var speed = 0.05D;

                    var time = (level.getGameTime() + this.getId()) * speed;

                    for (var step = 0; step <= stepCount; step++) {
                        var f = step / (double) stepCount;
                        var basePos = a.add(dir.scale(f));
                        var phase = (f * length) / wavelength * 2 * Math.PI + time;
                        var offset = u.scale(Math.cos(phase) * amplitude).add(v.scale(Math.sin(phase) * amplitude));
                        var pos = basePos.add(offset);

                        if (crossed) {
                            var color = new Color(255, random.nextInt(50), 0);
                            var data = ParticleUtils.constructSimpleSpark(color, 0.25F, 5, 0.9F);

                            var motion = 0.05F;

                            level.addParticle(data, true, pos.x, pos.y, pos.z, MathUtils.randomFloat(random) * motion, MathUtils.randomFloat(random) * motion, MathUtils.randomFloat(random) * motion);
                        } else {
                            var color = isFlawless() ? new Color(200 + random.nextInt(50), 150 + random.nextInt(50), 0) : new Color(50 + random.nextInt(50), 50 + random.nextInt(150), 255);
                            var data = ParticleUtils.constructSimpleSpark(color, 0.25F, 0, 1F);

                            level.addParticle(data, true, pos.x, pos.y, pos.z, 0, 0, 0);
                        }
                    }
                }
            }
        }
    }

