public void resolveSpell() {
        if (world == null)
            return;
        if (result instanceof EntityHitResult ehr && ehr.getEntity().isRemoved()) {
            return;
        }
        DelayTimeline delayTimeline = resolver.spell.particleTimeline().get(ParticleTimelineRegistry.DELAY_TIMELINE.get());
        delayTimeline.resolvingSound().sound.playSound(world, result.getLocation());
        resolver.resume(world);
    }

default void schedule(int ticks, Runnable task) {
        if (ticks < 0) {
            task.run();
            return;
        }
        if (ticks == 0) {
            getImmediateTasks().add(task);
            return;
        }
        long executionTime = getSchedulerTime() + ticks;
        var list = getScheduledTasks().getOrDefault(executionTime, new ArrayList<>());
        list.add(task);
        getScheduledTasks().put(executionTime, list);
    }

private static void execute(List<RunnableEntry> tasks) {
        if (tasks == null || tasks.isEmpty()) return;
        var iter = tasks.iterator();
        while (iter.hasNext()) {
            var task = iter.next();
            if (task.delay <= 0) {
                try {
                    task.runnable.run();
                } catch (Exception e) {
                    GTCEu.LOGGER.error("error while schedule gregtech task", e);
                }
                iter.remove();
            } else {
                task.delay--;
            }
        }
    }

@Test
	public void testSpacedOutRuns() {
		// Setup: the deduplicating runner has enough time between calls for each command to run independently.
		AtomicInteger runs = new AtomicInteger();
		Runnable testRunnable = runs::getAndIncrement;
		Duration delay = Duration.ofMillis(10);
		TestDelayedExecutor executor = new TestDelayedExecutor();
		DeduplicatingRunner deduplicatingRunner = new DeduplicatingRunner(delay, executor);

		// Operation: schedule and fully elapse the delay several times.
		for (int i = 0; i < 5; i++) {
			deduplicatingRunner.run(testRunnable);
			executor.elapse(delay);
		}

		// Assertions: spaced-out calls are not deduplicated together.
		Assertions.assertEquals(5, runs.get());
	}

public static <T extends RangeRitual> List<T> getRituals(Level level, Class<T> type) {
        List<T> rituals = new ArrayList<>();
        Set<BlockPos> worldList = posMap.getOrDefault(level.dimension().location().toString(), new HashSet<>());
        List<BlockPos> stalePos = new ArrayList<>();
        for (BlockPos p : worldList) {
            if (!level.isLoaded(p))
                continue;
            BlockEntity entity = level.getBlockEntity(p);
            if (!(entity instanceof RitualBrazierTile brazierTile)) {
                stalePos.add(p);
                continue;
            }
            AbstractRitual ritual = brazierTile.ritual;
            if (ritual != null && ritual.getClass().equals(type)) {
                rituals.add((T) ritual);
            }
        }
        return rituals;
    }

@Test
	public void testDeduplicatedRuns() {
		// Setup: the deduplicating runner has one command repeatedly scheduled inside the debounce window.
		AtomicInteger runs = new AtomicInteger();
		Runnable testRunnable = runs::getAndIncrement;
		Duration delay = Duration.ofMillis(1000);
		TestDelayedExecutor executor = new TestDelayedExecutor();
		DeduplicatingRunner deduplicatingRunner = new DeduplicatingRunner(delay, executor);

		// Operation: schedule the command many times, then advance past the final scheduled delay.
		for (int i = 0; i < 100; i++) {
			deduplicatingRunner.run(testRunnable);
			executor.elapse(Duration.ofMillis(1));
		}
		executor.elapse(delay);

		// Assertions: the repeated calls collapse into a single delayed execution.
		Assertions.assertEquals(1, runs.get());
	}

@Override
    public void tick(boolean serverSide) {
        duration--;
        if (duration <= 0 && serverSide) {
            resolveSpell();
        } else if (!serverSide && result != null) {
            if (emitter == null) {
                DelayTimeline delayTimeline = resolver.spell.particleTimeline().get(ParticleTimelineRegistry.DELAY_TIMELINE.get());
                emitter = new ParticleEmitter(result::getLocation, () -> new Vec2(0, 0), delayTimeline.onTickEffect);
            }
            if (showParticles) {
                emitter.tick(world);
                if (duration <= 0) {
                    DelayTimeline delayTimeline = resolver.spell.particleTimeline().get(ParticleTimelineRegistry.DELAY_TIMELINE.get());
                    ParticleEmitter resolveEmitter = new ParticleEmitter(result::getLocation, () -> new Vec2(0, 0), delayTimeline.onResolvingEffect);
                    resolveEmitter.tick(world);
                }
            }
        }
    }

public void tick(@Nullable ServerTickEvent.Post e) {
        if (events.isEmpty()) {
            return;
        }

        List<ITimedEvent> stale = new ObjectArrayList<>();
        // Enhanced-for or iterator will cause a concurrent modification on integrated servers.
        for (int i = 0; i < events.size(); i++) {
            ITimedEvent event = events.get(i);
            if (event.isExpired()) {
                stale.add(event);
            } else {
                if (e == null)
                    event.tick(false);
                else
                    event.tick(e);
            }
        }
        this.events.removeAll(stale);
    }

public static void addManaEvent(Level world, Class<? extends SourcelinkTile> tileType, int amount, Event event, BlockPos sourcePos) {
        List<BlockPos> stalePos = new ArrayList<>();
        Set<BlockPos> worldList = posMap.getOrDefault(world.dimension().location().toString(), new HashSet<>());
        for (BlockPos p : worldList) {
            if (!world.isLoaded(p))
                continue;
            BlockEntity entity = world.getBlockEntity(p);
            if (world.getBlockEntity(p) == null || !(entity instanceof SourcelinkTile sourcelinkTile)) {
                stalePos.add(p);
                continue;
            }
            if (entity.getClass().equals(tileType) && sourcelinkTile.eventInRange(sourcePos, event) && sourcelinkTile.canAcceptSource()) {
                sourcelinkTile.getManaEvent(sourcePos, amount);
                break;
            }
        }
        for (BlockPos p : stalePos) {
            worldList.remove(p);
        }
    }

public static @Nullable <T extends RangeRitual> T getRitual(Level level, Class<T> type, Predicate<T> isMatch) {
        Set<BlockPos> worldList = posMap.getOrDefault(level.dimension().location().toString(), new HashSet<>());
        List<BlockPos> stalePos = new ArrayList<>();
        for (BlockPos p : worldList) {
            if (!level.isLoaded(p))
                continue;
            BlockEntity entity = level.getBlockEntity(p);
            if (!(entity instanceof RitualBrazierTile brazierTile)) {
                stalePos.add(p);
                continue;
            }
            AbstractRitual ritual = brazierTile.ritual;
            if (ritual != null && ritual.getClass().equals(type) && isMatch.test((T) ritual)) {
                return (T) ritual;
            }
        }
        for (BlockPos p : stalePos) {
            worldList.remove(p);
        }
        return null;
    }

