public static void execute(SunAltarUpdatePacket payload, IPayloadContext context) {
        Player playerEntity = context.player();
        if (playerEntity.level() instanceof ServerLevel level && (!AetherConfig.SERVER.sun_altar_whitelist.get() || playerEntity.hasPermissions(4) || SunAltarWhitelist.INSTANCE.isWhiteListed(playerEntity.getGameProfile()))) {
            if (AetherConfig.SERVER.sun_altar_dimensions.get().contains(level.dimension().location().toString())) {
                // Get how many days have passed in the world first, then add to it.
                var dayBase = level.getDayTime() / (long) payload.timeScale();
                var dayTime = (dayBase * payload.timeScale()) + payload.dayTime();
                // Set the time.
                level.setDayTime(dayTime);
                level.getServer().getPlayerList().broadcastAll(new ClientboundSetTimePacket(level.getGameTime(), level.getDayTime(), level.getGameRules().getBoolean(GameRules.RULE_DAYLIGHT)), level.dimension());
            }
        }
    }

public void scheduleNextTick(World world, BlockPos pos, Block block, boolean reset)
  {
    if (!togglingIsActive) return;
    if (reset || ticksTillOutputStateChange == 0) {
      ticksTillOutputStateChange = (outputState == true) ? onTicks : offTicks;
    }
    final int MAXIMUM_DELAY_UNTIL_NEXT_UPDATE = 20;  // always tick at least once every 20 ticks.
    lastTickDelay = Math.min(ticksTillOutputStateChange, MAXIMUM_DELAY_UNTIL_NEXT_UPDATE);
    if (lastTickDelay != 0) {  // should never happen, but be defensive...
      world.getPendingBlockTicks().scheduleTick(pos, block, lastTickDelay);
    }
    return;
  }

@Override
	protected void tick(E entity) {
		if (this.delayFinishedAt <= entity.level().getGameTime()) {
			entity.setSharedFlag(3, true);
			entity.setDeltaMovement(this.chargeVelocity);
			entity.lookAt(EntityAnchorArgument.Anchor.FEET, entity.position().add(this.chargeVelocity));

			for (LivingEntity target : EntityRetrievalUtil.getEntities(entity.level(), entity.getBoundingBox().expandTowards(this.chargeVelocity), LivingEntity.class, target -> target != entity && target.isAlive() && (!(target instanceof Player pl) || !pl.isCreative()))) {
				entity.doHurtTarget(target);
				EntityUtil.pushEntityAway(entity, target, 1.5f);
			}
		}
	}

