public static void consume(SAddBrewParticlesPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Level level = Goety.PROXY.getLevel();
            if (level instanceof ClientLevel clientWorld) {
                int area = BrewUtils.getAreaOfEffect(packet.itemStack) + 4;
                Vec3 vec3 = Vec3.atBottomCenterOf(packet.blockPos);

                for(int l = 0; l < 8; ++l) {
                    clientWorld.addParticle(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(ModItems.SPLASH_BREW.get())), vec3.x, vec3.y, vec3.z, clientWorld.random.nextGaussian() * 0.15D, clientWorld.random.nextDouble() * 0.2D, clientWorld.random.nextGaussian() * 0.15D);
                }

                float f0 = (float)(packet.color >> 16 & 255) / 255.0F;
                float f1 = (float)(packet.color >> 8 & 255) / 255.0F;
                float f2 = (float)(packet.color & 255) / 255.0F;
                ParticleOptions particleoptions = packet.instant ? ParticleTypes.INSTANT_EFFECT : ParticleTypes.EFFECT;

                for(int j3 = 0; j3 < 100 * (BrewUtils.getAreaOfEffect(packet.itemStack) + 1); ++j3) {
                    float f3 = clientWorld.random.nextFloat() * area;
                    float f4 = clientWorld.random.nextFloat() * (float)(Math.PI * (area / 2.0F));
                    double d1 = Math.cos(f4) * f3;
                    double d2 = 0.01D + clientWorld.random.nextDouble() * 0.5D + (area / 10.0D);
                    double d3 = Math.sin(f4) * f3;
                    Particle particle = ParticleUtil.addParticleInternal(particleoptions, particleoptions.getType().getOverrideLimiter(), vec3.x + d1 * 0.1D, vec3.y + 0.3D, vec3.z + d3 * 0.1D, d1, d2, d3);
                    if (particle != null) {
                        float f5 = 0.75F + clientWorld.random.nextFloat() * 0.25F;
                        particle.setColor(f0 * f5, f1 * f5, f2 * f5);
                        particle.setPower((float)f3);
                    }
                }

                clientWorld.playLocalSound(packet.blockPos.getX(), packet.blockPos.getY(), packet.blockPos.getZ(), SoundEvents.SPLASH_POTION_BREAK, SoundSource.NEUTRAL, 1.0F, clientWorld.random.nextFloat() * 0.1F + 0.9F, false);
            }
        });
        ctx.get().setPacketHandled(true);
    }

public void handleTravelRequest(ServerboundRequestTravelPacket packet, IPayloadContext context) {
        context.enqueueWork(() -> {
            var player = context.player();
            // For keybind anchor teleports
            ItemStack travelItemStack = TravelHandler.findTravelItem(player);

            Optional<TravelTarget> target = TravelTargetApi.INSTANCE.get(player.level(), packet.pos());

            boolean canBlockTeleport = TravelHandler.canBlockTeleport(player);

            // These errors should only ever be triggered if there's some form of desync
            if (!canBlockTeleport && travelItemStack.isEmpty()) {
                player.displayClientMessage(EIOCommonLang.ERROR_CANNOT_TELEPORT, true);
                return;
            }
            if (target.isEmpty()) {
                player.displayClientMessage(EIOCommonLang.ERROR_INVALID_DESTINATION, true);
                return;
            }
            // Eventually change the packet structure to include what teleport method was
            // used so this range can be selected correctly
            int range = Math.max(target.get().block2BlockRange(), target.get().item2BlockRange());
            if (packet.pos().distSqr(player.getOnPos()) > range * range) {
                player.displayClientMessage(EIOCommonLang.ERROR_TOO_FAR, true);
                return;
            }

            // Try to do teleport
            boolean successfulTeleport = TravelHandler.blockTeleportTo(player.level(), player, target.get(), false);
            if(successfulTeleport && !canBlockTeleport && !travelItemStack.isEmpty()){
                TravelHandler.consumeResources(travelItemStack);
                player.getCooldowns().addCooldown(travelItemStack.getItem(), BaseConfig.COMMON.ITEMS.TRAVELLING_BLINK_DISABLED_TIME.get());
            }
        });
    }

public static void handleSimpleInputEvent(ServerboundSimpleInputEvent msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            ServerPlayer player = (ServerPlayer) context.player();
            FactionPlayerHandler handler = FactionPlayerHandler.get(player);
            //Try to keep this simple
            final VampirePlayer vampirePlayer = VampirePlayer.get(player);
            switch (msg.event()) {
                case FINISH_SUCK_BLOOD -> vampirePlayer.endFeeding(true);
                case REVERT_BACK -> {
                    if (player.containerMenu instanceof RevertBackMenu menu) {
                        menu.consume(player);
                    }
                    handler.leaveFaction(!player.level().getServer().isHardcore());
                }
                case TOGGLE_VAMPIRE_VISION -> {
                    vampirePlayer.switchVision();
                    vampirePlayer.sync();
                }
                case TRAINER_LEVELUP -> {
                    if (player.containerMenu instanceof HunterTrainerMenu) {
                        ((HunterTrainerMenu) player.containerMenu).onLevelupClicked();
                    }
                }
                case BASIC_HUNTER_LEVELUP -> {
                    if (player.containerMenu instanceof HunterBasicMenu menu) {
                        menu.onLevelUpClicked(player);
                    }
                }
                case RESURRECT -> vampirePlayer.tryResurrect();
                case GIVE_UP -> vampirePlayer.giveUpDBNO();
                case JUMP -> IDraculaPlayer.getPresentDracula(player).ifPresent(IDraculaPlayer::swingWings);
                case GROW_WINGS -> IDraculaPlayer.getPresentDracula(player).ifPresent(IDraculaPlayer::toggleWings);
            }
        });
    }

public static void handle(PacketSyncOptions msg, Supplier<NetworkEvent.Context> ctx) {
		ctx.get().enqueueWork(() -> {

			/*
			 * Receiving this packet from server explicitly signifies that we have logged
			 * in to either a dedicated server, or integrated server that we do not host
			 * ourselves, so let's keep track of it.
			 */

			OmniconfigWrapper.onRemoteServer = true;

			OmniconfigWrapper wrapper = OmniconfigWrapper.wrapperRegistry.get(msg.fileName);

			if (wrapper != null) {

				EnigmaticLegacy.LOGGER.info("Synchronizing values of " + msg.fileName + " with ones dispatched by server...");

				for (String id : msg.synchronizedParameters.keySet()) {
					Omniconfig.GenericParameter parameter = wrapper.invokationMap.get(id);

					if (parameter != null) {
						String oldValue = parameter.valueToString();
						parameter.parseFromString(msg.synchronizedParameters.get(id));

						EnigmaticLegacy.LOGGER.info("Value of '" + parameter.getId() + "' was set to '" + parameter.valueToString() + "'; old value: " + oldValue);
					} else {
						EnigmaticLegacy.LOGGER.error("Value '" + id + "' does not exist in " + msg.fileName + "! Skipping.");
					}
				}
			} else {
				EnigmaticLegacy.LOGGER.fatal("Received synchronization packet for non-existent config file: " + msg.fileName);
			}

		});
		ctx.get().setPacketHandled(true);
	}

