private void breakAround(Level world, BlockPos pos, Direction face, ServerPlayer shooter) {
        Vec3i axis1 = RotationHelper.shiftAxis(face.getNormal());
        Vec3i axis2 = RotationHelper.shiftAxis(axis1);
        ServerScheduler.schedule(2, () -> {
            breakBlock(world, pos.offset(axis1), shooter);
            breakBlock(world, pos.subtract(axis1), shooter);
        });
        ServerScheduler.schedule(4, () -> {
            breakBlock(world, pos.offset(axis2), shooter);
            breakBlock(world, pos.subtract(axis2), shooter);
        });
        ServerScheduler.schedule(6, () -> {
            breakBlock(world, pos.offset(axis1).offset(axis2), shooter);
            breakBlock(world, pos.subtract(axis1).subtract(axis2), shooter);
        });
        ServerScheduler.schedule(8, () -> {
            breakBlock(world, pos.offset(axis1).subtract(axis2), shooter);
            breakBlock(world, pos.subtract(axis1).offset(axis2), shooter);
        });
    }

public static void echo(Player attacker, int delay, Runnable callback) {
        Vec3 origin = attacker.position();
        RandomSource rand = attacker.getRandom();
        for (int i = 0; i < delay / 10; i++) {
            ServerScheduler.schedule(i * 10, () -> {
                ((ServerLevel) attacker.level()).sendParticles(ParticleTypes.WITCH,
                        origin.x + attacker.getBbWidth() * (rand.nextGaussian() - 0.5) * 0.5,
                        origin.y + attacker.getBbHeight() * rand.nextFloat(),
                        origin.z + attacker.getBbWidth() * (rand.nextGaussian() - 0.5) * 0.5,
                        3, rand.nextFloat() * 0.2, 0.2 + rand.nextFloat() * 0.6, rand.nextFloat() * 0.2, 0);
            });
        }

        ServerScheduler.schedule(delay, () -> {
            Vec3 currentPos = attacker.position();
            attacker.setPos(origin.x, origin.y, origin.z);
            callback.run();
            attacker.setPos(currentPos.x, currentPos.y, currentPos.z);
        });
    }

public static BlockState setPipeActive(PipeBlockEntity<?, ?> blockEntity,
                                           BlockState state, boolean newActive, int duration) {
        if (!state.hasProperty(GTBlockStateProperties.ACTIVE) ||
                state.getValue(GTBlockStateProperties.ACTIVE) == newActive) {
            return state;
        }
        BlockState newState = state.setValue(GTBlockStateProperties.ACTIVE, newActive);
        if (blockEntity == null || blockEntity.getLevel() == null || blockEntity.isRemoved()) {
            return newState;
        }
        Level level = blockEntity.getLevel();

        level.setBlock(blockEntity.getBlockPos(), newState, Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
        blockEntity.notifyBlockUpdate();
        blockEntity.setChanged();

        if (newActive && level instanceof ServerLevel serverLevel) {
            TaskHandler.enqueueServerTask(serverLevel, () -> setPipeActive(blockEntity, newState, false, -1), duration);
        }
        return newState;
    }

private void handleDismount(Entity passenger)
	{
		final var passengerPosition = getPassengerRidingPosition(passenger);
		passenger.teleportTo(passengerPosition.x, passengerPosition.y, passengerPosition.z);
		passenger.setDeltaMovement(getDeltaMovement());
		if(getDeltaMovement().y < 0)
		{
			passenger.fallDistance = SkylineHelper.fallDistanceFromSpeed(getDeltaMovement().y);
			passenger.setOnGround(false);
		}
		passenger.getData(IEDataAttachments.SKYHOOK_USER.get()).release();
		if(hand!=null&&passenger instanceof Player)
		{
			ItemStack held = ((Player)passenger).getItemInHand(hand);
			if(held.getItem()==Misc.SKYHOOK.asItem())
				((Player)passenger).getCooldowns().addCooldown(Misc.SKYHOOK.asItem(), 10);
		}
	}

