				});
		}
	}

public static void applyChanges(LivingEntity livingEntity, List<Diff> changes) {
        for (var change : changes) {
            final var newAmplifier = change.newAmplifier;
            if (change.delay > 0) {
                final var effectType = change.effect.getEffectType();
                ((WorldScheduler)livingEntity.getWorld()).schedule(change.delay - 1, () -> {
                    var effect = livingEntity.getStatusEffect(effectType);
                    if (effect == null) {
                        // If the effect is not present, we can skip processing
                        return;
                    }
                    processRemoval(livingEntity, effect, newAmplifier);
                });
            } else {
                processRemoval(livingEntity, change.effect, newAmplifier);
            }
        }
    }

@Override
    public boolean perform(ItemEffectContext context) {
        if (key != null || keyEntity != null) {
            String entityId = Optional.ofNullable(keyEntity)
                    .map(provider -> provider.getEntity(context))
                    .map(Entity::getStringUUID)
                    .orElse(null);
            String concatenatedKey = Stream.of(key, entityId)
                    .filter(Objects::nonNull)
                    .collect(Collectors.joining(""));

            if (replaceKey.test(context) || !ServerScheduler.isScheduled(concatenatedKey)) {
                ServerScheduler.schedule(concatenatedKey, delay.getIntegerValue(context), () -> outcome.perform(context));
                return true;
            }
            return false;
        }

        ServerScheduler.schedule(delay.getIntegerValue(context), () -> outcome.perform(context));
        return true;
    }

