            for (LivingEntity nearby : EntityRetrievalUtil.getEntities(entity.level(), stompPos, entity.getBbWidth(), LivingEntity.class, target -> target != entity)) {
                DamageUtil.safelyDealDamage(DamageUtil.positionedEntityDamage(DamageTypes.MOB_ATTACK_NO_AGGRO, entity, stompPos), nearby, 10);
            }
        }

private void screenShakePlayers(ServerLevel level, T entity, Vec3 earthquakeOrigin) {
        for (ServerPlayer player : level.players()) {
            if (player.distanceToSqr(entity) > 20 * 20)
                continue;

            AoANetworking.sendToPlayer(player, new ScreenShakePacket(10, Math.max(0.1f, (1 - (float)earthquakeOrigin.distanceToSqr(player.position()) / (20f * 20f)) * 2), 0.98f));
