private void doBlocks(ServerLevel level, T entity, Vec3 earthquakeOrigin, int tick) {
        List<BlockSnapshot> positions = BlockRetrievalUtil.getBlocks(level, reader -> {
            List<BlockSnapshot> list = new ObjectArrayList<>();
            Iterable<Vec3> iterable = MathUtil.inLateralCircle(earthquakeOrigin, tick, 64);
            Set<BlockPos> checkedPositions = new ObjectOpenHashSet<>();

            for (Vec3 vecPos : iterable) {
                BlockPos pos = BlockPos.containing(vecPos);

                if (!checkedPositions.add(pos))
                    continue;

                BlockState state = reader.getBlockState(pos);

                if (!state.blocksMotion()) {
                    int offset = 10;

                    while (offset-- > 0 && !(state = reader.getBlockState(pos = pos.below())).blocksMotion());
                }
                else if (reader.getBlockState(pos.above()).blocksMotion()) {
                    int offset = 10;

                    while (offset-- > 0 && reader.getBlockState(pos = pos.above()).blocksMotion());

                    state = reader.getBlockState(pos = pos.below());
                }

                if (state.blocksMotion() && !reader.getBlockState(pos.above()).blocksMotion())
                    list.add(new BlockSnapshot(pos, state));
            }

            return list;
        });

        TMEParticlePacket packet = new TMEParticlePacket();

        if (entity.tickCount % 3 == 0) {
            for (ServerPlayer player : level.players()) {
                if (player.distanceToSqr(entity) > 32 * 32)
                    continue;

                Vec3 velocity = earthquakeOrigin.vectorTo(player.position()).normalize();

                SoundBuilder.at(AoASounds.FX_RUBBLE, level, earthquakeOrigin.add(velocity.scale(tick)))
                        .customInstance(new BuildableMovingSoundInstance(velocity))
                        .pitch(0.75f)
                        .onlyFor(player)
                        .play();
            }
        }

        for (BlockSnapshot ringPos : positions) {
            EarthquakeBlockEntity block = new EarthquakeBlockEntity(AoAMiscEntities.EARTHQUAKE_BLOCK.get(), level, ringPos.state(), ringPos.pos(), entity);

            block.setDamage(this.damage);
            block.setDeltaMovement(new Vec3(0, 0.35f, 0));
            block.setPos(Vec3.atCenterOf(ringPos.pos()));
            level.addFreshEntity(block);
            packet.particle(ParticleBuilder.forRandomPosInBlock(new BlockParticleOption(ParticleTypes.BLOCK, ringPos.state()), ringPos.pos())
                                    .lifespan(RandomUtil.numberBetween(20, 40))
                                    .scaleMod(0.5f)
                                    .velocity(RandomUtil.scaledGaussianValue(0.1f), RandomUtil.valueBetween(0.2f, 0.4f), RandomUtil.scaledGaussianValue(0.1f)));
        }

        packet.sendToAllPlayersTrackingEntity(entity);
    }

public boolean plungeAttack(Level world, LivingEntity attacker, ItemStack stack) {

        if (attacker.fallDistance <= attacker.getMaxFallDistance() || !isEmpowered(stack) || !useEnergy(stack, true, attacker)) {
            return false;
        }
        float range = getPlungeRange(attacker.fallDistance);
        if (world.isClientSide) {
            // TODO circle particle
            world.addParticle(new CylindricalParticleOptions(CoreParticles.BLAST_WAVE.get(), range * 2.0F, range * 3.0F, 0, VFXHelper.windColor(world.random).toRGBA(), 1.5F), attacker.getX(), attacker.getY(), attacker.getZ(), 0, 0, 0);
            return true;
        }
        if (Utils.getItemEnchantmentLevel(Enchantments.CHANNELING, stack) > 0) {
            if (world.canSeeSky(attacker.blockPosition()) && world instanceof ServerLevel && world.isThundering()) {
                attacker.addEffect(new MobEffectInstance(LIGHTNING_RESISTANCE.get(), 40, 0, false, false));
                Utils.spawnLightningBolt(world, attacker.blockPosition(), attacker);
            }
        }
        double r2 = range * range;
        boolean hit = false;
        for (Entity target : world.getEntities(attacker, attacker.getBoundingBox().inflate(range, 1, range), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
            if (attacker.distanceToSqr(target) <= r2) {
                hit |= target.hurt(IFluxItem.fluxDirectDamage(attacker), getPlungeAttackDamage(attacker, stack));
            }
        }
        if (hit) {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_RETURN, SoundSource.PLAYERS, 10.0F, 1.0F);
        } else {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_HIT_GROUND, SoundSource.PLAYERS, 3.0F, 1.0F);
        }
        return hit;
    }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity victim = result.getEntity();
        float f = (float) getBaseDamage();
        Entity owner = this.getOwner();
        boolean channeled = isChanneled();
        DamageSource damagesource = channeled ? this.damageSources().source(ISSDamageTypes.LIGHTNING_MAGIC, this, owner == null ? this : owner)
                : this.damageSources().trident(this, owner == null ? this : owner);
        if (this.level() instanceof ServerLevel serverlevel) {
            f = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), victim, damagesource, f);
        }
        if (channeled && owner instanceof LivingEntity livingOwner) {
            // todo: generic spell power too?
            f *= (float) livingOwner.getAttributeValue(AttributeRegistry.LIGHTNING_SPELL_POWER);
        }

        this.dealtDamage = true;
        if (victim.hurt(damagesource, f)) {
            if (victim.getType() == EntityType.ENDERMAN) {
                return;
            }

            if (this.level() instanceof ServerLevel serverlevel1) {
                EnchantmentHelper.doPostAttackEffectsWithItemSource(serverlevel1, victim, damagesource, this.getWeaponItem());
            }

            if (victim instanceof LivingEntity livingentity) {
                this.doKnockback(livingentity, damagesource);
                this.doPostHurtEffects(livingentity);
            }
        }

        this.setDeltaMovement(this.getDeltaMovement().multiply(-0.03, -0.1, -0.03));
        this.playSound(SoundEvents.TRIDENT_HIT, 1.0F, 0.7F);
    }

@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity entity, @NotNull LivingEntity attacker) {
		double range = 8;
		IntList alreadyTargetedEntities = new IntArrayList();

		Predicate<Entity> selector = e -> e instanceof LivingEntity && e instanceof Enemy && !(e instanceof Player) && !alreadyTargetedEntities.contains(e.getId());

		LivingEntity prevTarget = entity;
		int hops = entity.level().isThundering() ? 10 : 4;
		int dmg = hops + 1;
		for (int i = 0; i < hops; i++) {
			List<Entity> entities = entity.level().getEntities(prevTarget, new AABB(prevTarget.getX() - range, prevTarget.getY() - range, prevTarget.getZ() - range, prevTarget.getX() + range, prevTarget.getY() + range, prevTarget.getZ() + range), selector);
			if (entities.isEmpty()) {
				break;
			}

			LivingEntity target = (LivingEntity) entities.get(entity.level().getRandom().nextInt(entities.size()));
			if (attacker instanceof Player player) {
				target.hurt(player.damageSources().playerAttack(player), dmg);
			} else {
				target.hurt(attacker.damageSources().mobAttack(attacker), dmg);
			}

			alreadyTargetedEntities.add(target.getId());
			prevTarget = target;
			dmg--;
		}

		if (!alreadyTargetedEntities.isEmpty()) {
			XplatAbstractions.INSTANCE.sendToTracking(attacker,
					new BotaniaEffectPacket(EffectType.THUNDERCALLER_EFFECT,
							attacker.getX(), attacker.getY() + attacker.getBbHeight() / 2.0, attacker.getZ(),
							alreadyTargetedEntities.toArray(new int[0])));
		}

		return super.hurtEnemy(stack, entity, attacker);
	}

@Override
        public void tickTask() {
            ++this.ticks;
            if (this.level.getEntity(this.owner) instanceof LivingEntity living) {
                living.fallDistance = 0;
                living.invulnerableTime = 20;
                double radius = 1.0D;
                if (this.staff){
                    radius += 0.25D;
                }
                for(int i = 0; i < 2; ++i) {
                    double d0 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    double d1 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    double d2 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    this.level.sendParticles(ModParticleTypes.BIG_ELECTRIC.get(), living.getRandomX(1.0D), living.getRandomY(), living.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                }
                ServerParticleUtil.addParticlesAroundMiddleSelf(this.level, ModParticleTypes.ELECTRIC.get(), living);

                List<Entity> list = this.level.getEntities(living, living.getBoundingBox().inflate(radius));
                if (!list.isEmpty()) {
                    for (Entity entity : list) {
                        if (entity instanceof LivingEntity target) {
                            if (!MobUtil.areAllies(living, entity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entity) && entity.isAttackable()){
                                float baseDamage = SpellConfig.BoltingDamage.get().floatValue() * WandUtil.damageMultiply();
                                if (target.hurt(ModDamageSource.directShock(living), baseDamage + this.damage)){
                                    float chance = this.staff ? 0.25F : 0.05F;
                                    float chainDamage = this.damage / 2.0F;
                                    if (this.level.isThundering() && this.level.isRainingAt(target.blockPosition())){
                                        chance += 0.25F;
                                        chainDamage = this.damage;
                                    }
                                    if (this.level.random.nextFloat() <= chance){
                                        target.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                                    }
                                    if (this.staff){
                                        WandUtil.chainLightning(target, living, 2.0D, chainDamage);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

private void onThrowableCollision(HitResult result) {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player) || ((int) getY()) <= 0) {
			discard();
			return;
		}

		for (int i = 0; i < 32; i++) {
			level().addParticle(ParticleTypes.PORTAL, getX(), getY() + random.nextDouble() * 2D, getZ(), random.nextGaussian(), 0.0D, random.nextGaussian());
		}

		if (!level().isClientSide) {
			thrower.fallDistance = 0.0F;

			int x = (int) Math.round(getX());
			int y = (int) Math.round(getY());
			int z = (int) Math.round(getZ());

			if (result.getType() != HitResult.Type.MISS) {
				BlockPos pos;
				if (result.getType() == HitResult.Type.ENTITY) {
					Entity entityHit = ((EntityHitResult) result).getEntity();
					entityHit.hurt(damageSources().thrown(this, thrower), 0);
					pos = entityHit.blockPosition();
				} else {
					BlockHitResult blockResult = (BlockHitResult) result;
					pos = blockResult.getBlockPos().relative(blockResult.getDirection());
				}

				y = pos.getY();
				x = pos.getX();
				z = pos.getZ();
			}
			float targetX = x + 0.5F;
			float targetY = y + 0.5F;
			float targetZ = z + 0.5F;
			if (thrower instanceof ServerPlayer serverPlayer) {
				EventHooks.onEnderPearlLand(serverPlayer, targetX, targetY, targetZ, new ThrownEnderpearl(level(), serverPlayer), 0, result);
			}

			thrower.playSound(SoundEvents.ENDERMAN_TELEPORT, 1.0f, 1.0f);
			thrower.teleportTo(targetX, targetY, targetZ);
		}
		discard();
	}

default void dealAOEDamage(Player player, Entity target, ItemStack stack, long energyPerHit, float damage, double aoe) {
        List<LivingEntity> entities = player.level().getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(aoe, 0.25D, aoe));
        double aoeAngle = 100;
        double yaw = player.getYRot() - 180;

        int fireAspect = player.level().registryAccess().holder(Enchantments.FIRE_ASPECT).map(e -> EnchantmentHelper.getEnchantmentLevel(e, player)).orElse(0);

        for (LivingEntity entity : entities) {
            if (getEnergyStored(stack) < energyPerHit && !player.getAbilities().instabuild) break;
            float distance = player.distanceTo(entity);
            if (entity == player || entity == target || player.isAlliedTo(entity) || distance < 1 || entity.distanceTo(target) > aoe) continue;
            double angle = Math.atan2(player.getX() - entity.getX(), player.getZ() - entity.getZ()) * MathHelper.todeg;
            double relativeAngle = Math.abs((angle + yaw) % 360);
            if (relativeAngle <= aoeAngle / 2 || relativeAngle > 360 - (aoeAngle / 2)) {
                boolean lit = false;
                float health = entity.getHealth();
                if (fireAspect > 0 && !entity.isOnFire()) {
                    lit = true;
                    entity.setRemainingFireTicks(20);
                }

                if (entity.hurt(entity.level().damageSources().playerAttack(player), damage)) {
                    float damageDealt = health - entity.getHealth();
                    entity.knockback(0.4F, MathHelper.sin(player.getYRot() * MathHelper.torad), (-MathHelper.cos(player.getYRot() * MathHelper.torad)));

                    if (fireAspect > 0) {
                        entity.setRemainingFireTicks(fireAspect * 4 * 20);
                    }

                    if (player.level() instanceof ServerLevel && damageDealt > 2.0F) {
                        int k = (int)((double)damage * 0.5D);
                        ((ServerLevel)player.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, entity.getX(), entity.getY(0.5D), entity.getZ(), k, 0.1D, 0.0D, 0.1D, 0.2D);
                    }

                    player.awardStat(Stats.DAMAGE_DEALT, Math.round(damageDealt * 10.0F));
                    if (player.level() instanceof ServerLevel && damageDealt > 2.0F) {
                        int k = (int) ((double) damageDealt * 0.5D);
                        ((ServerLevel) player.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, entity.getX(), entity.getY(0.5D), entity.getZ(), k, 0.1D, 0.0D, 0.1D, 0.2D);
                    }
                } else if (lit) {
                    entity.clearFire();
                }
            }
            extractEnergy(player, stack, energyPerHit);
        }
    }

protected void onHitEntity(EntityHitResult p_37626_) {
        if (!this.level.isClientSide) {
            float baseDamage = SpellConfig.IceSpikeDamage.get().floatValue() * WandUtil.damageMultiply();
            Entity entity = p_37626_.getEntity();
            if (this.getPierceLevel() > 0) {
                if (this.piercingIgnoreEntityIds == null) {
                    this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
                }

                if (this.piercedAndKilledEntities == null) {
                    this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
                }

                if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
                    this.discard();
                    return;
                }

                this.piercingIgnoreEntityIds.add(entity.getId());
            }
            Entity entity1 = this.getOwner();
            boolean flag;
            baseDamage += this.getExtraDamage();
            if (entity1 instanceof LivingEntity livingentity) {
                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }
                flag = entity.hurt(ModDamageSource.iceSpike(this, livingentity), baseDamage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    }
                }
            } else {
                flag = entity.hurt(ModDamageSource.iceSpike(this, this), baseDamage);
            }

            if (flag && entity instanceof LivingEntity livingEntity) {
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + livingEntity.getRandom().nextInt(2))));
                this.playSound(ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (livingEntity.level instanceof ServerLevel serverLevel){
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.PACKED_ICE.defaultBlockState()), livingEntity);
                }
                if (this.getPierceLevel() <= 0) {
                    this.discard();
                }
            }

        }
    }

private void executeAttacks() {
		if (this.currentState == State.MORTAR_SHOOTING && this.ticksProgress % 10 == 0) {
			HydraMortar mortar = new HydraMortar(TFEntities.HYDRA_MORTAR.get(), this.headEntity.level(), this.headEntity);

			// launch blasting mortars if the player is hiding
			if (this.targetEntity != null && !this.headEntity.canEntityBeSeen(this.targetEntity)) {
				mortar.setToBlasting();
			}

			this.headEntity.playSound(TFSounds.HYDRA_SHOOT.get(), 10.0F, (this.headEntity.level().getRandom().nextFloat() - this.headEntity.level().getRandom().nextFloat()) * 0.2F + 1.0F);
			this.headEntity.level().addFreshEntity(mortar);

		}
		if (this.headEntity.getState() == State.BITING) {
			// damage nearby things
			List<Entity> nearbyList = this.headEntity.level().getEntities(this.headEntity, this.headEntity.getBoundingBox().inflate(0.0, 1.0, 0.0));

			for (Entity nearby : nearbyList) {
				if (nearby instanceof LivingEntity living && nearby != this.hydra) {
					//is a player holding a shield? Let's do some extra stuff!
					if (nearby instanceof Player player && player.isBlocking()) {
						if (!player.getCooldowns().isOnCooldown(player.getUseItem())) {
							//cause severe damage and play a shatter sound
							this.headEntity.level().playSound(null, player.blockPosition(), player.getUseItem().is(Items.SHIELD) ? TFSounds.WOOD_SHIELD_SHATTERS.get() : TFSounds.METAL_SHIELD_SHATTERS.get(), SoundSource.PLAYERS, 1.0F, player.getVoicePitch());
							player.getUseItem().hurtAndBreak(112, player, player.getUsedItemHand());
						}
						//add cooldown and knockback
						player.getCooldowns().addCooldown(player.getUseItem(), 200);
						player.stopUsingItem();
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.15F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					}

					// bite it!
					nearby.hurt(TFDamageTypes.getEntityDamageSource(living.level(), TFDamageTypes.HYDRA_BITE, this.hydra, TFEntities.HYDRA.get()), BITE_DAMAGE);

					//knockback!
					if (living instanceof Player player) {
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.1F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					} else {
						living.knockback(-this.headEntity.getDirection().getStepX(), 0.1F, -this.headEntity.getDirection().getStepZ());
					}
				}
			}
		}

		if (this.headEntity.getState() == State.FLAMING) {
			Entity target = getHeadLookTarget();

			if (target != null && target != this.headEntity.getParent() && (!(target instanceof HydraPart) || ((HydraPart) target).getParent() != this.headEntity.getParent()) && this.hydra.level() instanceof ServerLevel serverLevel) {
				if (!target.fireImmune() && target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(target.level(), TFDamageTypes.HYDRA_FIRE, this.hydra, TFEntities.HYDRA.get()), FLAME_DAMAGE)) {
					target.igniteForSeconds(FLAME_BURN_FACTOR);
				}
			}
		}
	}

private static Vec3 handleDamageFromTrain(Level world, AbstractContraptionEntity contraptionEntity,
		Vec3 contraptionMotion, Entity entity, Vec3 entityMotion, PlayerType playerType) {

		if (!(contraptionEntity instanceof CarriageContraptionEntity cce))
			return entityMotion;
		if (!entity.onGround())
			return entityMotion;

		CompoundTag persistentData = entity.getPersistentData();
		if (persistentData.contains("ContraptionGrounded")) {
			persistentData.remove("ContraptionGrounded");
			return entityMotion;
		}

		if (cce.collidingEntities.containsKey(entity))
			return entityMotion;
		if (entity instanceof ItemEntity)
			return entityMotion;
		if (cce.nonDamageTicks != 0)
			return entityMotion;
		if (!AllConfigs.server().trains.trainsCauseDamage.get())
			return entityMotion;

		Vec3 diffMotion = contraptionMotion.subtract(entity.getDeltaMovement());

		if (diffMotion.length() <= 0.35f || contraptionMotion.length() <= 0.35f)
			return entityMotion;

		DamageSource source = CreateDamageSources.runOver(world, contraptionEntity);
		double damage = diffMotion.length();
		if (entity.getClassification(false) == MobCategory.MONSTER)
			damage *= 2;

		if (entity instanceof Player p && (p.isCreative() || p.isSpectator()))
			return entityMotion;

		if (playerType == PlayerType.CLIENT) {
			CatnipServices.NETWORK.sendToServer(new TrainCollisionPacket((int) (damage * 16), contraptionEntity.getId()));
			world.playSound((Player) entity, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT,
				SoundSource.NEUTRAL, 1, .75f);
		} else {
			entity.hurt(source, (int) (damage * 16));
			world.playSound(null, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.NEUTRAL, 1, .75f);
			if (!entity.isAlive())
				contraptionEntity.getControllingPlayer()
					.map(world::getPlayerByUUID)
					.ifPresent(AllAdvancements.TRAIN_ROADKILL::awardTo);
		}

		Vec3 added = entityMotion.add(contraptionMotion.multiply(1, 0, 1)
			.normalize()
			.add(0, .25, 0)
			.scale(damage * 4))
			.add(diffMotion);

		return VecHelper.clamp(added, 3);
	}

public void tick() {
        super.tick();
        prevactivateProgress = activateProgress;

        if (isActivate() && this.activateProgress > 0F) {
            this.activateProgress--;
        }

        if (this.level().isClientSide) {
            if (this.clientSideAttackStarted) {
                --this.lifeTicks;
                if (!isActivate() && this.activateProgress < 10F) {
                    this.activateProgress++;
                }
                if (this.lifeTicks == 33) {
                    for(int i = 0; i < 80; ++i) {
                        BlockState block = level().getBlockState(blockPosition().below());
                        double d0 = this.getX() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d1 = this.getY() + 0.03D;
                        double d2 = this.getZ() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d3 = (this.random.nextGaussian() * 0.07D);
                        double d4 = (this.random.nextGaussian() * 0.07D);
                        double d5 = (this.random.nextGaussian() * 0.07D);
                        this.level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, block), d0, d1, d2, d3, d4, d5);
                    }
                }

                if (this.lifeTicks == 14) {
                    this.setActivate(true);
                    for(int i = 0; i < 12; ++i) {
                        double d0 = this.getX() + (this.random.nextDouble() * 2.0D - 1.0D) * (double)this.getBbWidth() * 0.5D;
                        double d1 = this.getY() + 0.05D + this.random.nextDouble();
                        double d2 = this.getZ() + (this.random.nextDouble() * 2.0D - 1.0D) * (double)this.getBbWidth() * 0.5D;
                        double d3 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        double d4 = 0.3D + this.random.nextDouble() * 0.3D;
                        double d5 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        this.level().addParticle(ParticleTypes.REVERSE_PORTAL, d0, d1, d2, d3, d4, d5);
                    }
                }
            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -10) {
                if(isActivate()) {
                    this.setActivate(false);
                }
            }
            if (this.warmupDelayTicks < -10 && this.warmupDelayTicks > -30) {
                for(LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.2D, 0.0D, 0.2D))) {
                    this.damage(livingentity);
                }
            }


            if (!this.sentSpikeEvent) {
                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (--this.lifeTicks < 0) {
                this.discard();
            }
        }

    }

@Override
	public void doCastFx(ServerLevel level, ItemStack staff, LivingEntity caster, Object args) {
		super.doCastFx(level, staff, caster, args);

		final int rings = Mth.ceil(caster.getBbHeight() * 4);

		for (int i = 0; i < rings; i++) {
			final int step = i;

			AoAScheduler.schedule(i + 1, tick -> {
				ParticleBuilder.forPositionsInCircle(ParticleTypes.EXPLOSION, caster.position().add(0, step * 0.25f, 0), Mth.sin(step / (float)rings + 0.5f) * 0.25f, 32)
						.scaleMod(0.15f)
						.lifespan((rings + 3) - step)
						.colourTint(0xF79400)
						.addTransition(FollowEntityParticleTransition.create(caster.getId()))
						.sendToAllPlayersTrackingEntity(caster);
				ParticleBuilder.forPositionsInCircle(ParticleTypes.SPORE_BLOSSOM_AIR, caster.position().add(0, step * 0.25f, 0), Mth.sin(step / (float)rings + 0.5f) * 0.25f, 32)
						.scaleMod(0.25f)
						.lifespan(caster.getRandom().nextInt(10, 30))
						.colourTint(0xFA9400)
						.sendToAllPlayersTrackingEntity(caster);
			});
		}
	}

@Override
	public void tick() {
		super.tick();

		if (!level.isClientSide) {
			if (random.nextInt(200) == 0 && !level.dimensionType().ultraWarm() && level.getBlockState(blockPosition()).getMaterial().isReplaceable()) {
				level.setBlockAndUpdate(blockPosition(), Blocks.WATER.defaultBlockState());
				new DracyonCleanupTask(level, blockPosition()).schedule(5, TimeUnit.SECONDS);
			}

			if (random.nextInt(70) == 0 && getTarget() != null) {
				LivingEntity target = getTarget();
				BaseMobProjectile projectile = new SpectralShotEntity(this, BaseMobProjectile.Type.MAGIC);

				double distanceFactorX = target.getX() - projectile.getX();
				double distanceFactorY = target.getBoundingBox().minY + (target.getBbHeight() / 3) - projectile.getY();
				double distanceFactorZ = target.getZ() - projectile.getZ();
				double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) * 0.05d;

				level.playSound(null, blockPosition(), AoASounds.ENTITY_DRACYON_AMBIENT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
				projectile.shoot(distanceFactorX, distanceFactorY + hyp, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
				level.addFreshEntity(projectile);
			}

			float healthPercent = getHealth() / getMaxHealth();

			if (healthPercent != bossInfo.getPercent())
				bossInfo.setPercent(healthPercent);
		}
	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
		if (WorldUtil.isWorld(level, AoADimensions.NOWHERE) || !(level instanceof ServerLevel serverLevel) || !(entity instanceof ServerPlayer pl))
			return stack;

		ServerLevel nowhere = serverLevel.getServer().getLevel(AoADimensions.NOWHERE);

		if (nowhere == null)
			return stack;

		BlockPos fromPos = entity.blockPosition();

		AoAScheduler.schedule(1, tick -> {
			if (AdvancementUtil.isAdvancementCompleted(pl, AdventOfAscension.id("nowhere/root"))) {
				ServerPlayerDataManager plData = PlayerUtil.getAdventPlayer(pl);
				GlobalPos returnLoc = plData.storage.getPortalReturnFor(nowhere.dimension());

				pl.changeDimension(AoAPortal.getTransitionForLevel(nowhere, pl, AoABlocks.NOWHERE_PORTAL.get()));
				pl.connection.teleport(17.5d, 502.5d, 3.5d, 0, pl.getXRot());

				plData.storage.setPortalReturnLocation(nowhere.dimension(), returnLoc == null ? new GlobalPos(level.dimension(), fromPos) : returnLoc);
			}
			else {
				PlayerUtil.getAdventPlayer(pl).storage.setPortalReturnLocation(nowhere.dimension(), pl.level().dimension(), pl.blockPosition());
				pl.changeDimension(AoAPortal.getTransitionForLevel(nowhere, pl, AoABlocks.NOWHERE_PORTAL.get()));
				pl.connection.teleport(17.5d, 452.5d, 3.5d, 0, pl.getXRot());
			}
		});

		return stack;
	}

private static void onPlayerDamagedPre(final LivingDamageEvent.Pre ev) {
		if (ev.getEntity() instanceof ServerPlayer pl) {
			if (pl.getHealth() <= ev.getContainer().getNewDamage()) {
				ServerPlayerDataManager plData = PlayerUtil.getAdventPlayer(pl);
				PositionAndRotation checkpoint = plData.storage.getActiveCheckpoint();

				if (checkpoint != null) {
					if (CheckpointBlock.isValidCheckpoint(pl.level(), checkpoint)) {
						AoAScheduler.schedule(1, tick -> {
							if (NowhereEvents.isInBossRegion(pl.blockPosition()))
								InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);

							PlayerUtil.resetToDefaultStatus(pl);
							pl.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
							pl.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.respawn"), ChatFormatting.GREEN), true);
							checkpoint.applyToEntity(pl);
						});

						ev.getContainer().setNewDamage(0);

						return;
					}
					else {
						plData.storage.clearActiveCheckpoint();
						pl.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.invalid"), ChatFormatting.RED));
					}
				}

				if (ev.getEntity().level().dimension() == AoADimensions.NOWHERE)
					NowhereEvents.doDeathPrevention(ev, plData);
			}
		}
	}

public static void handleNowhereRightClickBlock(final PlayerInteractEvent.RightClickBlock ev) {
		BlockState blockState = ev.getLevel().getBlockState(ev.getPos());
		Block block = blockState.getBlock();
		ItemStack heldStack = ev.getEntity().getItemInHand(ev.getHand());
		Item heldItem = heldStack.getItem();

		if (block == Blocks.JUKEBOX) {
			if (heldItem == Items.AIR || heldStack.has(DataComponents.JUKEBOX_PLAYABLE)) {
				ev.setUseItem(TriState.TRUE);
				ev.setUseBlock(TriState.TRUE);
				ev.getEntity().getAbilities().mayBuild = true;
			}
		}
		else if (blockState.is(AoATags.Blocks.NOWHERE_SAFE_GUI_BLOCK)) {
			ev.setUseItem(TriState.FALSE);
		}
		else if (block == Blocks.WATER_CAULDRON) {
			ev.setUseItem(TriState.FALSE);
			AoAScheduler.schedule(1, tick -> ev.getLevel().setBlock(ev.getPos(), blockState.setValue(LayeredCauldronBlock.LEVEL, LayeredCauldronBlock.MAX_FILL_LEVEL), Block.UPDATE_CLIENTS));
		}
		else if (block == AoABlocks.TEA_SINK.get()) {
			ev.setUseItem(TriState.FALSE);
			AoAScheduler.schedule(1, tick -> ev.getLevel().setBlock(ev.getPos(), blockState.setValue(TeaSink.FILLED, true), Block.UPDATE_CLIENTS));
		}
		else if (heldItem == AoAItems.LOTTO_TOTEM.get()) {
			ev.setUseItem(TriState.TRUE);
			ev.setUseBlock(TriState.FALSE);
			ev.getEntity().getAbilities().mayBuild = true;
		}
		else {
			ev.setCanceled(true);
		}
	}

public static void doDeathPrevention(final LivingDamageEvent.Pre ev, ServerPlayerDataManager plData) {
		ServerPlayer player = plData.getPlayer();

		if (player.server.isHardcore() && NowhereEvents.isInBossRegion(player.blockPosition()))
			return;

		LivingEntity killer = player.getKillCredit();

		player.getScoreboard().forAllObjectives(ObjectiveCriteria.DEATH_COUNT, player, ScoreAccess::increment);

		if (killer != null) {
			player.awardStat(Stats.ENTITY_KILLED_BY.get(killer.getType()));
			killer.awardKillScore(player, 1, ev.getContainer().getSource());
		}

		player.awardStat(Stats.DEATHS);
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_DEATH));
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_REST));

		if (!AdvancementUtil.isAdvancementCompleted(player, AdventOfAscension.id("nowhere/root"))) {
			AoAScheduler.schedule(1, tick -> {
				PlayerUtil.resetToDefaultStatus(player);
				player.connection.teleport(17.5d, 452.5d, 3.5d, 0, player.getXRot());
				InventoryUtil.clearItems(player, AoAItems.RETURN_CRYSTAL);
				PlayerUtil.getAdventPlayer(player).storage.returnStoredItems();
			});
		}
		else {
			NowhereActivityPortal.Activity.RETURN.activate(plData.getPlayer());
		}

		player.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
		ev.getContainer().setNewDamage(0);
	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level world, LivingEntity entity) {
		if (entity instanceof ServerPlayer pl) {
			if (!WorldUtil.isWorld(world, AoADimensions.NOWHERE)) {
				PlayerUtil.notifyPlayer(pl, LocaleUtil.getLocaleMessage("message.feedback.item.returnCrystal.wrongDim"));

				return stack;
			}

			if (!pl.isCreative())
				stack.shrink(1);

			if (!NowhereEvents.isInLobbyRegion(pl.blockPosition())) {
				if (NowhereEvents.isInBossRegion(pl.blockPosition()) && !AdvancementUtil.isAdvancementCompleted(pl, AdventOfAscension.id("nowhere/root"))) {
					AoAScheduler.schedule(1, tick -> {
						PlayerUtil.resetToDefaultStatus(pl);
						pl.placePortalTicket(pl.blockPosition());
						pl.teleportTo(pl.serverLevel(), 17.5d, 452.5d, 3.5d, Set.of(), 0, pl.getXRot());
						InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);
						PlayerUtil.getAdventPlayer(pl).storage.returnStoredItems();
					});
				}
				else {
					AoAScheduler.schedule(1, tick -> {
						PlayerUtil.resetToDefaultStatus(pl);
						pl.placePortalTicket(pl.blockPosition());
						pl.teleportTo(pl.serverLevel(), 16.5d, 1501.5d, 16.5d, Set.of(), 180, pl.getXRot());
						InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);
						PlayerUtil.getAdventPlayer(pl).storage.returnStoredItems();
					});
				}
			}
		}

		return stack;
	}

private static void onEntityInteract(final PlayerInteractEvent.EntityInteractSpecific ev) {
		if (!ev.getEntity().level().isClientSide) {
			if (ev.getItemStack().getItem() instanceof StasisCapsule stasisCapsule && ev.getTarget() instanceof LivingEntity target) {
				InteractionResult result = stasisCapsule.tryCapture(ev.getEntity(), target, ev.getItemStack(), ev.getHand());

				if (result != InteractionResult.PASS) {
					ev.setCancellationResult(result);

					return;
				}
			}

			if (ev.getTarget() instanceof Piglin piglin && piglin.getItemBySlot(EquipmentSlot.HEAD).getItem() == Items.GOLDEN_HELMET) {
				ItemStack stack = ev.getEntity().getItemInHand(ev.getHand());

				if ((stack.getItem() == Items.ENCHANTED_GOLDEN_APPLE || stack.getItem() == AoAItems.GOLD_COIN.get()) && piglin.getOffhandItem().isEmpty()) {
					piglin.addTag("BarteringForExplosiveIdol");
					piglin.setItemSlot(EquipmentSlot.OFFHAND, stack.split(1));
					piglin.setGuaranteedDrop(EquipmentSlot.OFFHAND);
					piglin.getBrain().setMemoryWithExpiry(MemoryModuleType.ADMIRING_ITEM, true, 121);
					piglin.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);
					piglin.getNavigation().stop();

					AoAScheduler.schedule(120, tick -> {
						if (piglin != null && piglin.isAlive() && piglin.getHealth() >= piglin.getMaxHealth()) {
							ItemStack offHandItem = piglin.getItemInHand(InteractionHand.OFF_HAND);

							if (offHandItem.getItem() == Items.ENCHANTED_GOLDEN_APPLE || offHandItem.getItem() == AoAItems.GOLD_COIN.get()) {
								piglin.setItemInHand(InteractionHand.OFF_HAND, Items.GOLD_INGOT.getDefaultInstance());
								piglin.getBrain().eraseMemory(MemoryModuleType.ADMIRING_ITEM);
							}
						}
					});
				}
			}
		}
	}

private static void fireTriggers(Event event) {
        if (event.player.getWorld().isClient()) { return; }
        // Iterate stash effects
        SpellStashHelper.useStashes(event);
        // Iterate passive spells
        var player = event.player;
        var caster = (SpellCaster.Player)player;
        for(var spellEntry: SpellContainerSource.passiveSpellsOf(event.player)) {
            var spell = spellEntry.value();
            var spellId = spellEntry.getKey().get().getValue();
            if (spell.passive != null && !caster.getCooldownManager().isCoolingDown(spellEntry)) {
                for (var trigger : spell.passive.triggers) {
                    if (evaluateTrigger(spellEntry, trigger, event)) {
                        SpellTarget.SearchResult targetResult;
                        if (spell.target.type == Spell.Target.Type.FROM_TRIGGER) {
                            if (event.target == null && event.location != null) {
                                targetResult = SpellTarget.SearchResult.of(event.location);
                            } else {
                                List<Entity> targets = List.of(event.target(trigger));
                                targetResult = SpellTarget.SearchResult.of(targets);
                            }
                        } else {
                            targetResult = SpellTarget.findTargets(player, spellEntry, SpellTarget.SearchResult.empty(), true);
                        }
                        if (trigger.fire_delay > 0) {
                            ((WorldScheduler)player.getWorld()).schedule(trigger.fire_delay - 1, () -> {
                                SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                            });
                        } else {
                            SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                        }
                        break;
                    }
                }
            }
        }
    }

private static void groundSlamEntity(Player attacker, LivingEntity target, ItemModularHandheld item, ItemStack itemStack, Vec3 origin,
            double damageMultiplier, int slowDuration, double momentumEfficiency, int revengeLevel) {
        ServerScheduler.schedule(target.blockPosition().distManhattan(BlockPos.containing(origin)) - 3, () -> {
            float knockback = momentumEfficiency > 0 ? 0.1f : 0.5f;

            AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockback, knockback);

            if (momentumEfficiency > 0) {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.GENERIC_BIG_FALL, SoundSource.PLAYERS, 1, 0.7f);
            } else {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.9f);
            }

            if (result != AbilityUseResult.fail) {
                if (slowDuration > 0) {
                    target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, slowDuration, 1, false, true));
                }

                if (momentumEfficiency > 0) {
                    double velocity = momentumEfficiency;
                    velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                    target.push(0, velocity, 0);
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, 40, 0, false, false));
                }

                if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
                    RevengeTracker.removeEnemySynced((ServerPlayer) attacker, target);
                }
            }

            if (result == AbilityUseResult.crit) {
                RandomSource rand = target.getRandom();
                CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                        world.sendParticles(ParticleTypes.CRIT,
                                target.getX(), target.getY(), target.getZ(), 10,
                                rand.nextGaussian() * 0.3, rand.nextGaussian() * 0.5, rand.nextGaussian() * 0.3, 0.1f));
            }
        });
    }

private void setBlock(ServerLevel level, BlockPos pos) {
        if (delay > 0 || randomDelay > 0) {
            int actualDelay = delay + (randomDelay > 0 ? level.getRandom().nextInt(randomDelay) : 0);
            ServerScheduler.schedule(actualDelay, () -> {
                if (blockState.canSurvive(level, pos) && testRequirements(level, level.getBlockState(pos), pos)) {
                    level.setBlock(pos, blockState, Block.UPDATE_ALL);
                    if (particle != null) {
                        level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                                8, 0.5, 0.5, 0.5, 0.1);
                    }
                    if (sound != null) {
                        level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
                    }
                }
            });
            if (intervalParticle != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    ServerScheduler.schedule(i * fxInterval, () -> level.sendParticles(intervalParticle, pos.getX() + 0.5, pos.getY() + 0.5,
                            pos.getZ() + 0.5,
                            8, 0.5, 0.5, 0.5, 0.1));
                }
            }
            if (intervalSound != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    float volume = intervalSound.volume + i * intervalSoundVolumeChange;
                    float pitch = intervalSound.pitch + i * intervalSoundPitchChange;
                    ServerScheduler.schedule(i * fxInterval, () -> level.playSound(null, pos, intervalSound.type, SoundSource.PLAYERS, volume,
                            pitch));
                }
            }
        } else {
            level.setBlock(pos, blockState, Block.UPDATE_ALL);
            if (particle != null) {
                level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                        8, 0.5, 0.5, 0.5, 0.1);
            }
            if (sound != null) {
                level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
            }
        }
    }

public boolean checkAndClear(ServerLevel level) {
		AABB bounds = getStructureBounds(level);

		if (bounds == null)
			return false;

		if (!level.isLoaded(BlockPos.containing(bounds.getCenter())))
			return true;

		List<Player> players = getPlayersInside(level, bounds);
		List<Entity> entities = getEntitiesInside(level, bounds);

		if (!players.isEmpty()) {
			boolean keepArena = false;

			for (Entity entity : entities) {
				if (entity instanceof ItemEntity || entity.getType().is(Tags.EntityTypes.BOSSES)) {
					keepArena = true;

					break;
				}
			}

			if (keepArena)
				return false;

			for (Player player : players) {
				AoAScheduler.schedule(1, tick -> {
					ServerPlayer pl = (ServerPlayer)player;
					PlayerUtil.resetToDefaultStatus(pl);
					pl.teleportTo(pl.serverLevel(), 17.5d, 452.5d, 3.5d, Set.of(), 0, pl.getXRot());
					InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);
					PlayerUtil.getAdventPlayer(pl).storage.returnStoredItems();
				});
			}
		}

		for (Entity entity : entities) {
			entity.discard();
		}

		return true;
	}

@SubscribeEvent
        public static void onTridentUse(LivingEntityUseItemEvent.Stop event)
        {
            LivingEntity entity = event.getEntity();
            ItemStack stack = event.getItem();

            if (!entity.level().isClientSide())
            {
                TaskScheduler.scheduleServer(() ->
                {
                    if (stack.getItem() instanceof TridentItem && EnchantmentHelper.getRiptide(stack) > 0 && !entity.isInWaterOrBubble())
                    {   Temperature.removeModifiers(entity, Trait.WORLD, WaterTempModifier.class);
                    }
                }, 5);
            }
        }

@SubscribeEvent
        public static void initModifiersOnEntity(EntityJoinLevelEvent event)
        {
            if (event.getEntity() instanceof LivingEntity living && !living.level().isClientSide()
            && isTemperatureEnabled(living))
            {
                getTemperatureCap(living).ifPresent(cap ->
                {
                    // Add default modifiers every time the entity joins the world
                    Map<Trait, List<TempModifier>> modifiers = gatherTempModifiers(living);
                    cap.clearModifiers();
                    cap.setModifiers(modifiers);
                    TaskScheduler.scheduleServer(() ->
                    {   cap.tick(living);
                        Temperature.updateTemperature(living, cap, true);
                        Temperature.updateModifiers(living, cap);
                    }, 1);
                });
            }
        }

@Override
    public Result onEaten(ItemStack item, Chameleon entity, Entity thrower)
    {
        if (!entity.level().isClientSide)
        {
            // Flag for searching
            entity.setSearching(true);

            // Create a new thread to look for the biome
            Thread searchThread = new Thread(null, () ->
            {
                // Search for a cold biome
                BlockPos entityPos = WorldHelper.sublevelToWorld(entity.level(), entity.blockPosition());
                Pair<BlockPos, Holder<Biome>> biomePair = ((ServerLevel) entity.level()).findClosestBiome3d(biome -> this.biomePredicate.test(entity.level(), biome), entityPos, 2000, 32, 64);

                if (biomePair != null)
                {
                    TaskScheduler.scheduleServer(() ->
                    {
                        // Set the chameleon to track this position
                        entity.setTrackingPos(biomePair.getFirst());

                        WorldHelper.playEntitySound(ModSounds.CHAMELEON_FIND, entity, entity.getSoundSource(), 1.2f, entity.getVoicePitch());
                        WorldHelper.spawnParticleBatch(entity.level(), ParticleTypes.HAPPY_VILLAGER, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 1, 1, 1, 6, 0.01);

                        // Stop searching
                        entity.setSearching(false);
                    }, (int) (Math.random() * 20 + 40));
                }
                else
                {
                    TaskScheduler.scheduleServer(() ->
                    {
                        WorldHelper.spawnParticleBatch(entity.level(), ParticleTypes.SMOKE, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 1, 1, 1, 6, 0.01);

                        // Stop searching
                        entity.setSearching(false);
                    }, (int) (Math.random() * 20 + 40));
                }
            }, "(Cold Sweat) Chameleon search thread");
            // Execute the search thread
            searchThread.start();
        }
        return Result.SUCCESS;
    }

@SubscribeEvent
    public static void onShearGoat(PlayerInteractEvent.EntityInteract event)
    {
        Entity entity = event.getTarget();
        Player player = event.getEntity();
        ItemStack stack = event.getItemStack();

        if (entity instanceof LivingEntity living && (!(living instanceof AgeableMob ageable) || !ageable.isBaby())
        && !entity.level().isClientSide && stack.is(Tags.Items.SHEARS))
        {
            getFurCap(living).ifPresent(cap ->
            {
                if (cap.isSheared())
                {   event.setResult(PlayerInteractEvent.Result.DENY);
                    return;
                }

                // Use shears
                player.swing(event.getHand(), true);
                shear(living, player);
                if (!player.getAbilities().instabuild)
                {   stack.hurtAndBreak(1, player, (p) -> p.broadcastBreakEvent(player.getUsedItemHand()));
                }

                // Random chance to ram the player when sheared
                if (living instanceof Goat goat && !player.getAbilities().instabuild && goat.level().getDifficulty() != Difficulty.PEACEFUL
                && !goat.level().isClientSide && goat.getRandom().nextDouble() < 0.4)
                {
                    // Set ram cooldown ticks
                    goat.getBrain().setMemory(MemoryModuleType.RAM_COOLDOWN_TICKS, 30);
                    // Stop active goals
                    for (WrappedGoal goal : goat.goalSelector.getAvailableGoals())
                    {
                        if (goal.isInterruptable())
                        {   goal.stop();
                        }
                    }

                    // Start lowering head
                    TaskScheduler.scheduleServer(() ->
                    {
                        ClientboundEntityEventPacket packet = new ClientboundEntityEventPacket(goat, (byte) 58);
                        ((ServerChunkCache) goat.level().getChunkSource()).broadcastAndSend(goat, packet);
                    }, 5);

                    // Look at player
                    BehaviorUtils.lookAtEntity(goat, player);
                    // Stop walking
                    goat.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);

                    // Set ram target to player pos
                    goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                    TaskScheduler.scheduleServer(() ->
                    {
                        if (player.distanceTo(goat) <= 10)
                        {
                            goat.playSound(goat.isScreamingGoat() ? SoundEvents.GOAT_SCREAMING_PREPARE_RAM : SoundEvents.GOAT_PREPARE_RAM, 1.0F, 1.0F);
                            goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                        }
                    }, 30);

                    // Trigger ram
                    goat.getBrain().setActiveActivityIfPossible(Activity.RAM);
                }
                event.setResult(PlayerInteractEvent.Result.ALLOW);
            });
        }
    }

public void tick()
    {
        if ((this.target == null || this.target.isRemoved()) && this.entity.getEatTimer() <= 0)
        {
            this.stop();
            return;
        }

        // Look at target position
        this.lookPos = this.target.position().add(this.target.getDeltaMovement());
        this.entity.getLookControl().setLookAt(lookPos);

        if (this.entity.getEatTimer() <= 0)
        {
            // Move to the target
            PathNavigation navigator = this.entity.getNavigation();
            Path path = navigator.createPath(target, 0);
            if (path != null) navigator.moveTo(path, 1.5);

            // Update look position

            // If within 1.5 blocks, eat the item
            if (Math.sqrt(this.entity.distanceToSqr(this.target)) < 1.5 && Math.abs(this.entity.getY() - this.target.getY()) < 1 && this.target.isAlive())
            {
                navigator.stop();
                this.entity.getLookControl().setLookAt(lookPos);

                // Play tongue stretch animation
                this.entity.eatAnimation();

                // Play tongue out sound
                WorldHelper.playEntitySound(ModSounds.CHAMELEON_TONGUE_OUT, this.entity, this.entity.getSoundSource(), 1, (float) Math.random() * 0.2f + 0.9f);

                // Remove target item
                TaskScheduler.scheduleServer(() ->
                {
                    if (this.target != null && this.target.isAlive() && !this.target.isRemoved())
                    {
                        this.entity.onEatEntity(this.target);
                        this.target.remove(Entity.RemovalReason.KILLED);

                        if (this.target instanceof ItemEntity item)
                        {   this.entity.onItemPickup(item);

                            Entity thrower = item.getOwner();
                            if (thrower != null)
                            {
                                if (item.getItem().getCount() > 0)
                                {   ItemStack stack = item.getItem().copy();
                                    stack.shrink(1);
                                    if (!stack.isEmpty())
                                    {   ItemEntity remainingStack = WorldHelper.entityDropItem(this.entity, stack);
                                        remainingStack.setThrower(thrower.getUUID());
                                        remainingStack.getPersistentData().putUUID("Recipient", this.entity.getUUID());
                                    }
                                }
                            }
                        }

                        // Play tongue in sound
                        WorldHelper.playEntitySound(ModSounds.CHAMELEON_TONGUE_IN, this.entity, this.entity.getSoundSource(), 1, (float) Math.random() * 0.2f + 0.9f);
                    }
                }, this.entity.getEatAnimLength() / 2 + 2);

                // Send the entity toward the chameleon
                TaskScheduler.scheduleServer(() ->
                {
                    this.target.setDeltaMovement(this.entity.position().subtract(this.target.position()).normalize().scale(0.75));
                }, this.entity.getEatAnimLength() / 2);
            }

            this.entity.goalSelector.getRunningGoals().forEach(goal ->
            {
                Goal g = goal.getGoal();
                if (g instanceof TemptGoal || g instanceof LookAtPlayerGoal || g instanceof RandomLookAroundGoal || g instanceof LazyLookGoal)
                {
                    this.stoppedTasks = true;
                    goal.stop();
                }
            });
        }
    }

@Override
    public boolean apply(ResourceLocation[] unlockedEffects, ItemStack upgradedStack, String slot, boolean isReplacing, Player player,
            ItemStack[] preMaterials, Map<ToolAction, Integer> tools, Level world, UpgradeSchematic schematic, BlockPos pos, BlockState blockState,
            boolean consumeResources, ItemStack[] postMaterials, float severity) {

        if (consumeResources && !world.isClientSide() && world.getRandom().nextFloat() < chance) {
            ServerLevel serverLevel = (ServerLevel) world;
            if (randomOriginDistance > 0) {
                pos = pos.offset(getRandomOffset(world.getRandom(), randomOriginDistance));
            }
            pos = serverLevel.findLightningTargetAround(pos);

            if (delayTicks > 0) {
                BlockPos finalPos = pos;
                RandomSource random = world.getRandom();
                for (int i = 0; i < delayTicks; i += 5) {
                    Vec3 particlePos = Vec3.atBottomCenterOf(pos)
                            .add(random.nextGaussian() * 0.3f, random.nextFloat() * 0.5f, random.nextGaussian() * 0.3f);

                    int randomDelay = random.nextInt(4);
                    ServerScheduler.schedule(i + randomDelay, () -> serverLevel.sendParticles(ParticleTypes.ELECTRIC_SPARK, particlePos.x,
                            particlePos.y, particlePos.z, 4, 0, 0, 0, 0));
                }
                ServerScheduler.schedule(delayTicks, () -> spawnLightningBolt(serverLevel, finalPos, (ServerPlayer) player));
            } else {
                spawnLightningBolt(serverLevel, pos, (ServerPlayer) player);
            }

            return true;
        }
        return false;
    }

@Override
    public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

        double damageMultiplier = item.getEffectLevel(itemStack, isDefensive ? ItemEffect.abilityDefensive : ItemEffect.overpower) / 100f;
        double efficiency = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

        if (overchargeBonus > 0) {
            damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
        }

        int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
        if (comboLevel > 0) {
            damageMultiplier += comboLevel * ComboPoints.get(attacker) / 100d;
        }

        if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
            damageMultiplier += revengeLevel / 100d;
        }

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.1f, 0.1f);
        if (result != AbilityUseResult.fail) {
            int currentAmplifier = Optional.ofNullable(target.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);

            int amplifier = currentAmplifier + 2;

            if (isDefensive) {
                amplifier--;
            }

            if (overchargeBonus > 0) {
                amplifier += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
            }

            int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
            if (momentumLevel > 0 && currentAmplifier > -1) {
                double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
                double velocity = momentumLevel / 100d;
                velocity += momentumEfficiency * (currentAmplifier + 1);

                velocity += momentumEfficiency * Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                        .map(MobEffectInstance::getAmplifier)
                        .map(amp -> amp + 1)
                        .orElse(0);

                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);

                if (velocity > 0) {
                    target.push(0, velocity, 0);
                }
            }


            int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationLevel > 0 && !target.isAlive()) {
                ServerScheduler.schedule(0, () -> attacker.removeEffect(ExhaustedPotionEffect.instance));

            }

            target.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (efficiency * 20), amplifier, false, true));

            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 0.8f);
        } else {
            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.8f);
        }


        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);
        item.applyDamage(2, itemStack, attacker);
    }

public static void breakBlocks(ItemModularHandheld item, ItemStack itemStack, int effectLevel, ServerLevel world, BlockState state, BlockPos pos, LivingEntity entity) {
        Player player = CastOptional.cast(entity, Player.class).orElse(null);

        if (player != null && effectLevel > 0) {
            Vec3 entityPosition = entity.getEyePosition(0);
            double lookDistance = Optional.ofNullable(entity.getAttribute(ForgeMod.BLOCK_REACH.get()))
                    .map(AttributeInstance::getValue)
                    .orElse(5d);

            Vec3 lookingPosition = entity.getLookAngle().scale(lookDistance).add(entityPosition);
            BlockHitResult rayTrace = world.clip(new ClipContext(entityPosition, lookingPosition,
                    ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity));

            Direction direction = rayTrace.getType() == HitResult.Type.BLOCK
                    ? rayTrace.getDirection().getOpposite()
                    : Direction.orderedByNearest(entity)[0];

            float referenceHardness = state.getDestroySpeed(world, pos);
            ToolAction referenceTool = ToolActionHelper.getAppropriateTools(state).stream()
                    .filter(tool -> item.canPerformAction(itemStack, tool))
                    .findFirst()
                    .orElse(null);

            if (referenceTool != null && item.getToolLevel(itemStack, referenceTool) > 0) {
                double critMultiplier = CritEffect.rollMultiplier(entity.getRandom(), item, itemStack);
                if (critMultiplier != 1) {
                    effectLevel *= critMultiplier;
                    world.sendParticles(ParticleTypes.ENCHANTED_HIT, pos.getX() + .5f, pos.getY() + .5f, pos.getZ() + .5f, 15, 0.2D, 0.2D, 0.2D, 0.0D);
                }

                Vec3i limiter = getLimiter(item, direction, player.getDirection(), itemStack);

                List<BlockPos> positions = new LinkedList<>(getRegularOffsets(pos, pos, limiter));
                List<BlockPos> backupPositions = new LinkedList<>(getBackupOffsets(pos, pos, limiter));

                int blockCount = effectLevel;
                ServerScheduler.schedule(player.getRandom().nextInt(3), () -> breakRecursive(world, player, item, itemStack, direction, pos,
                        limiter, positions, backupPositions, referenceHardness, referenceTool, blockCount));

                item.applyDamage(effectLevel, itemStack, entity);
                item.tickProgression(entity, itemStack, Mth.ceil(effectLevel / 2d));
            }
        }
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        var stack = player.getItemInHand(hand);

        if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").canPlayerUse(player))
            return InteractionResultHolder.pass(stack);

        if (player.isShiftKeyDown() && this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getRankModifierData("salvo").isEnabled()) {
            if (!level.isClientSide()) {
                var hit = EntityUtils.rayTraceEntity(player, entity -> entity instanceof LivingEntity living && !living.isDeadOrDying() && !EntityUtils.isAlliedTo(player, living) && !living.is(player), 64D);

                if (!(hit instanceof EntityHitResult entityHit) || !(entityHit.getEntity() instanceof LivingEntity target))
                    return InteractionResultHolder.pass(stack);

                var stacks = this.getHealingStacks(stack);

                if (stacks.isEmpty())
                    return InteractionResultHolder.pass(stack);

                var look = player.getLookAngle();
                var eye = player.getEyePosition();
                var right = look.cross(new Vec3(0, 1, 0));

                if (right.lengthSqr() < 1e-4)
                    right = new Vec3(1, 0, 0);

                var up = look.cross(right).normalize();
                right = right.normalize();

                var count = stacks.size();
                var radius = 0.6D;
                var basePos = eye.subtract(look.scale(0.75D));

                for (int i = 0; i < count; i++) {
                    var healingStack = stacks.get(i);
                    var projectileDamage = Math.max(0F, healingStack.remainingHeal());

                    var angle = (Math.PI * 2D / count) * i + player.getRandom().nextDouble() * (Math.PI / count);
                    var offset = right.scale(Math.cos(angle) * radius).add(up.scale(Math.sin(angle) * radius));
                    var spawnPos = basePos.add(offset);

                    ServerScheduler.schedule(i * 2, () -> {
                        var projectile = new SelfSacrificeProjectileEntity(RelicsEntities.SELF_SACRIFICE_PROJECTILE.get(), level);

                        projectile.setOwner(player);
                        projectile.setPos(spawnPos);
                        projectile.setStack(stack);
                        projectile.setDeltaMovement(look.scale(0.25F).add(offset.normalize().scale(0.25F)).add(0, 0.05F, 0));
                        projectile.setDamage(projectileDamage);
                        projectile.setTarget(target);
                        projectile.setFlawless(this.getRelicData(player, stack).isVisuallyFlawless());

                        level.addFreshEntity(projectile);

                        this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatisticData().getMetricData("projectiles_created").addValue(1);
                    });
                }

                this.setHealingStacks(stack, List.of());
            }

            return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
        }

        if (!level.isClientSide()) {
            if (player.getHealth() / player.getMaxHealth() < 0.33F || this.getHealingStacks(stack).size() >= this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatData("stacks").getValue())
                return InteractionResultHolder.pass(stack);

            var damage = this.getHealthCost(player);

            var remaining = Math.max(0F, player.getHealth() - 1F);

            damage = Math.min(damage, remaining);

            player.invulnerableTime = 0;
            player.hurt(level.damageSources().magic(), damage);

            this.getRelicData(player, stack).getLevelingData().addExperience("sacrifice", "self_inflicted", 1);

            this.addHealingStack(player, stack, this.buildHealingStack(player));
        }

        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }

public static boolean fallProjectile(World world, LivingEntity caster, Entity target, @Nullable Vec3d targetLocation, RegistryEntry<Spell> spellEntry, ImpactContext context, int sequenceIndex) {
        if (world.isClient) {
            return false;
        }

        Vec3d targetPosition = (target != null) ? target.getPos() : targetLocation;
        if (targetPosition == null) {
            return false;
        }

        var spell = spellEntry.value();
        var meteor = spell.deliver.meteor;
        var height = meteor.launch_height;
        var launchPoint = targetPosition.add(0, height, 0);
        var data = spell.deliver.meteor;
        var projectileData = data.projectile;
        var mutableLaunchProperties = data.launch_properties.copy();
        var mutablePerks = projectileData.perks.copy();
        var scaleMultiplier = 1F;
        var launchRadius = meteor.launch_radius;

        for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
            if (modifier.projectile_launch != null) {
                mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
            }
            if (modifier.projectile_perks != null) {
                mutablePerks.mutatingCombine(modifier.projectile_perks);
            }
            scaleMultiplier += modifier.projectile_scale_multiply;
            launchRadius += modifier.meteor_launch_radius_add;
        }

        var projectile = new SpellProjectile(world, caster,
                launchPoint.getX(), launchPoint.getY(), launchPoint.getZ(),
                SpellProjectile.Behaviour.FALL, spellEntry, context, mutablePerks);
        projectile.setScaleMultiplier(scaleMultiplier);

        if (SpellEvents.PROJECTILE_FALL.isListened()) {
            SpellEvents.PROJECTILE_FALL.invoke((listener) -> listener.onProjectileLaunch(new SpellEvents.ProjectileLaunchEvent(projectile, mutableLaunchProperties, caster, target, spellEntry, context, sequenceIndex)));
        }

        projectile.setYaw(0);
        projectile.setPitch(90);

        if (launchSequenceEligible(sequenceIndex, meteor.divergence_requires_sequence)) {
            projectile.setVelocity( 0, - 1, 0, mutableLaunchProperties.velocity, 0.5F, projectileData.divergence);
        } else {
            projectile.setVelocity(new Vec3d(0, - mutableLaunchProperties.velocity, 0));
        }
        if (launchSequenceEligible(sequenceIndex, meteor.follow_target_requires_sequence)) {
            projectile.setFollowedTarget(target);
        } else {
            projectile.setFollowedTarget(null);
        }
        if (launchRadius > 0 && launchSequenceEligible(sequenceIndex, meteor.offset_requires_sequence)) {
            var randomAngle = Math.toRadians(world.random.nextFloat() * 360);
            var offset = (new Vec3d(launchRadius, 0, 0)).rotateY((float) randomAngle);
            projectile.setPosition(projectile.getPos().add(offset));
        }

        projectile.prevYaw = projectile.getYaw();
        projectile.prevPitch = projectile.getPitch();
        projectile.range = height;

        world.spawnEntity(projectile);

        if (sequenceIndex == 0 && mutableLaunchProperties.extra_launch_count > 0) {
            for (int i = 0; i < mutableLaunchProperties.extra_launch_count; i++) {
                var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                var nextSequenceIndex = i + 1;
                ((WorldScheduler)world).schedule(ticks, () -> {
                    if (caster == null || !caster.isAlive()) {
                        return;
                    }
                    fallProjectile(world, caster, target, targetLocation, spellEntry, context, nextSequenceIndex);
                });
            }
        }
        return true;
    }

public static void shootProjectile(World world, LivingEntity caster, Entity target, RegistryEntry<Spell> spellEntry, ImpactContext context, int sequenceIndex) {
        if (world.isClient) {
            return;
        }

        var spell = spellEntry.value();
        var launchPoint = LaunchGeometry.launchPoint(caster);
        var data = spell.deliver.projectile;
        var projectileData = data.projectile;
        var mutablePerks = projectileData.perks.copy();
        var mutableLaunchProperties = data.launch_properties.copy();
        var scaleMultiplier = 1F;

        for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
            if (modifier.projectile_launch != null) {
                mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
            }
            if (modifier.projectile_perks != null) {
                mutablePerks.mutatingCombine(modifier.projectile_perks);
            }
            scaleMultiplier += modifier.projectile_scale_multiply;
        }

        var effectiveCaster = context.effectiveCaster(world);
        var owner = effectiveCaster != null ? effectiveCaster : caster;

        var projectile = new SpellProjectile(world, owner,
                launchPoint.getX(), launchPoint.getY(), launchPoint.getZ(),
                SpellProjectile.Behaviour.FLY, spellEntry, context, mutablePerks);
        projectile.setScaleMultiplier(scaleMultiplier);

        if (SpellEvents.PROJECTILE_SHOOT.isListened()) {
            SpellEvents.PROJECTILE_SHOOT.invoke((listener) -> listener.onProjectileLaunch(
                    new SpellEvents.ProjectileLaunchEvent(projectile, mutableLaunchProperties, caster, target, spellEntry, context, sequenceIndex)));
        }
        var velocity = mutableLaunchProperties.velocity;
        var divergence = projectileData.divergence;
        var directionPitch = data.inherit_shooter_pitch ? caster.getPitch() : 0;
        var directionYaw = data.inherit_shooter_yaw ? caster.getYaw() : 0;
        if (data.direct_towards_target && target != null) {
            var directionVector = target.getPos().subtract(caster.getPos()).normalize();
            // Yaw and pitch from distance vector
            directionPitch = (float) VectorHelper.pitchFromNormalized(directionVector);
            directionYaw = (float) VectorHelper.yawFromNormalized(directionVector);
        }
        if (data.inherit_shooter_velocity) {
            projectile.setVelocity(caster, directionPitch, directionYaw, 0, velocity, divergence);
        } else {
            if (data.direction_offsets != null && data.direction_offsets.length > 0
                && (!data.direction_offsets_require_target || target != null)) {
                var baseIndex = context.isChanneled() ? context.channelTickIndex() : sequenceIndex;
                var index = baseIndex % data.direction_offsets.length;
                var offset = data.direction_offsets[index];
                directionPitch += offset.pitch;
                directionYaw += offset.yaw;
            }
            // var look = caster.getRotationVector().normalize();
            var look = caster.getRotationVector(directionPitch, directionYaw).normalize();
            projectile.setVelocity(look.x, look.y, look.z, velocity, divergence);
        }
        // Charge `bonus.range_add` extends the projectile's flight distance (already ratio-scaled).
        var chargeModifier = context.chargeModifier();
        projectile.range = spell.range + (chargeModifier != null ? chargeModifier.range_add : 0F);
        projectile.setPitch(directionPitch);
        projectile.setYaw(directionYaw);

        projectile.setFollowedTarget(target);
        world.spawnEntity(projectile);
        SoundHelper.playSound(world, projectile, mutableLaunchProperties.sound);

        var allowExtraShoot = (context.isChanneled() && mutableLaunchProperties.extra_launch_mod >= 0)
                ? context.channelTickIndex() % mutableLaunchProperties.extra_launch_mod == 0
                : true;
        if (sequenceIndex == 0 && mutableLaunchProperties.extra_launch_count > 0 && allowExtraShoot) {
            for (int i = 0; i < mutableLaunchProperties.extra_launch_count; i++) {
                var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                var nextSequenceIndex = i + 1;
                ((WorldScheduler)world).schedule(ticks, () -> {
                    if (caster == null || !caster.isAlive()) {
                        return;
                    }
                    shootProjectile(world, caster, target, spellEntry, context, nextSequenceIndex);
                });
            }
        }
    }

public static void shootArrow(World world, LivingEntity shooter, RegistryEntry<Spell> spellEntry, SpellExecution.ImpactContext context, int sequenceIndex) {
        var spell = spellEntry.value();
        var shoot_arrow = spell.deliver.shoot_arrow;
        var weaponStack = shooter.getMainHandStack();

        // var weapon = weaponStack.getItem();
        // Using CROSSBOW statically, so arrows fired behave consistently
        // When using any bow, divergence is applied in an unhelpful manner
        var weapon = Items.CROSSBOW;
        if (shoot_arrow != null
                && (world instanceof ServerWorld serverWorld)
                && (weapon instanceof RangedWeaponItem rangedWeapon)) {
            var mutableLaunchProperties = shoot_arrow.launch_properties.copy();
            if (shooter instanceof PlayerEntity player) {
                var spellModifiers = SpellModifiers.of(player, spellEntry);
                for (var modifier: spellModifiers) {
                    if (modifier.projectile_launch != null) {
                        mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
                    }
                }
            }

            ItemStack ammo;
            if (shooter instanceof PlayerEntity player) {
                ammo = player.getProjectileType(weaponStack);
            } else {
                ammo = new ItemStack(Items.ARROW);
            }
            var loadedAmmo = RangedWeaponAccessor.load_SpellEngine(weaponStack, ammo, shooter);
            if (loadedAmmo.isEmpty()) {
                return;
            }

            // Save as active spell
            if (shooter instanceof SpellCaster.Player caster) {
                var shotContext = caster.getArrowShootContext();
                shotContext.firedBySpell = true;
                shotContext.activeSpells.add(spellEntry);
            }
            var divergence = (sequenceIndex == 0) ? 0F : shoot_arrow.divergence;
            // Perform shoot
            ((RangedWeaponAccessor) rangedWeapon).shootAll_SpellEngine(
                    serverWorld,
                    shooter,
                    Hand.MAIN_HAND,
                    weaponStack,
                    loadedAmmo,
                    shoot_arrow.launch_properties.velocity,
                    divergence,
                    shoot_arrow.arrow_critical_strike,
                    null);
            // Arrow perks applied by `RangedWeaponItemMixin`

            // Fixing inconsistent Vanille code, shoot sound is played by `BOW` outside of `shootAll`
            if (weapon instanceof BowItem) {
                world.playSound(
                        null,
                        shooter.getX(),
                        shooter.getY(),
                        shooter.getZ(),
                        SoundEvents.ENTITY_ARROW_SHOOT,
                        SoundCategory.PLAYERS,
                        1.0F,
                        1.0F / (world.getRandom().nextFloat() * 0.4F + 1.2F) + 1 * 0.5F
                );
            }

            if (shooter instanceof SpellCaster.Player caster) {
                caster.setArrowShootContext(ArrowShootContext.empty());
            }

            var extra_launch = mutableLaunchProperties.extra_launch_count;
            if (sequenceIndex == 0 && extra_launch > 0) {
                for (int i = 0; i < extra_launch; i++) {
                    var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                    var nextSequenceIndex = i + 1;
                    ((WorldScheduler)world).schedule(ticks, () -> {
                        if (shooter == null || !shooter.isAlive()) {
                            return;
                        }
                        shootArrow(world, shooter, spellEntry, context, nextSequenceIndex);
                    });
                }
            }
        }
    }

public static void placeCloud(World world, LivingEntity caster,
                                  @Nullable Entity target, @Nullable Vec3d location,
                                  RegistryEntry<Spell> spellEntry, ImpactContext context) {
        var spell = spellEntry.value();
        var clouds = spell.deliver.clouds;
        if (clouds == null || clouds.isEmpty()) {
            return;
        }
        if (target == null && location == null) {
            target = caster;
        }

        List<Spell.Modifier> spellModifiers = SpellModifiers.of(caster, spellEntry, context.chargeModifier());
        float extraTimeToLive = 0;
        var extraPlacements = new ArrayList<Spell.EntityPlacement>();
        // Summed cloud bonus, snapshotted onto each cloud below. Magnitudes accumulate; growth timing is
        // taken from the first modifier that actually contributes growth (see radiusForAge merge rules).
        var cloudModifier = new Spell.Modifier.Cloud();
        boolean cloudTimingSet = false;
        for (var spellModifier: spellModifiers) {
            extraTimeToLive += spellModifier.spawn_duration_add;
            extraPlacements.addAll(spellModifier.additional_placements);
            var cm = spellModifier.cloud;
            if (cm != null) {
                cloudModifier.radius_add += cm.radius_add;
                cloudModifier.growth.radius_step += cm.growth.radius_step;
                if (cm.growth.duration_ticks < 0 || cloudModifier.growth.duration_ticks < 0) {
                    cloudModifier.growth.duration_ticks = -1; // "whole life" sentinel wins over any span
                } else {
                    cloudModifier.growth.duration_ticks += cm.growth.duration_ticks;
                }
                if (!cloudTimingSet && cm.growth.radius_step != 0F) {
                    cloudModifier.growth.step_interval = cm.growth.step_interval;
                    cloudModifier.growth.start_tick = cm.growth.start_tick;
                    cloudTimingSet = true;
                }
            }
        }

        var index = 0;
        for (var cloud: clouds) {
            var placements = new ArrayList<Spell.EntityPlacement>();
            placements.add(cloud.placement);
            placements.addAll(cloud.additional_placements);
            if (index == 0) {
                placements.addAll(extraPlacements);
            }
            var base_delay = cloud.delay_ticks;

            for (var placement: placements) {
                var delay = base_delay + placement.delay_ticks;

                SpellCloud entity;
                if (cloud.entity_type_id != null) {
                    var id = Identifier.of(cloud.entity_type_id);
                    var type = Registries.ENTITY_TYPE.get(id);
                    entity = (SpellCloud) type.create(world);
                } else {
                    entity = new SpellCloud(world);
                }
                entity.setOwner(caster);
                entity.onCreatedFromSpell(spellEntry.getKey().get().getValue(), cloud, context, cloud.time_to_live_seconds + extraTimeToLive, cloudModifier);

                if (target != null) {
                    EntityPlacements.applyEntityPlacement(entity, target, target.getPos(), placement);
                } else if (location != null) {
                    EntityPlacements.applyEntityPlacement(caster.getWorld(), entity,
                            caster.getYaw(), caster.getPitch(), null,
                            location, placement);
                } else {
                    continue;
                }


                ((WorldScheduler)world).schedule(delay, () -> {
                    world.spawnEntity(entity);
                    var sound = cloud.spawn.sound;
                    if (sound != null) {
                        SoundHelper.playSound(world, entity, sound);
                    }
                    var spawnVisuals = cloud.spawn.visuals.resolved(Fx.Context.NONE);
                    ParticleHelper.sendBatches(entity, spawnVisuals.particles);
                    ModelEffectHelper.spawn(world, entity.getPos(), entity.getYaw(), spawnVisuals.models, null);
                });

                if (cloud.placement_delay_stacks) {
                    base_delay = delay;
                }
            }
            index += 1;
        }
    }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            var entity = event.getEntity();
            var level = entity.level();
            var random = level.getRandom();

            var damage = event.getNewDamage();
            var health = entity.getHealth();
            var absorption = entity.getAbsorptionAmount();

            if (damage < health)
                return;

            var damageToThreshold = health - 0.1F;
            var remaining = damage - damageToThreshold;
            var diff = absorption - remaining;

            if (diff > 0)
                return;

            for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.LEAFY_MANTLE.get())) {
                var relic = (LeafyMantleItem) stack.getItem();

                if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").canPlayerUse(entity))
                    continue;

                if (diff > 0)
                    break;

                if (!level.isClientSide())
                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("damage_negated").addValue(Math.abs(diff));

                var radius = (int) Math.ceil(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("radius").getValue());
                var heal = (float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("heal").getValue();

                var center = entity.blockPosition();

                var positions = IntStream.rangeClosed(-radius, radius).boxed()
                        .flatMap(dx -> IntStream.rangeClosed(-radius, radius)
                                .boxed()
                                .flatMap(dy -> IntStream.rangeClosed(-radius, radius)
                                        .mapToObj(dz -> new BlockPos(center.getX() + dx, center.getY() + dy, center.getZ() + dz))))
                        .filter(pos -> level.getBlockState(pos).is(BlockTags.LEAVES))
                        .sorted(Comparator.comparingDouble(pos -> pos.distSqr(center)))
                        .toList();

                var potential = positions.size() * heal;

                if (potential + diff < 0)
                    continue;

                var blocks = 0;

                for (var pos : positions) {
                    ServerScheduler.schedule(blocks + random.nextInt(10), () -> {
                        var leaves = new LeavesBlockEntity(RelicsEntities.LEAVES_BLOCK.get(), level);

                        var posVec = new Vec3(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D);

                        var toPlayer = entity.position().subtract(posVec).normalize();
                        var randomVec = new Vec3(MathUtils.randomFloat(random), MathUtils.randomFloat(random), MathUtils.randomFloat(random));
                        var perpendicular = randomVec.subtract(toPlayer.scale(randomVec.dot(toPlayer))).normalize().scale(0.5D + random.nextDouble() * 0.5D);

                        leaves.setParalysis((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("paralysis").getValue());
                        leaves.setDeltaMovement(perpendicular.scale(0.5F + random.nextFloat()));
                        leaves.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                        leaves.setPos(posVec.x(), posVec.y(), posVec.z());
                        leaves.setBlockState(level.getBlockState(pos));
                        leaves.setTarget(entity);
                        leaves.setOwner(entity);
                        leaves.setDamage(heal);
                        leaves.setStack(stack);

                        level.addFreshEntity(leaves);

                        level.destroyBlock(pos, false);

                        if (!level.isClientSide()) {
                            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("leaves_consumed").addValue(1);

                            relic.getRelicData(entity, stack).getLevelingData().addExperience("revival", "consuming_leaves", 1);
                        }
                    });

                    blocks++;

                    diff += heal;

                    if (diff >= 0)
                        break;
                }

                if (blocks > 0) {
                    event.setNewDamage(damageToThreshold);

                    if (diff > 0) {
                        var healAmount = diff;

                        ServerScheduler.schedule(1, () -> {
                            entity.heal(healAmount);
                        });
                    }
                }
            }
        }

@Inject(method = "updateEntityAfterFallOn", at = @At("HEAD"), cancellable = true)
    public void onEntityFall(BlockGetter getter, Entity entity, CallbackInfo ci) {
        if (!(entity instanceof LivingEntity livingEntity))
            return;

        var level = livingEntity.level();

        var waveIndex = 0;

        for (var stack : EntityUtils.findEquippedCurios(livingEntity, RelicsItems.SPRINGY_BOOT.get())) {
            if (!(stack.getItem() instanceof SpringyBootItem relic))
                continue;

            if (relic.isLeaped(stack)) {
                if (relic.getBounceCooldown(stack) <= 0) {
                    if (!livingEntity.level().isClientSide()) {
                        var motion = livingEntity.getKnownMovement();
                        var speed = motion.y();

                        if (speed <= -0.75D) {
                            relic.addBounceCooldown(stack, 5);
                            relic.addLeaps(stack, 1);

                            speed = Math.abs(speed);

                            if (!livingEntity.isShiftKeyDown()) {
                                if (!level.isClientSide()) {
                                    relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "bounce", 1);

                                    relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("secondary_bounces").addValue(1);
                                }

                                level.playSound(null, livingEntity.blockPosition(), RelicsSounds.SPRING_BOING.get(), SoundSource.PLAYERS, (float) Math.clamp(0.5F + speed * 0.5F, 0.5F, 2F), (float) Math.max(0.1F, 2F - speed * 0.75F));

                                NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CBounceFromSurface(livingEntity.getId(), motion.multiply(1F, -1F, 1F).toVector3f()), livingEntity);

                                SpringyBootItem.spawnBounceFog(level, livingEntity, Math.max(1.1D, speed * 0.85D), 12 + Mth.ceil(speed * 2.5D));
                            } else {
                                if (relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getRankModifierData("shockwave").isEnabled()) {
                                    var delayTicks = waveIndex * 20;

                                    var center = livingEntity.blockPosition();
                                    var verticalSpeed = Math.abs(livingEntity.getKnownMovement().y());
                                    var radius = (int) Math.min(25, Math.round((1 + relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("radius").getValue()) * verticalSpeed));
                                    var damage = (float) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("damage").getValue();
                                    var stun = (int) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("stun").getValue() * 20;
                                    var serverLevel = (ServerLevel) level;

                                    relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "create_shockwave", radius);

                                    ServerScheduler.schedule(delayTicks, () -> {
                                        relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwaves_amount").addValue(1);

                                        var poses = new ArrayList<BlockPos>();

                                        for (var i = -radius; i <= radius; i++) {
                                            var r1 = (int) Mth.sqrt(radius * radius - i * i);

                                            for (var j = -r1; j <= r1; j++)
                                                poses.add(center.offset(i, 0, j));
                                        }

                                        for (var step = 0; step <= radius; step++) {
                                            var finalStep = step;

                                            ServerScheduler.schedule(finalStep, () -> {
                                                var height = 0.25F;

                                                poses.stream().filter(pos -> {
                                                    var dx = pos.getX() - center.getX();
                                                    var dz = pos.getZ() - center.getZ();

                                                    var dist = Math.hypot(dx, dz);

                                                    return dist >= finalStep && dist < finalStep + 1;
                                                }).forEach(entryPos -> {
                                                    var centerY = center.getY();
                                                    var maxOffset = 8;

                                                    var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                                                    var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                                                    var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                                                    if (groundY < minAllowedY || groundY > maxAllowedY)
                                                        return;

                                                    var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());
                                                    var shockwave = new SpringyBootShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                                                    shockwave.setDamage(damage);
                                                    shockwave.setStun(stun);
                                                    shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                                                    shockwave.setBlockState(level.getBlockState(surfacePos));
                                                    shockwave.setDeltaMovement(0, height, 0);
                                                    shockwave.setOwner(livingEntity);
                                                    shockwave.setCenter(surfacePos);
                                                    shockwave.setKnockback(1F);
                                                    shockwave.setStack(stack);

                                                    level.addFreshEntity(shockwave);

                                                    var px = surfacePos.getX() + 0.15D + level.random.nextDouble() * 0.7D;
                                                    var pz = surfacePos.getZ() + 0.15D + level.random.nextDouble() * 0.7D;

                                                    var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                                                    if (direction.lengthSqr() < 0.001D)
                                                        direction = new Vec3(level.random.nextDouble() - 0.5D, 0D, level.random.nextDouble() - 0.5D);

                                                    direction = direction.normalize();

                                                    var particleSpeed = 0.008D + level.random.nextDouble() * 0.012D;
                                                    var lifetime = 10 + level.random.nextInt(25);
                                                    var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                                                    var fogMotion = new Vector3f((float) (direction.x * particleSpeed), height / 2F, (float) (direction.z * particleSpeed));

                                                    NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
                                                });
                                            });
                                        }
                                    });

                                    waveIndex++;
                                }
                            }
                        }
                    }
                }

                ci.cancel();
            }
        }
    }

@Override
    protected void onHitBlock(BlockHitResult result) {
        var center = result.getBlockPos();
        var level = this.level();

        ShakeManager.add(level, Shake.builder(this)
                .amplitude(0.075F)
                .duration(5)
                .radius(16)
                .build());

        if (level.isClientSide())
            return;

        var serverLevel = (ServerLevel) level;
        var position = this.position();
        var radius = Math.max(this.getRadius() - this.bounces, 1);

        var ringParticleCount = 250 + random.nextInt(250);

        for (var i = 0; i < ringParticleCount; i++) {
            var angle = 2 * Math.PI * i / ringParticleCount;
            var velocity = new Vec3(Math.cos(angle), 0.15D + random.nextDouble() * 0.1D, Math.sin(angle)).normalize().scale(0.5 + random.nextDouble() * 0.25D);

            var color = this.isFlawless() ? new Color(255, 215, 0) : new Color(50 + random.nextInt(150), 50 + random.nextInt(150), 255);

            NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.75F + random.nextFloat() * 0.25F, 5 + random.nextInt(5), 0.8F), position.toVector3f(), velocity.toVector3f()), this);
        }

        var burstParticleCount = 250 + random.nextInt(100);

        for (var i = 0; i < burstParticleCount; i++) {
            var velocity = new Vec3(random.nextGaussian(), random.nextGaussian(), random.nextGaussian()).normalize().scale(0.1 + random.nextDouble() * 0.25);
            var color = this.isFlawless() ? new Color(255, 235, 100) : new Color(100 + random.nextInt(155), 100 + random.nextInt(155), 255);

            NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat(), 10 + random.nextInt(10), 0.9F), position.toVector3f(), velocity.toVector3f()), this);
        }

        var trailCount = 10;
        var pointCount = 75;
        var maxDistance = 5;

        for (var i = 0; i < trailCount; i++) {
            var direction = new Vec3(random.nextGaussian(), random.nextDouble(), random.nextGaussian()).normalize();

            for (var j = 1; j <= pointCount; j++) {
                var t = j / (double) pointCount;

                var spacedT = Math.pow(t, 1.5);

                var px = position.x + direction.x * spacedT * maxDistance;
                var py = position.y + direction.y * spacedT * maxDistance;
                var pz = position.z + direction.z * spacedT * maxDistance;

                var color = this.isFlawless() ? new Color(255, 200, 50) : new Color(80 + random.nextInt(100), 80 + random.nextInt(100), 255);
                var spark = ParticleUtils.constructSimpleSpark(color, (float) (1F * (1 - t) + 0.1F), 15 + random.nextInt(15), 0.5F);

                NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(spark, new Vector3f((float) px, (float) py, (float) pz), new Vector3f((float) (direction.x * 0.02F), (float) (direction.y * 0.02F), (float) (direction.z * 0.02F))), this);
            }
        }

        if (this.noPhysics || !level.getBlockState(center).blocksMotion())
            return;

        var poses = new ArrayList<BlockPos>();

        for (var i = -radius; i <= radius; i++) {
            var r1 = (int) Mth.sqrt(radius * radius - i * i);

            for (var j = -r1; j <= r1; j++)
                poses.add(center.offset(i, 0, j));
        }

        for (var step = 0; step <= radius; step++) {
            int finalStep = step;

            ServerScheduler.schedule(finalStep, () -> {
                var height = 0.25F;

                poses.stream().filter(pos -> {
                    var dx = pos.getX() - center.getX();
                    var dz = pos.getZ() - center.getZ();
                    var dist = Math.hypot(dx, dz);

                    return dist >= finalStep && dist < finalStep + 1;
                }).forEach(entryPos -> {
                    var centerY = center.getY();

                    int maxOffset = 8;

                    var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                    var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                    var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                    if (groundY < minAllowedY || groundY > maxAllowedY)
                        return;

                    var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());

                    var shockwave = new FallingStarShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                    shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                    shockwave.setBlockState(level.getBlockState(surfacePos));
                    shockwave.setDeltaMovement(0, height, 0);
                    shockwave.setDamage(this.getDamage());
                    shockwave.setOwner(this.getOwner());
                    shockwave.setStack(this.getStack());
                    shockwave.setStun(this.getStun());
                    shockwave.setCenter(surfacePos);
                    shockwave.setKnockback(0.75F);

                    level.addFreshEntity(shockwave);

                    var px = surfacePos.getX() + 0.15D + random.nextDouble() * 0.7D;
                    var pz = surfacePos.getZ() + 0.15D + random.nextDouble() * 0.7D;

                    var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                    if (direction.lengthSqr() < 0.001D)
                        direction = new Vec3(random.nextDouble() - 0.5D, 0D, random.nextDouble() - 0.5D);

                    direction = direction.normalize();

                    var speed = 0.008D + random.nextDouble() * 0.012D;
                    var lifetime = 10 + random.nextInt(25);
                    var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                    var fogMotion = new Vector3f((float) (direction.x * speed), height / 2F, (float) (direction.z * speed));

                    NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
                });
            });
        }

        level.playSound(null, this.blockPosition(), RelicsSounds.FALLING_STAR_FALL.get(), SoundSource.MASTER, 0.5F, 1F + random.nextFloat() + this.bounces * 0.2F);

        var bounceChance = this.getBounceChance();

        if (bounceChance > 0F) {
            if (this.bounced)
                return;

            if (random.nextFloat() <= bounceChance) {
                var normal = Vec3.atLowerCornerOf(result.getDirection().getNormal()).normalize();

                var motion = this.getDeltaMovement();
                var reflected = motion.subtract(normal.scale(2 * motion.dot(normal))).normalize().scale(0.5F + this.getRadius() * 0.075F);

                this.setDeltaMovement(reflected);

                this.bounced = true;
                this.bounces++;

                var stack = this.getStack();

                if (stack.getItem() instanceof MidnightMantleItem relic && this.getOwner() instanceof LivingEntity owner) {
                    relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("starfall").getStatisticData().getMetricData("star_bounces").addValue(1);

                    relic.getRelicData(owner, stack).getLevelingData().addExperience("starfall", "star_bounce", 1);
                }
            } else
                this.discard();
        } else
            this.discard();
    }

public void tick() {
        super.tick();

        if (this.level().isClientSide) {
            if (this.clientSideAttackStarted) {
                --this.lifeTicks;
                if (this.lifeTicks == 14) {
                    double d0 = this.getX();
                    double d1 = this.getY() + 2.0D;
                    double d2 = this.getZ();
                    this.level().addAlwaysVisibleParticle(ModParticle.FLAME_JET.get(), d0, d1, d2, 0, 0, 0);
                }

            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -8) {
                AABB aabb = this.getBoundingBox().inflate(0.1D);
                AABB selection = new AABB(aabb.minX, this.getY() - 0.1D, aabb.minZ, aabb.maxX, this.getY() + 3.5D, aabb.maxZ);
                for(LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, selection)) {
                    this.damage(livingentity);
                }
            }

            if (!this.sentSpikeEvent) {
                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (--this.lifeTicks < 0) {
                this.discard();
            }
        }

    }

@Override
    public void tick() {
        super.tick();

        var level = this.getCommandSenderWorld();

        level.addParticle((ParticleUtils.constructSimpleSpark(new Color(random.nextInt(150), 150 + random.nextInt(50), 200 + random.nextInt(50)), 0.05F, 10, 0.9F)), this.xOld, this.yOld, this.zOld,
                -this.getDeltaMovement().x * 0.1F * random.nextFloat(), -this.getDeltaMovement().y * 0.1F * random.nextFloat(), -this.getDeltaMovement().z * 0.1F * random.nextFloat());

        if (target == null || target.isDeadOrDying() || this.tickCount >= 250) {
            if (!level.isClientSide())
                this.discard();

            return;
        }

        if (this.position().distanceTo(target.getEyePosition()) > 1F) {
            var direction = target.getEyePosition().subtract(this.position()).normalize();
            var motion = this.getDeltaMovement();

            var window = 5;

            if (tickCount > window) {
                var factor = Math.clamp((tickCount - window) * 0.1F, 0F, 1F);

                this.setDeltaMovement(motion.x + (direction.x * factor - motion.x) * factor, motion.y + (direction.y * factor - motion.y) * factor, motion.z + (direction.z * factor - motion.z) * factor);
            }
        } else {
            target.invulnerableTime = 0;

            EntityUtils.hurt(target, level.damageSources().thrown(this, this.getOwner()), getDamage());

            this.discard();
        }
    }

private void HoldAttack(float range, float height, float arc, float damage, int shieldbreakticks) {
        List<LivingEntity> entitiesHit = this.getEntityLivingBaseNearby(range, height, range, range);
        DamageSource damagesource = this.damageSources().mobAttack(this);
        if (!this.level().isClientSide) {
            for (LivingEntity entityHit : entitiesHit) {
                float entityHitAngle = (float) ((Math.atan2(entityHit.getZ() - this.getZ(), entityHit.getX() - this.getX()) * (180 / Math.PI) - 90) % 360);
                float entityAttackingAngle = this.yBodyRot % 360;
                if (entityHitAngle < 0) {
                    entityHitAngle += 360;
                }
                if (entityAttackingAngle < 0) {
                    entityAttackingAngle += 360;
                }
                float entityRelativeAngle = entityHitAngle - entityAttackingAngle;
                float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - this.getZ()) * (entityHit.getZ() - this.getZ()) + (entityHit.getX() - this.getX()) * (entityHit.getX() - this.getX()));
                if (entityHitDistance <= range && (entityRelativeAngle <= arc / 2 && entityRelativeAngle >= -arc / 2) || (entityRelativeAngle >= 360 - arc / 2 || entityRelativeAngle <= -360 + arc / 2)) {
                    if (!(entityHit instanceof Clawdian_Entity) && entityHit != this) {
                        if (!entityHit.getType().is(ModTag.IGNIS_CANT_POKE) && entityHit.isAlive() && this.getPassengers().isEmpty()) {
                            if (entityHit.isShiftKeyDown()) {
                                entityHit.setShiftKeyDown(false);
                            }

                            if (entityHit.hurt(damagesource, 1)) {

                                entityHit.startRiding(this, true);
                                Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> entityHit), new MessageEntityCamera(entityHit.getId(), false));

                            }
                        } else if (!isAlliedTo(entityHit)) {
                            entityHit.hurt(damagesource, (float) (this.getAttributeValue(Attributes.ATTACK_DAMAGE) * damage));
                        }
                    }
                }
            }
        }
    }

private void BodyCheckAttack(float range, float height, float arc, float damage, float hpdamage, int shieldbreakticks, int slowticks, double airborne) {
        List<LivingEntity> entitiesHit = this.getEntityLivingBaseNearby(range, height, range, range);
        if (!this.level().isClientSide) {
            DamageSource damagesource = this.damageSources().mobAttack(this);
            for (LivingEntity entityHit : entitiesHit) {
                float entityHitAngle = (float) ((Math.atan2(entityHit.getZ() - this.getZ(), entityHit.getX() - this.getX()) * (180 / Math.PI) - 90) % 360);
                float entityAttackingAngle = this.yBodyRot % 360;
                if (entityHitAngle < 0) {
                    entityHitAngle += 360;
                }
                if (entityAttackingAngle < 0) {
                    entityAttackingAngle += 360;
                }
                float entityRelativeAngle = entityHitAngle - entityAttackingAngle;
                float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - this.getZ()) * (entityHit.getZ() - this.getZ()) + (entityHit.getX() - this.getX()) * (entityHit.getX() - this.getX()));
                if (entityHitDistance <= range && (entityRelativeAngle <= arc / 2 && entityRelativeAngle >= -arc / 2) || (entityRelativeAngle >= 360 - arc / 2 || entityRelativeAngle <= -360 + arc / 2)) {
                    if (!isAlliedTo(entityHit) && !(entityHit instanceof Ignis_Entity)) {
                        boolean flag = entityHit.hurt(damagesource, (float) (this.getAttributeValue(Attributes.ATTACK_DAMAGE) * damage + entityHit.getMaxHealth() * hpdamage));
                        if (entityHit.isDamageSourceBlocked(damagesource) && entityHit instanceof Player player && shieldbreakticks > 0) {
                            EntityUtil.disableShield(player, shieldbreakticks);
                        }

                        if (flag) {
                            this.playSound(SoundEvents.ANVIL_LAND, 1.5f, 0.8F + this.getRandom().nextFloat() * 0.1F);
                            double d0 = entityHit.getX() - this.getX();
                            double d1 = entityHit.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            entityHit.push(d0 / d2 * 2.5D, airborne, d1 / d2 * 2.5D);
                            if (slowticks > 0) {
                                entityHit.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), slowticks));
                            }
                        }
                    }
                }
            }
        }
    }

