public void damageEntities() {
        double actualRadius = this.radius() * 2.0D;
        List<Entity> list1 = this.level.getEntities(this, new AABB(this.getX() - actualRadius, this.getY() - actualRadius, this.getZ() - actualRadius, this.getX() + actualRadius, this.getY() + 6.0D + actualRadius, this.getZ() + actualRadius), this::canHitEntity);
        for(Entity entity : list1) {
            if (entity instanceof LivingEntity livingEntity) {
                if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                    boolean flag = false;
                    DamageSource damageSource = this.damageSources().lightningBolt();
                    if (this.getOwner() != null) {
                        if (!MobUtil.areAllies(this.getOwner(), livingEntity)) {
                            flag = true;
                            damageSource = ModDamageSource.lightning(this, this.getOwner());
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        if (livingEntity.hurt(damageSource, this.getDamage())){
                            this.hurtEffect(livingEntity);
                        }
                    }
                }
            }
        }
        this.playSound(ModSounds.THUNDER_STRIKE_FAST.get());
    }

@Override
	protected boolean effectOnDamage(DamageSource src, MutableFloat amount, Player player, ItemStack stack) {
		if (!src.is(DamageTypeTags.BYPASSES_ARMOR)) {
			int range = 6;
			@SuppressWarnings("unchecked")
			List<Enemy> mobs = (List<Enemy>) (List<?>) player.level().getEntitiesOfClass(Entity.class, new AABB(player.getX() - range, player.getY() - range, player.getZ() - range, player.getX() + range, player.getY() + range, player.getZ() + range), Predicates.instanceOf(Enemy.class));
			for (Enemy mob : mobs) {
				if (mob instanceof LivingEntity entity) {
					entity.hurt(player.damageSources().playerAttack(player), amount.getValue());
				}
			}

			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.unholyCloak, SoundSource.PLAYERS, 1F, 1F);
			for (int i = 0; i < 90; i++) {
				float rad = i * 4F * (float) Math.PI / 180F;
				float xMotion = (float) Math.cos(rad) * 0.2F;
				float zMotion = (float) Math.sin(rad) * 0.2F;
				WispParticleData data = WispParticleData.wisp(0.6F + (float) Math.random() * 0.2F, 0.4F + (float) Math.random() + 0.25F, 0F, 0F);
				player.level().addParticle(data, player.getX(), player.getY() + 0.5, player.getZ(), xMotion, 0F, zMotion);
			}

			return true;
		}

		return false;
	}

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        float potency = SpellConfig.LeechingDamage.get().floatValue() * WandUtil.damageMultiply();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster) / 2.0F;
            range += WandUtil.getRangeLevel(caster);
        }
        potency += spellStat.getPotency();
        LivingEntity target = this.getTarget(caster, range);
        if (target != null){
            ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_RED);
            Vec3 targetVec = new Vec3(target.getX(), target.getY() + (target.getBbHeight() / 2.0F), target.getZ());
            Vec3 casterVec = new Vec3(caster.getRandomX(1.0F), caster.getEyeY(), caster.getRandomZ(1.0F));
            worldIn.sendParticles(new GatherTrailParticleOption(colorUtil, casterVec), targetVec.x, targetVec.y, targetVec.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
            for (int i = 0; i < 8; ++i) {
                targetVec = new Vec3(target.getRandomX(1.0F), target.getRandomY(), target.getRandomZ(1.0F));
                worldIn.sendParticles(new AbsorbTrailParticleOption(casterVec, 11141120, 10), targetVec.x, targetVec.y, targetVec.z, 1, 0.0, 0.0, 0.0, 0.0);
            }
            if (target.hurt(ModDamageSource.lifeLeech(caster, caster), potency)) {
                if (this.rightStaff(staff)){
                    target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 60, 0));
                }
                this.playSound(worldIn, caster, ModSounds.SOUL_EAT.get());
            }
        }
    }

@Override
	protected void onImpact(RayTraceResult par1RayTraceResult){

		Entity entityHit = par1RayTraceResult.entityHit;

		if(entityHit != null){

			float damage = Spells.thunderbolt.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

			entityHit.attackEntityFrom(
					MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK).setProjectile(),
					damage);

			float knockbackStrength = Spells.thunderbolt.getProperty(KNOCKBACK_STRENGTH).floatValue();

