        DamageSource damageSource = this.damageSources().mobAttack(this);
        if (this.distanceToSqr(entity) < 1.5 && this.isAwake() && this.hasLineOfSight(entity) && entity.hurt(damageSource, 1.0F) && this.tickCount > 20 && this.isAlive()) {
