public static void updateDryingTime(Pig pig, int amount) {
		setDryingTime(pig, Mth.clamp(0, getDryingTime(pig) + amount, MAX_DRYING_TIME));
	}

@SubscribeEvent
	public static void onLivingTick(EntityTickEvent.Post event) {
		Entity entity = event.getEntity();
		Level level = entity.getCommandSenderWorld();

		if (entity instanceof Pig pig && entity.isAlive() && isMuddy(pig)) {
			if (canGetWet(pig)) {
				updateDryingTime(pig, 1);
			} else if (EnvironmentalConfig.COMMON.muddyPigsDryOverTime.get() && (!EnvironmentalConfig.COMMON.muddyPigsOnlyDryInTheNether.get() || level.dimensionType().ultraWarm())) {
				updateDryingTime(pig, -1);
			}
		}
	}

@SubscribeEvent
	public static void onEntityInteract(EntityInteract event) {
		Player player = event.getEntity();
		InteractionHand hand = event.getHand();
		ItemStack stack = event.getItemStack();
		Entity target = event.getTarget();
		Level level = event.getLevel();
		RandomSource random = level.getRandom();

		if (target instanceof Pig pig && target.isAlive()) {
			IDataManager data = ((IDataManager) target);
			if (enabled() && isMuddy(pig)) {
				boolean dried = getDryingTime(pig) <= 0;

				Optional<Item> decoration = getDecoration(pig);
				if (decoration.isEmpty()) {
					removeDecoration(pig);
				}

				boolean allowDecorating = EnvironmentalConfig.COMMON.decoratableMuddyPigs.get();

				if (allowDecorating) {
					if (decoration.isEmpty()) {
						if (stack.is(EnvironmentalItemTags.MUDDY_PIG_DECORATIONS)) {
							data.setValue(EnvironmentalDataProcessors.MUDDY_PIG_DECORATION, BuiltInRegistries.ITEM.getKey(stack.getItem()));
							level.playSound(null, target, dried ? SoundEvents.PACKED_MUD_PLACE : SoundEvents.MUD_PLACE, SoundSource.PLAYERS, 1.0F, 1.0F);
							if (!event.getEntity().isCreative()) stack.shrink(1);
							event.setCancellationResult(InteractionResult.sidedSuccess(level.isClientSide()));
							event.setCanceled(true);
						}
					} else if (stack.canPerformAction(ItemAbilities.SHEARS_CARVE)) {
						level.playSound(null, target, SoundEvents.SNOW_GOLEM_SHEAR, SoundSource.PLAYERS, 1.0F, 1.0F);
						target.gameEvent(GameEvent.SHEAR, player);
						if (!level.isClientSide()) {
							ItemEntity item = target.spawnAtLocation(new ItemStack(decoration.get()), 1.0F);
							item.setDeltaMovement(item.getDeltaMovement().add((random.nextFloat() - random.nextFloat()) * 0.1F, random.nextFloat() * 0.05F, (random.nextFloat() - random.nextFloat()) * 0.1F));
							stack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));
						}
						removeDecoration(pig);
						event.setCancellationResult(InteractionResult.sidedSuccess(level.isClientSide()));
						event.setCanceled(true);
					}
				}

				if (stack.is(EnvironmentalItemTags.MUDDY_PIG_DRYING_ITEMS) && !dried) {
					level.playSound(null, target, SoundEvents.PACKED_MUD_PLACE, SoundSource.PLAYERS, 1.0F, 1.0F);
					if (!event.getEntity().isCreative()) stack.shrink(1);
					setDryingTime(pig, 0);
					event.setCancellationResult(InteractionResult.sidedSuccess(level.isClientSide()));
					event.setCanceled(true);
				} else if (stack.is(Items.BUCKETS_WATER)) {
					level.playSound(null, target, SoundEvents.GENERIC_SPLASH, SoundSource.PLAYERS, 1.0F, 1.0F);
					player.setItemInHand(hand, ItemUtils.createFilledResult(stack, player, stack.getCraftingRemainingItem()));
					player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
					if (!level.isClientSide) {
						ServerLevel serverlevel = (ServerLevel) level;
						for (int i = 0; i < 5; ++i) {
							serverlevel.sendParticles(ParticleTypes.SPLASH, target.getX() + level.random.nextDouble(), target.getY() + 1, target.getZ() + level.random.nextDouble(), 1, 0.0D, 0.0D, 0.0D, 1.0D);
						}
					}

					setMuddy(pig, false);
					setDryingTime(pig, 0);

					if (decoration.isPresent()) {
						if (!level.isClientSide()) {
							ItemEntity item = target.spawnAtLocation(new ItemStack(decoration.get()), 1.0F);
							item.setDeltaMovement(item.getDeltaMovement().add((random.nextFloat() - random.nextFloat()) * 0.1F, random.nextFloat() * 0.05F, (random.nextFloat() - random.nextFloat()) * 0.1F));
							stack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));
						}
						removeDecoration(pig);
					}

					level.playSound(null, target, SoundEvents.BUCKET_EMPTY, SoundSource.BLOCKS, 1.0F, 1.0F);
					event.setCancellationResult(InteractionResult.sidedSuccess(level.isClientSide()));
					event.setCanceled(true);
				}
			}
		}
	}

private boolean causeInternalFallDamage(float f1, float f2, DamageSource damageSource) {
        float[] ret = net.minecraftforge.common.ForgeHooks.onLivingFall(this, f1, f2);
        if (ret == null) return false;
        f1 = ret[0];
        f2 = ret[1];

        int i = this.calculateFallDamage(f1, f2);
        if (i > 0) {
            this.playBlockFallSound();
            this.hurt(damageSource, (float)i);
            return true;
        } else {
            return this.getType().is(EntityTypeTags.FALL_DAMAGE_IMMUNE);
        }
    }

public boolean swallowEntity(Entity entity) {
        if (this.getCatfishSize() == 2 && entity instanceof final Mob mob) {
            this.setHasSwallowedEntity(true);
            final ResourceLocation mobtype = ForgeRegistries.ENTITY_TYPES.getKey(mob.getType());
            if (mobtype != null) {
                this.setSwallowedEntityType(mobtype.toString());
            }
            final CompoundTag tag = new CompoundTag();
            mob.addAdditionalSaveData(tag);
            this.setSwallowedData(tag);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            return true;
        }
        if (this.getCatfishSize() < 2 && entity instanceof final ItemEntity item) {
            this.pickUpItem(item);
        }
        return false;
    }

public void spit() {
        this.setSpitTime(10);
        this.eatCooldown = 60 + random.nextInt(60);
        if (this.getCatfishSize() == 2) {
            if (this.hasSwallowedEntity()) {
                EntityType type = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(this.getSwallowedEntityType()));
                if (type != null) {
                    Entity entity = type.create(level());
                    if (entity instanceof final LivingEntity alive) {
                        alive.readAdditionalSaveData(this.getSwallowedData());
                        alive.setHealth(Math.max(2, alive.getMaxHealth() * 0.25F));
                        alive.setYRot(random.nextFloat() * 360 - 180);
                        alive.setPos(this.getMouthVec());
                        if (level().addFreshEntity(alive)) {
                            this.setHasSwallowedEntity(false);
                            this.setSwallowedEntityType("minecraft:pig");
                            this.setSwallowedData(new CompoundTag());
                        }
                    }
                }
            }
        } else {
            ItemStack itemStack = ItemStack.EMPTY;
            int index = -1;
            if(this.catfishInventory != null){
                for (int i = 0; i < this.catfishInventory.getContainerSize(); i++) {
                    if (!this.catfishInventory.getItem(i).isEmpty()) {
                        itemStack = this.catfishInventory.getItem(i);
                        index = i;
                        break;
                    }
                }
            }
            if (!itemStack.isEmpty()) {
                final Vec3 vec3 = this.getMouthVec();
                final Vec3 vec32 = vec3.subtract(position()).normalize().scale(0.14F);
                final ItemEntity item = new ItemEntity(level(), vec3.x, vec3.y, vec3.z, itemStack, vec32.x, vec32.y, vec32.z);
                item.setDeltaMovement(Vec3.ZERO);
                item.setPickUpDelay(30);
                if (level().addFreshEntity(item) && this.catfishInventory != null) {
                    this.catfishInventory.setItem(index, ItemStack.EMPTY);
                }
            }
        }
    }

private boolean canBlockDamageSource(DamageSource damageSourceIn) {
        Entity entity = damageSourceIn.getDirectEntity();
        boolean flag = false;
        if (entity instanceof AbstractArrow abstractarrow) {
            if (abstractarrow.getPierceLevel() > 0) {
                flag = true;
            }
        }
        if (!damageSourceIn.is(DamageTypeTags.BYPASSES_SHIELD) && this.isDraugrBlocking() && !flag) {
            Vec3 vector3d2 = damageSourceIn.getSourcePosition();
            if (vector3d2 != null) {
                Vec3 vector3d = this.getViewVector(1.0F);
                Vec3 vector3d1 = vector3d2.vectorTo(this.position()).normalize();
                vector3d1 = new Vec3(vector3d1.x, 0.0D, vector3d1.z);
                return vector3d1.dot(vector3d) < 0.0D;
            }
        }
        return false;
    }

