public static void scheduleRequiredAsyncTask(Runnable run, int time, TimeUnit unit) {
		if (scheduler == null)
			serverStartupTasks();

		scheduler.schedule(run, time, unit);
		requiredTasks.add(run);
	}

public static void serverStartupTasks() {
		if (scheduler != null) {
			for (Runnable task : requiredTasks) {
				task.run();
			}

			scheduler.shutdownNow();
		}

		scheduler = Executors.newScheduledThreadPool(1);
	}

public static void serverShutdownTasks() {
		for (Runnable task : requiredTasks) {
			task.run();
		}

		scheduler.shutdownNow();
		scheduler = null;
	}

private boolean tryPush(Direction dir) {
        BlockEntity te = getCachedNeighbor(dir);

        if (te == null) {
            return tryDispense(dir);
        }

        return IOHelper.getInventoryForBlock(te, dir.getOpposite()).map(dstHandler -> {
            validateCachedSlot(pushSlots, dir, dstHandler);

            ItemStack toPush = findNextItem(inventory, pushSlots, dir);
            if (toPush.isEmpty()) {
                // empty inventory
                return false;
            }
            ItemStack excess = ItemHandlerHelper.insertItem(dstHandler, toPush, false);
            int transferred = toPush.getCount() - excess.getCount();
            if (transferred > 0) {
                // success!
                inventory.extractItem(pushSlots.getOrDefault(dir, 0), transferred, false);
                return true;
            } else {
                // this item can't be pushed... move on
                pushSlots.put(dir, scanForward(inventory, pushSlots.getOrDefault(dir, 0)));
            }
            return false;
        }).orElse(false);
    }

private boolean tryDispense(Direction dir) {
        if (getUpgrades(ModUpgrades.DISPENSER.get()) > 0) {
            if (!Block.canSupportCenter(nonNullLevel(), worldPosition, dir.getOpposite())) {
                ItemStack toPush = findNextItem(inventory, pushSlots, dir);
                if (!toPush.isEmpty()) {
                    ItemStack pushed = inventory.extractItem(pushSlots.getOrDefault(dir, 0), toPush.getCount(), false);
                    BlockPos dropPos = worldPosition.relative(dir);
                    PneumaticCraftUtils.dropItemOnGroundPrecisely(pushed, level,dropPos.getX() + 0.5, dropPos.getY() + 0.5, dropPos.getZ() + 0.5);
                    return true;
                }
            }
        }
        return false;
    }

private boolean tryPull(Direction dir) {
        BlockEntity te = getCachedNeighbor(dir);

        if (te == null) {
            return tryMagnet(dir);
        }

        return IOHelper.getInventoryForBlock(getCachedNeighbor(dir), dir.getOpposite()).map(srcHandler -> {
            validateCachedSlot(pullSlots, dir, srcHandler);

            ItemStack toPull = findNextItem(srcHandler, pullSlots, dir);
            if (toPull.isEmpty()) {
                // source inventory is empty
                return false;
            }
            ItemStack excess = ItemHandlerHelper.insertItem(inventory, toPull, false);
            int transferred = toPull.getCount() - excess.getCount();
            if (transferred > 0) {
                // success!
                srcHandler.extractItem(pullSlots.getOrDefault(dir, 0), transferred, false);
                return true;
            } else {
                // this item can't be inserted into this chest... move on to next item next tick
                pullSlots.put(dir, scanForward(inventory, pullSlots.getOrDefault(dir, 0)));
            }
            return false;
        }).orElse(false);
    }

public void areaAttack(){
        for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(16.0D),
                living -> !MobUtil.areAllies(living, this) && living.isAlive())){
            double xPower = this.getX() - livingEntity.getX();
            double yPower = this.getY() - livingEntity.getY();
            double zPower = this.getZ() - livingEntity.getZ();
            double distance = Math.sqrt(xPower * xPower + yPower * yPower + zPower * zPower);
            if (this.distanceToSqr(livingEntity) < 9.0D) {
                if (livingEntity.hurt(this.getServantAttack(), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                    this.playSound(SoundEvents.PLAYER_ATTACK_KNOCKBACK, 1.0F, 1.0F);
                    livingEntity.hurtMarked = true;
                    if (!livingEntity.hasEffect(GoetyEffects.TANGLED.get())) {
                        MobUtil.push(livingEntity, -xPower / distance * 2.0D, -yPower / distance * 2.0D + 0.5D, -zPower / distance * 2.0D);
                    }
                }
            }
        }
    }

private SpiritInfluenceRendererData tickData(IArtificeAcceptor target) {
        ClientLevel level = Minecraft.getInstance().level;
        if (level.getGameTime() == gameTimeCache) {
            return this;
        }
        gameTimeCache = level.getGameTime();
        var activeSpiritType = target.getActiveSpiritType();
        if (activeSpiritType != null) {
            merge(activeSpiritType, 1, (a, b) -> Math.min(a + b, maxValue()));
        }
        for (SpiritArcanaType spiritType : keySet()) {
            if (spiritType.equals(activeSpiritType)) {
                continue;
            }
            merge(spiritType, 1, (a, b) -> Math.max(a - b, 0));
        }
        return this;
    }

private static void damageIfNeeded(UseOnContext context) {
    ItemStack stack = context.getItemInHand();
    Level level = context.getLevel();
    // vanilla tools tend not to call the proper damage methods if player is null, so just manually damage the stack
    // we expect modded items will have the same bug, so just go ahead and damage them. On the chance it works, they get 2 damage, no big deal
    // our tools we know work so ignore them
    if (!level.isClientSide && context.getPlayer() == null && stack.isDamageableItem() && !stack.is(TinkerTags.Items.MODIFIABLE)) {
      // unable to call Forge damageItem as that needs entity access, but its just vanilla broken anyways, right?
      stack.hurt(1, level.getRandom(), null);
      // calling methods again instead of using return as return may be incorrect for custom broken stacks
      if (stack.getDamageValue() >= stack.getMaxDamage()) {
        // but that won't happen, right? will need to consider another workaround in that case.
        stack.shrink(1);
        stack.setDamageValue(0);
        level.playSound(null, context.getClickedPos(), SoundEvents.ITEM_BREAK, SoundSource.BLOCKS, 1.0F, 1.0F);
      }
    }
  }

