	}

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (this.getAnimation() == GUARDIAN_MASS_DESTRUCTION && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }
        Entity entity = source.getDirectEntity();
        if (!this.getIsHelmetless()) {
            if (entity instanceof AbstractArrow) {
                return false;
            }
        }
        if (entity instanceof ShulkerBullet || entity instanceof Ender_Guardian_Bullet_Entity) {
            return false;
        }
        if (entity instanceof AbstractGolem) {
            damage *= 0.5;
        }

        boolean attack = super.hurt(source, damage);
        if(attack) {
            if (this.getIsHelmetless()) {
                this.playSound(SoundEvents.SHULKER_HURT, 1.0f, 0.8f);
            }
        }
        return attack;
    }

public InteractionResult mobInteract(Player player, InteractionHand hand) {
        final ItemStack itemstack = player.getItemInHand(hand);
        final Item item = itemstack.getItem();
        final InteractionResult type = super.mobInteract(player, hand);
        if (!this.level().isClientSide) {
            if (item == Items.SNOW && !this.isSnowy()) {
                this.usePlayerItem(player, hand, itemstack);
                this.permSnow = true;
                this.setSnowy(true);
                this.playSound(SoundEvents.SNOW_PLACE, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                return InteractionResult.SUCCESS;
            }

            if (item instanceof ShovelItem && this.isSnowy()) {
                this.permSnow = false;
                if (!player.isCreative()) {
                    itemstack.hurt(1, this.getRandom(), player instanceof ServerPlayer ? (ServerPlayer) player : null);
                }
                this.setSnowy(false);
                this.playSound(SoundEvents.SNOW_BREAK, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                return InteractionResult.SUCCESS;
            }
        }
        return type;
    }

