public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack,
            @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
        super.perform(attacker, hand, item, itemStack, target, targetPos, hitVec, chargedTicks);

        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
        boolean overextended = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend) > 0;

        double exhaustDuration = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

        if (!attacker.level().isClientSide && !isDefensive) {
            int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);

            int newAmp = 1;

            if (overchargeBonus > 0) {
                newAmp += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
            }

            double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
            if (comboEfficiency > 0 && attacker.getCommandSenderWorld().getRandom().nextFloat() < (comboEfficiency * ComboPoints.get(attacker) / 100f)) {
                newAmp--;

                RandomSource rand = attacker.getCommandSenderWorld().getRandom();
                ((ServerLevel) attacker.getCommandSenderWorld()).sendParticles(ParticleTypes.HAPPY_VILLAGER,
                        attacker.getX(), attacker.getY() + attacker.getBbHeight() / 2, attacker.getZ(), 10,
                        rand.nextGaussian() * 0.3, rand.nextGaussian() * attacker.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f);
            }

            if (target != null && revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                newAmp--;
            }

            if (overextended && !attacker.getFoodData().needsFood()) {
                newAmp = -1;
            }

            if (newAmp > 0) {
                int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
                if (echoLevel > 0) {
                    delayExhaustion(attacker, item, itemStack, (int) (exhaustDuration * 20), newAmp);
                } else {
                    attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (exhaustDuration * 20),
                            newAmp + currentAmp, false, true));
                }
            }
        }

        attacker.causeFoodExhaustion(overextended ? 6 : 1);
        attacker.swing(hand, false);

        int cooldown = getCooldown(item, itemStack);

        if (isDefensive) {
            cooldown = (int) (cooldown * (1 + item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) / 100f));
        }

        if (ComboPoints.canSpend(item, itemStack)) {
            ComboPoints.reset(attacker);
        }

        if (target != null && revengeLevel > 0) {
            RevengeTracker.removeEnemy(attacker, target);
        }

        attacker.getCooldowns().addCooldown(item, cooldown);
    }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity entity = result.getEntity();
        float f = 12.0F;
        if (entity instanceof LivingEntity) {
            LivingEntity livingentity = (LivingEntity) entity;
            f += EnchantmentHelper.getDamageBonus(this.tridentItem, livingentity.getMobType());
        }

        Entity entity1 = this.getOwner();
        DamageSource damagesource = DamageSource.trident(this, entity1 == null ? this : entity1);
        entitiesHit++;
        if (entitiesHit >= getMaxPiercing())
            this.dealtDamage = true;
        SoundEvent soundevent = SoundEvents.TRIDENT_HIT;
        if (entity.hurt(damagesource, f)) {
            if (entity.getType() == EntityType.ENDERMAN) {
                return;
            }

            if (entity instanceof LivingEntity) {
                LivingEntity livingentity1 = (LivingEntity) entity;
                if (entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingentity1, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity1);
                }

                this.doPostHurtEffects(livingentity1);
            }
        }

        float f1 = 1.0F;
        if (this.level instanceof ServerLevel && this.level.isThundering() && EnchantmentHelper.hasChanneling(this.tridentItem)) {
            BlockPos blockpos = entity.blockPosition();
            if (this.level.canSeeSky(blockpos)) {
                LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(this.level);
                lightningboltentity.moveTo(Vec3.atCenterOf(blockpos));
                lightningboltentity.setCause(entity1 instanceof ServerPlayer ? (ServerPlayer) entity1 : null);
                this.level.addFreshEntity(lightningboltentity);
                soundevent = SoundEvents.TRIDENT_THUNDER;
                f1 = 5.0F;
            }
        }

        this.playSound(soundevent, f1, 1.0F);
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the firebomb gets a direct hit
				float damage = Spells.firebomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FIRE).setProjectile(),
						damage);

				if(!MagicDamage.isEntityImmune(DamageType.FIRE, entityHit))
					entityHit.setFire(Spells.firebomb.getProperty(Spell.BURN_DURATION).intValue());
			}

			// Notify clients to play the explosion effect
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.FIREBOMB, posX, posY, posZ, blastMultiplier),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_FIREBOMB_SMASH, 1.5F, rand.nextFloat() * 0.4F + 0.6F);
			this.playSound(WizardrySounds.ENTITY_FIREBOMB_FIRE, 1, 1);

			double range = Spells.firebomb.getProperty(Spell.BLAST_RADIUS).floatValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(range, this.posX, this.posY,
					this.posZ, this.world);

			for(EntityLivingBase target : targets){
				if(target != entityHit && target != this.getThrower()
						&& !MagicDamage.isEntityImmune(DamageType.FIRE, target)){
					// Splash damage does not count as projectile damage
					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FIRE),
							Spells.firebomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);
					target.setFire(Spells.firebomb.getProperty(Spell.BURN_DURATION).intValue());
				}
			}
		}

		this.setDead();
	}

@SubscribeEvent
	public static void onAttackEntityEvent(AttackEntityEvent event){

		ItemStack stack = event.getEntityPlayer().getHeldItemMainhand();

		if(stack.getItem() instanceof ItemLightningHammer && event.getTarget() instanceof EntityLivingBase){

			EntityPlayer wielder = event.getEntityPlayer();
			EntityLivingBase hit = (EntityLivingBase)event.getTarget();

			float attackStrength = wielder.getCooledAttackStrength(0);

			double dx = wielder.posX - hit.posX;
			double dz;
			for(dz = wielder.posZ - hit.posZ; dx * dx + dz * dz < 1.0E-4D; dz = (Math.random() - Math.random())
					* 0.01D){
				dx = (Math.random() - Math.random()) * 0.01D;
			}

			hit.knockBack(wielder, 2 * attackStrength, dx, dz);

			if(attackStrength == 1){ // Only chains when the attack meter is full

				List<EntityLivingBase> nearby = EntityUtils.getLivingWithinRadius(CHAINING_RANGE, hit.posX, hit.posY, hit.posZ, hit.world);

				nearby.remove(hit);
				nearby.remove(wielder);
				// When held, the number of chaining targets is halved
				int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue() / 2;
				while(nearby.size() > maxTargets) nearby.remove(nearby.size() - 1);

				for(EntityLivingBase target : nearby){

					target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(wielder, DamageType.SHOCK), CHAINING_DAMAGE * ((ItemLightningHammer)stack.getItem()).getDamageMultiplier(stack));

					if(hit.world.isRemote){
						ParticleBuilder.create(Type.LIGHTNING).pos(hit.getPositionVector().add(0, hit.height / 2, 0))
								.target(target).spawn(hit.world);
						ParticleBuilder.spawnShockParticles(hit.world, target.posX, target.posY + target.height / 2, target.posZ);
					}

					//target.playSound(WizardrySounds.SPELL_SPARK, 1, 1.5f + 0.4f * world.rand.nextFloat());
				}
			}
		}
	}

protected void onHitEntity(EntityHitResult pResult) {
        Entity target = pResult.getEntity();
        float f = 6.0F;
        float f1 = 0.0F;
        int i = 0;
        Entity owner = this.getOwner();
        if (this.getItem().getItem() instanceof SwordItem swordItem){
            f = swordItem.getDamage();
        }
        if (!this.getItem().isEmpty()) {
            f1 += this.getItem().getEnchantmentLevel(Enchantments.KNOCKBACK);
            i = this.getItem().getEnchantmentLevel(Enchantments.FIRE_ASPECT);
        }
        if (target instanceof LivingEntity livingentity) {
            f += EnchantmentHelper.getDamageBonus(this.getItem(), livingentity.getMobType());
        }
        DamageSource damagesource = ModDamageSource.sword(this, owner == null ? this : owner);
        if (owner instanceof Player player){
            damagesource = this.damageSources().playerAttack(player);
        } else if (owner instanceof Mob mob){
            damagesource = this.damageSources().mobAttack(mob);
        }
        SoundEvent soundevent = SoundEvents.TRIDENT_HIT;
        if (target.hurt(damagesource, f)) {
            if (target instanceof LivingEntity livingTarget) {
                if (owner instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingTarget, owner);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity)owner, livingTarget);
                    ItemHelper.setItemEffect(this.getItem(), livingTarget);
                }
                if (f1 > 0) {
                    double d0 = this.getX() - livingTarget.getX();
                    double d1 = this.getZ() - livingTarget.getZ();
                    livingTarget.knockback(f1 * 0.5F, d0, d1);
                }
                if (i > 0) {
                    livingTarget.setSecondsOnFire(i * 4);
                }

                this.doPostHurtEffects(livingTarget);
            }
        }

        float f2 = 1.0F;
        this.playSound(soundevent, f2, 1.0F);
    }

public void aiStep() {
		if (!this.level().isClientSide() && this.isAlive()) {
			++this.eatTicks;
			if (this.isSitting()) {
				this.getNavigation().stop();
			}
			ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
			if (this.canEatItem(itemstack)) {
				if (this.eatTicks > 600) {
					ItemStack itemstack1 = itemstack.finishUsingItem(this.level(), this);
					if (!itemstack1.isEmpty()) {
						this.setItemSlot(EquipmentSlot.MAINHAND, itemstack1);
					}

					this.eatTicks = 0;
				} else if (this.eatTicks > 560 && this.random.nextFloat() < 0.1F) {
					this.level().broadcastEntityEvent(this, (byte)45);
				}
			}

			LivingEntity livingentity = this.getTarget();
			if (livingentity == null || !livingentity.isAlive()) {
				this.setCrouching(false);
				this.func_213502_u(false);
			}
		}
		if (this.getTarget() != null) {
			if (this.getVehicle() != null) {
				if (this.getVehicle() == this.getTarget() && this.tickCount % 20 == 0) {
					AttributeInstance iattributeinstance = this.getAttribute(Attributes.ATTACK_DAMAGE);
					this.getTarget().hurt(this.damageSources().mobAttack(this), (float) iattributeinstance.getBaseValue());
				}
			}
		}
		if (!this.isNoAi()) {

			if (this.isSleeping() || this.isMovementBlocked()) {
				this.jumping = false;
				this.xxa = 0.0F;
				this.zza = 0.0F;
			}
			super.aiStep();
			if (this.isDakotaraptorAggroed() && this.random.nextFloat() < 0.05F) {
			}
		}
	}

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		if(caster.onGround){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(
					getProperty(EFFECT_RADIUS).floatValue() * modifiers.get(WizardryItems.blast_upgrade),
					caster.posX, caster.posY, caster.posZ, world);

			for(EntityLivingBase target : targets){
				if(AllyDesignationSystem.isValidTarget(caster, target)){
					// Base damage is 4 hearts no matter where the target is.
					target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
							getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

					if(!world.isRemote){

						double dx = target.posX - caster.posX;
						double dz = target.posZ - caster.posZ;
						// Normalises the velocity.
						double vectorLength = MathHelper.sqrt(dx * dx + dz * dz);
						dx /= vectorLength;
						dz /= vectorLength;

						target.motionX = getProperty(REPULSION_VELOCITY).floatValue() * dx;
						target.motionY = 0;
						target.motionZ = getProperty(REPULSION_VELOCITY).floatValue() * dz;

						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}
					}
				}
			}

			if(world.isRemote){
				ParticleBuilder.create(Type.LIGHTNING_PULSE).pos(caster.posX, caster.posY
						+ GeometryUtils.ANTI_Z_FIGHTING_OFFSET, caster.posZ)
				.scale(modifiers.get(WizardryItems.blast_upgrade)).spawn(world);
			}

			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}
		return false;
	}

@Override
    public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float area = this.getAreaOfEffect() / 2;
            float f = 1.5F + area;
            ColorUtil color = ColorUtil.WHITE;
            ServerParticleUtil.windParticle(serverLevel, color, (f - 1.0F) + serverLevel.getRandom().nextFloat() * 0.5F, 0.0F, this.getId(), this.position());
            ServerParticleUtil.windParticle(serverLevel, color, f + serverLevel.getRandom().nextFloat() * 0.5F, 0.0F, this.getId(), this.position());

            if (this.tickCount == 20){
                List<Entity> targets = new ArrayList<>();
                float area0 = 1.0F + area;
                AABB aabb = this.getBoundingBox();
                AABB aabb1 = new AABB(aabb.minX - area0, aabb.minY - 1.0F, aabb.minZ - area0, aabb.maxX + area0, aabb.maxY + 1.0F, aabb.maxZ + area0);
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb1)){
                    if (this.getOwner() != null) {
                        if (entity != this.getOwner() && !MobUtil.areAllies(entity, this.getOwner())) {
                            targets.add(entity);
                        }
                    } else {
                        targets.add(entity);
                    }
                }
                if (!targets.isEmpty()){
                    for (Entity entity : targets) {
                        if (entity instanceof LivingEntity livingEntity) {
                            livingEntity.hurt(ModDamageSource.windBlast(this, this.getOwner()), this.getDamage());
                            MobUtil.push(livingEntity, 0.0D, 1.0D, 0.0D);
                        } else if (entity instanceof AbstractCyclone cyclone && cyclone.getTrueOwner() != this.getOwner()){
                            cyclone.trueRemove();
                        }
                    }
                }
            }
        }
        if (this.tickCount == 1){
            this.playSound(ModSounds.UPDRAFT_BLAST.get(), 0.9F, 1.5F);
        }
        if (this.tickCount > 20){
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.25D, 0.0D));
            this.move(MoverType.SELF, this.getDeltaMovement());
        }
        if (this.tickCount % 30 == 0){
            this.discard();
        }
    }

private static void spawnInfinityDrops(Level level, BlockPos pos, FireCraftingRecipe recipe) {
        var randomSource = level.getRandom();
        boolean didDrop = false;

        for (var result : recipe.results()) {
            float dropChance = level.getRandom().nextFloat();
            if (dropChance >= result.chance()) {
                continue;
            }

            int itemCount = level.getRandom().nextIntBetweenInclusive(result.minCount(), result.maxCount());
            if (itemCount <= 0) {
                continue;
            }

            ItemStack resultStack = result.result().copy();
            resultStack.setCount(itemCount);

            // Get random offset
            double x = randomSource.nextFloat() * 0.5f + 0.25f;
            double y = randomSource.nextFloat() * 0.5f + 0.25f;
            double z = randomSource.nextFloat() * 0.5f + 0.25f;
            ItemEntity itemEntity = new ItemEntity(level, pos.getX() + x, pos.getY() + y, pos.getZ() + z, resultStack);
            itemEntity.setDefaultPickUpDelay();

            // Make it survive the fire for a bit
            itemEntity.hurt(itemEntity.damageSources().inFire(), -100);

            // Actually set it on fire
            itemEntity.setRemainingFireTicks(10);
            level.addFreshEntity(itemEntity);
            didDrop = true;
        }

        if (didDrop) {
            // Play explosion sound
            if (BaseConfig.COMMON.INFINITY.MAKES_SOUND.get()) {
                level.playSound(null, pos, SoundEvents.FIREWORK_ROCKET_LARGE_BLAST, SoundSource.BLOCKS, 1.0f,
                    randomSource.nextFloat() * 0.4f + 0.8f);
            }

            // Replace the base (if applicable)
            if (recipe.blockAfterBurning().isPresent()) {
                level.setBlock(pos.below(), recipe.blockAfterBurning().get().defaultBlockState(), Block.UPDATE_ALL);
            }
        }
    }

