public static boolean doMiscMagicAttack(@Nullable Entity attacker, Entity target, float dmg, @Nullable Vec3 position) {
		return safelyDealDamage(position == null ? attacker == null ?
												   miscDamage(AoADamageTypes.MAGIC_ATTACK, target.level()) :
												   entityDamage(AoADamageTypes.MAGIC_ATTACK, attacker) :
								positionedEntityDamage(AoADamageTypes.MAGIC_ATTACK, attacker, position), target, dmg);
	}

public static boolean safelyDealDamage(DamageSource damageSource, Entity target, float dmg) {
		return safelyDealDamage(damageSource, target, dmg, true);
	}

public static boolean safelyDealDamage(DamageSource damageSource, Entity target, float dmg, boolean ignoreMiscEntities) {
		if (!ignoreMiscEntities && !(target instanceof LivingEntity) && !(target instanceof PartEntity<?>) && !(target instanceof EndCrystal))
			return false;

		if (target.hurt(damageSource, dmg)) {
			if (damageSource.getEntity() instanceof LivingEntity attacker)
				attacker.setLastHurtMob(target);

			return true;
		}

		return false;
	}

public static List<LivingEntity> getEntityLivingBaseNearby(LivingEntity livingEntity, double distanceX, double distanceY, double distanceZ, double radius) {
        return getEntitiesNearby(livingEntity, LivingEntity.class, distanceX, distanceY, distanceZ, radius);
    }

public static void areaAttack(LivingEntity attacker, float range, float height, float arc, float damage, float hpDamage, int shieldBreak, DamageSource damageSource, boolean knockback) {
        areaAttack(attacker, range, height, arc, damage, hpDamage, shieldBreak, damageSource, knockback, null);
    }

public static void areaAttack(LivingEntity attacker, float range, float height, float arc, float damage, float hpDamage, int shieldBreak, DamageSource damageSource, boolean knockback, @Nullable Consumer<Entity> attackEffect) {
        List<LivingEntity> entitiesHit = getEntityLivingBaseNearby(attacker, range, height, range, range);
        if (!attacker.level.isClientSide) {
            for (LivingEntity entityHit : entitiesHit) {
                float entityRelativeAngle = getRelativeAngle(attacker, entityHit);
                float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - attacker.getZ()) * (entityHit.getZ() - attacker.getZ()) + (entityHit.getX() - attacker.getX()) * (entityHit.getX() - attacker.getX()));
                if (entityHitDistance <= range && (entityRelativeAngle <= arc / 2 && entityRelativeAngle >= -arc / 2) || (entityRelativeAngle >= 360 - arc / 2 || entityRelativeAngle <= -360 + arc / 2)) {
                    if (!areAllies(attacker, entityHit)) {
                        boolean flag = entityHit.hurt(damageSource, damage + (entityHit.getMaxHealth() * hpDamage));
                        if (entityHit.isDamageSourceBlocked(damageSource) && shieldBreak > 0) {
                            disableShield(entityHit, shieldBreak);
                        }
                        if (flag) {
                            double d0 = entityHit.getX() - attacker.getX();
                            double d1 = entityHit.getZ() - attacker.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            if (knockback) {
                                entityHit.push(d0 / d2 * 2.5D, 0.18D, d1 / d2 * 2.2D);
                            }
                            if (attackEffect != null) {
                                attackEffect.accept(entityHit);
                            }
                        }
                    }
                }
            }
        }
    }

public static float getRelativeAngle(LivingEntity attacker, LivingEntity entityHit) {
        float entityHitAngle = (float) ((Math.atan2(entityHit.getZ() - attacker.getZ(), entityHit.getX() - attacker.getX()) * (180 / Math.PI) - 90) % 360);
        float entityAttackingAngle = attacker.yBodyRot % 360;
        if (entityHitAngle < 0) {
            entityHitAngle += 360;
        }
        if (entityAttackingAngle < 0) {
            entityAttackingAngle += 360;
        }
        return entityHitAngle - entityAttackingAngle;
    }

@Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, NetworkedParticleEffectExtraData extraData) {
        double posX = positionData.getPosX();
        double posY = positionData.getPosY();
        double posZ = positionData.getPosZ();
        Vec3 pos = new Vec3(posX, posY, posZ);
        for (int i = 0; i < 16; i++) {
            ColorParticleData color = colorData.getColor();
            float lifetimeMultiplier = Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 1.5f);
            float gravityStrength = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.03f, 0.06f);
            double horizontalAngle = random.nextDouble() * Math.PI * 2;
            double x = (Math.cos(horizontalAngle));
            double y = Mth.nextFloat(random, -1, 1);
            double z = (Math.sin(horizontalAngle));
            Vec3 direction = new Vec3(x, y, z);
            Vec3 motion = direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 2f, 3f));
            Vec3 spawnPosition = pos.add(direction.scale(0.25f));
            final Consumer<LodestoneWorldParticle> sparkBehavior = p -> {
                Vec3 velocity = p.getParticleSpeed().scale(0.75f);
                if (velocity.equals(Vec3.ZERO)) {
                    velocity = p.getParticleSpeed();
                }
                p.setParticleSpeed(velocity.x, (velocity.y - gravityStrength) * 0.98f, velocity.z);
                if (p.getAge() < p.getLifetime() * 0.7f) {
                    if (level.getGameTime() % 2 == 0) {
                        var lightSpecs = spiritLightSpecs(level, p.getParticlePosition(), p.colorData);
                        lightSpecs.getBuilder()
                                .multiplyLifetime(lifetimeMultiplier / 2f)
                                .enableForcedSpawn();
                        lightSpecs.getBloomBuilder()
                                .multiplyLifetime(lifetimeMultiplier / 4f);
                        lightSpecs.spawnParticles();
                    }
                }
            };
            float scalar = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.8f, 1.1f);
            var sparks = SparkParticleEffects.spiritMotionSparks(level, spawnPosition, color).act(b -> b.getParticleOptions().setBehavior(SparkParticleBehavior.sparkBehavior()));
            sparks.getBuilder()
                    .setLengthData(GenericParticleData.create(3f * scalar, 0.75f * scalar, 0f).setEasing(Easing.QUARTIC_OUT, Easing.SINE_IN_OUT).build())
                    .setScaleData(GenericParticleData.create(0.4f * scalar, 0.2f * scalar, 0f).setEasing(Easing.SINE_IN, Easing.QUAD_IN).build())
                    .multiplyLifetime(lifetimeMultiplier)
                    .addTickActor(sparkBehavior)
                    .enableForcedSpawn()
                    .setMotion(motion);
            sparks.getBloomBuilder()
                    .modifyScaleData(d -> d.multiplyValue(2f))
                    .multiplyLifetime(lifetimeMultiplier)
                    .addTickActor(sparkBehavior)
                    .setMotion(motion);
            sparks.spawnParticles();
        }
        final SpinParticleData spinData = SpinParticleData.createRandomDirection(random, nextFloat(random, 0.05f, 0.1f)).randomSpinOffset(random).build();
        float scaleMultiplier = (float) (1 + Math.pow(random.nextFloat(), 2) * 0.5f);
        WorldParticleBuilder.create(MalumParticles.GIANT_GLOWING_STAR.get())
                .setTransparencyData(GenericParticleData.create(0.9f, 0.07f, 0).setEasing(Easing.SINE_IN, Easing.CIRC_IN).build())
                .setLifetime(15)
                .setSpinData(spinData)
                .setScaleData(GenericParticleData.create(5f * scaleMultiplier, 0.5f, 0).setEasing(Easing.EXPO_OUT, Easing.SINE_IN).build())
                .setColorData(colorData.getColor())
                .setRandomOffset(0.6f)
                .enableNoClip()
                .setRandomMotion(0.02f, 0.02f)
                .repeat(level, posX, posY, posZ, 3);
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, UnwindingChaosChargeEffectData extraData) {
        final Entity entity = level.getEntity(extraData.entityId);
        if (entity != null) {
            var smokeColor = new Color(45, 15, 15);
            long gameTime = level.getGameTime();
            var pos = positionData.getAsVector();
            var direction = pos.subtract(entity.position()).normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            Vec3 up = left.cross(direction);

            Consumer<LodestoneWorldParticle> behavior = p -> {
                Vec3 distance = entity.position().add(0, entity.getBbHeight() / 2f, 0).subtract(p.getParticlePosition());
                if (distance.length() == 0) {
                    distance = new Vec3(0, 0.02f, 0);
                }
                float delta = Math.max(p.getAge() / (float) p.getLifetime(), 0);
                float lerp = Easing.QUINTIC_IN_OUT.lerp(delta, 0.05f, 0.5f);
                float velocity = (float) Easing.CIRC_IN.lerp(delta, 0.05f, 0.2f + distance.length() * 1.2f);
                final Vec3 speed = p.getParticleSpeed().lerp(distance.normalize().scale(velocity), lerp);
                p.setParticleSpeed(speed);
            };

            for (int i = 0; i < 16; i++) {
                SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
                float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.6f);
                float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float angle = i / 16f * (float) Math.PI * 2f;
                Vec3 particleDirection = direction
                        .add(left.scale(Math.sin(angle) * spread))
                        .add(up.scale(Math.cos(angle) * spread))
                        .normalize().scale(speed);
                Vec3 particlePosition = pos.add(particleDirection.scale(2f));
                var lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(MalumParticles.SPARK.get()));
                var transparencyData = GenericParticleData.create(0.4f, 0.8f, 0f).setEasing(Easing.SINE_IN_OUT, Easing.EXPO_IN_OUT).build();
                int lifeDelay = i * 2;
                int lifetime = 20;
                lightSpecs.getBuilder()
                        .setBehavior(SparkParticleBehavior.sparkBehavior())
                        .setLengthData(GenericParticleData.create(0.2f, 2f, 0f).setEasing(Easing.SINE_IN, Easing.SINE_IN_OUT).build())
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 2, 2.5f)))
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior);
                lightSpecs.getBloomBuilder()
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior)
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.7f, 1.1f)))
                        .modifyTransparencyData(d -> d.multiplyCoefficient(1.4f));
                lightSpecs.spawnParticles();

                lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(LodestoneParticleTypes.WISP_PARTICLE.get()));
                transparencyData = GenericParticleData.create(1f, 0f).setCoefficient(1.5f).build();
                lightSpecs.getBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .setColorData(ColorParticleData.create(smokeColor).build())
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .addTickActor(behavior)
                        .setLifetime(lifetime);
                lightSpecs.spawnParticlesRaw();
            }
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();
		if (isAIDisabled()) return;

		if ((ticksExisted % RandUtil.nextInt(100, 200)) == 0)
			playSound(ModSounds.HALLOWED_SPIRIT, RandUtil.nextFloat(), RandUtil.nextFloat());

		fallDistance = 0;

		EntityPlayer farPlayer = world.getNearestPlayerNotCreative(this, 300);
		setAttackTarget(farPlayer);
		if (getAttackTarget() != null) {
			noClip = true;
			Vec3d direction = getPositionVector().subtract(getAttackTarget().getPositionVector()).normalize();
			motionX = direction.x * -0.1;
			motionY = direction.y * -0.1;
			motionZ = direction.z * -0.1;
			rotationYaw = (float) (((-MathHelper.atan2(direction.x, direction.z) * 180) / Math.PI) - 180) / 2;
		} else {
			if (!collidedVertically) {
				motionY = 0;
			}
			noClip = false;
		}

		EntityPlayer player = getAttackTarget() == null ? null : world.getNearestPlayerNotCreative(this, 2);
		EntityPlayer closePlayer = getAttackTarget() == null ? null : world.getNearestPlayerNotCreative(this, 30);
		boolean angry = player != null;

		ClientRunnable.run(new ClientRunnable() {
			@Override
			@SideOnly(Side.CLIENT)
			public void runIfClient() {
				if ((closePlayer != null) && !angry)
					LibParticles.SPIRIT_WIGHT_FLAME_FAR(world, getPositionVector().add(0, getEyeHeight(), 0));
				else if (angry)
					LibParticles.SPIRIT_WIGHT_FLAME_CLOSE(world, getPositionVector().add(0, getEyeHeight(), 0));
				else LibParticles.SPIRIT_WIGHT_FLAME_NORMAL(world, getPositionVector().add(0, getEyeHeight(), 0));
			}
		});

		if (angry) {
			player.attackEntityFrom(DamageSource.MAGIC, 0.15f);
			player.hurtResistantTime = 0;
		}
	}

@Override
	public void onUseTick(Level level, LivingEntity living, ItemStack stack, int count) {
		Cataclysm.PROXY.playWorldSound(living, (byte) 1);

		if (level instanceof ServerLevel serverLevel) {
			double range = 2.5D;
			Vec3 srcVec = living.getEyePosition();
			Vec3 lookVec = living.getViewVector(1.0F);

			Vec3 lookOffset = lookVec.scale(range);
			Vec3 destVec = srcVec.add(lookOffset);

			double padding = 1.0D;
			AABB searchArea = living.getBoundingBox().expandTowards(lookOffset).inflate(padding);
			List<Entity> possibleList = level.getEntities(living, searchArea);
			DamageSource shredderDamage = CMDamageTypes.causeShredderDamage(living);
			float basedmg = AttributeUtils.OriginDamage(living, stack);

			for (Entity entity : possibleList) {
				if (entity instanceof LivingEntity target) {
					double borderSize = 0.5D;
					AABB collisionBB = target.getBoundingBox().inflate(borderSize);
					boolean isHit = collisionBB.contains(srcVec) || collisionBB.clip(srcVec, destVec).isPresent();

					if (isHit) {
						float bonusDamage = EnchantmentHelper.getDamageBonus(stack, target.getMobType());
						float enchanteddmg = basedmg + bonusDamage;

						float finaldmg = enchanteddmg / 8.5F;
						if (target.hurt(shredderDamage, finaldmg)) {
							serverLevel.sendParticles(
									new ParryParticleOptions(255, 106, 0),
									target.getX(),
									target.getY(0.5),
									target.getZ(),
									2,
									target.getDeltaMovement().x,
									target.getDeltaMovement().y,
									target.getDeltaMovement().z,
									(level.getRandom().nextFloat() - 0.5F)
							);
						}
					}
				}
			}
		}
	}

public InteractionResult mobInteract(Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        Item item = itemstack.getItem();
        InteractionResult type = super.mobInteract(player, hand);
        if(item == Items.SNOW && !this.isSnowy() && !this.level().isClientSide){
            this.usePlayerItem(player, hand, itemstack);
            this.permSnow = true;
            this.setSnowy(true);
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.SNOW_PLACE, this.getSoundVolume(), this.getVoicePitch());
            return InteractionResult.SUCCESS;
        }
        if(item instanceof ShovelItem && this.isSnowy() && !this.level().isClientSide){
            this.permSnow = false;
            if(!player.isCreative()){
                itemstack.hurt(1, this.getRandom(), player instanceof ServerPlayer ? (ServerPlayer)player : null);
            }
            this.setSnowy(false);
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.SNOW_BREAK, this.getSoundVolume(), this.getVoicePitch());
            return InteractionResult.SUCCESS;
        }
        InteractionResult interactionresult = itemstack.interactLivingEntity(player, this, hand);
        if (interactionresult != InteractionResult.SUCCESS && type != InteractionResult.SUCCESS && isTame() && isOwnedBy(player) && !isFood(itemstack)){
            if(!player.isShiftKeyDown() && !this.isBaby()){
                player.startRiding(this);
                return InteractionResult.SUCCESS;
            }else{
                this.setCommand((this.getCommand() + 1) % 3);

                if (this.getCommand() == 3) {
                    this.setCommand(0);
                }
                player.displayClientMessage(Component.translatable("entity.alexsmobs.all.command_" + this.getCommand(), this.getName()), true);
                boolean sit = this.getCommand() == 2;
                if (sit) {
                    this.forcedSit = true;
                    this.setOrderedToSit(true);
                    return InteractionResult.SUCCESS;
                } else {
                    this.forcedSit = false;
                    this.setOrderedToSit(false);
                    return InteractionResult.SUCCESS;
                }
            }
        }
        return type;
    }

@Override
    public boolean hurt(DamageSource p_37849_, float p_37850_) {
        if (!this.level.isClientSide) {
            if (this.hasStaff() && this.isAggressive() && !this.isCasting() && this.coolDown <= 10) {
                if (this.staffDamage >= 64) {
                    this.setHasStaff(false);
                    this.level.broadcastEntityEvent(this, (byte) 13);
                    if (this.level instanceof ServerLevel serverLevel) {
                        for (int i = 0; i < 20; ++i) {
                            ServerParticleUtil.addParticlesAroundSelf(serverLevel, new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(ModItems.DARK_FABRIC.get())), this);
                        }
                    }
                    if (p_37849_.getEntity() != null) {
                        MobUtil.knockBack(this, p_37849_.getEntity(), 4.0D, 0.2D, 4.0D);
                    }
                    this.playSound(SoundEvents.ITEM_BREAK, 4.0F, 1.0F);
                    return false;
                } else if (!p_37849_.is(DamageTypeTags.BYPASSES_INVULNERABILITY)
                        && !p_37849_.is(DamageTypeTags.BYPASSES_EFFECTS)
                        && !p_37849_.is(DamageTypeTags.BYPASSES_ENCHANTMENTS)
                        && !p_37849_.is(DamageTypeTags.IS_EXPLOSION)
                        && !p_37849_.isCreativePlayer()
                        && !MobUtil.areAllies(p_37849_.getEntity(), this)
                        && p_37849_.getEntity() != null) {
                    Vec3 vec32 = p_37849_.getSourcePosition();
                    if (vec32 != null) {
                        MobUtil.instaLook(Minister.this, vec32);
                        if (ModDamageSource.toolAttack(p_37849_, item -> item instanceof AxeItem)) {
                            p_37850_ *= 2.0F;
                        }
                        this.staffDamage += p_37850_;
                        this.level.broadcastEntityEvent(this, (byte) 8);
                        this.playSound(SoundEvents.SHIELD_BLOCK);
                        if (this.level instanceof ServerLevel serverLevel) {
                            for (int i = 0; i < 5; ++i) {
                                ServerParticleUtil.addParticlesAroundSelf(serverLevel, new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(ModItems.DARK_FABRIC.get())), this);
                            }
                        }
                        if (this.level.random.nextFloat() <= 0.05F) {
                            this.playSound(ModSounds.MINISTER_LAUGH.get());
                        }
                    }
                    return false;
                }
            }
        }
        return super.hurt(p_37849_, p_37850_);
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int range = spellStat.getRange();
        float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            }
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);
		BlockPos pos = spell.getTargetPos();

		if (pos == null) return false;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell) / 2;

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {

			PotionEffect slowness = ((EntityLivingBase) targetEntity).getActivePotionEffect(MobEffects.SLOWNESS);
			PotionEffect frost = ((EntityLivingBase) targetEntity).getActivePotionEffect(ModPotions.SLIPPERY);
			int mult = 0;
			if (slowness != null)
				mult += slowness.getAmplifier() + 1;
			if (frost != null)
				mult += frost.getAmplifier() + 1;
			potency *= 1 + mult * 0.5;

			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;

			world.playSound(null, pos, ModSounds.MARBLE_EXPLOSION, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			world.playSound(null, pos, ModSounds.FIREWORK, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			if (caster instanceof EntityLivingBase)
			{
				((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);
				if (caster instanceof EntityPlayer)
					targetEntity.attackEntityFrom(DamageSource.causePlayerDamage((EntityPlayer) caster).setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);
			}
			else
				targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);

			targetEntity.hurtResistantTime = invTime;
		}

		// TODO: EffectShatter Sound
//		Vec3d target = spell.getTargetWithFallback();
//		if (target != null)
//			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, SoundCategory.NEUTRAL, 0.5f, 1f);
		return true;
	}

public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        prevangryProgress = angryProgress;
        if (this.isAggressive() && angryProgress < 10F) {
            angryProgress++;
        }
        if (!this.isAggressive() && angryProgress > 0F) {
            angryProgress--;
        }
        LivingEntity target = this.getTarget();
        if(this.isAlive()) {
            if (this.getAnimation() == COBOLETON_ATTACK) {
                if (this.getAnimationTick() == 11) {
                    this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                    if (target != null) {
                        if (this.distanceTo(target) < this.getBbWidth() * 2.5F * this.getBbWidth() * 2.5F + target.getBbWidth()) {
                            float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            target.hurt(damageSources().mobAttack(this), damage);

                            ItemStack offhand = target.getOffhandItem();
                            ItemStack mainhand = target.getMainHandItem();
                            Optional<SlotResult> slot = CuriosApi.getCuriosHelper().findFirstCurio(target, stack -> stack.is(ModItems.STICKY_GLOVES.get()));
                            if(this.random.nextFloat() * 100.0F <= (float)CMCommonConfig.Koboleton.CauseKoboletontoDropItemInHandPercent) {
                                if (slot.isEmpty()) {
                                    if (!offhand.isEmpty()) {
                                        if (!offhand.is(ModTag.STICKY_ITEM)) {
                                            int i = offhand.getCount();
                                            this.koboletonstealdrop(offhand.copyWithCount(1), target);
                                            target.setItemSlot(EquipmentSlot.OFFHAND, offhand.split(i - 1));
                                        }
                                    } else {
                                        if (!mainhand.isEmpty()) {
                                            if (!mainhand.is(ModTag.STICKY_ITEM)) {
                                                int i = mainhand.getCount();
                                                this.koboletonstealdrop(mainhand.copyWithCount(1), target);
                                                target.setItemSlot(EquipmentSlot.MAINHAND, mainhand.split(i - 1));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void tick(){
        super.tick();
        this.prevOnLandProgress = onLandProgress;
        boolean onLand = !this.isInWaterOrBubble() && this.onGround();
        if (onLand && onLandProgress < 5F) {
            onLandProgress++;
        }
        if (!onLand && onLandProgress > 0F) {
            onLandProgress--;
        }
        float targetXRot = 0;
        if(this.getDeltaMovement().length() > 0.09){
            targetXRot = -((float)(Mth.atan2(this.getDeltaMovement().y, this.getDeltaMovement().horizontalDistance()) * (double)Mth.RAD_TO_DEG));
        }
        if(targetXRot < this.getXRot() - 5){
            targetXRot = this.getXRot() - 5;
        }
        if(targetXRot > this.getXRot() + 5){
            targetXRot = this.getXRot() + 5;
        }
        this.setXRot(targetXRot);
        if (!this.level().isClientSide && this.getTarget() != null && this.distanceTo(this.getTarget()) < 2.0F + this.getTarget().getBbWidth()) {
            this.lookAt(this.getTarget(), 350, 200);
            if(this.getAnimation() == ANIMATION_STAB && this.getAnimationTick() == 7 && this.hasLineOfSight(this.getTarget())){
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
            if(this.getAnimation() == ANIMATION_SLASH && this.getAnimationTick() % 5 == 0 && this.getAnimationTick() > 0 && this.getAnimationTick() < 25 && this.hasLineOfSight(this.getTarget())){
                for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getTarget().getBoundingBox().inflate(2.0D))) {
                    if (!entity.isPassengerOfSameVehicle(this) && entity != this && !entity.isAlliedTo(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue() * 0.5F);
                    }
                }
            }
        }
        if(onLandProgress >= 5.0F && this.isVehicle()){
            this.ejectPassengers();
        }
        if(!isInWaterOrBubble()){
            if (this.onGround() && random.nextFloat() < 0.2F) {
                this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
                this.setYRot(this.random.nextFloat() * 360.0F);
                this.playSound(AMSoundRegistry.SKELEWAG_HURT.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public static void consume(SThunderBoltPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Vec3 start = new Vec3(packet.x, packet.y, packet.z);
            Vec3 end = new Vec3(packet.x2, packet.y2, packet.z2);
            ColorUtil colorUtil = new ColorUtil(packet.red, packet.green, packet.blue);
            Goety.PROXY.thunderBolt(start, end, colorUtil, packet.lifespan);
        });
        ctx.get().setPacketHandled(true);
    }

